def validate_build_manifest_before_startup():
    global BUILD_MANIFEST, BUILD_MANIFEST_VALIDATION
    manifest_root = Path(__file__).resolve().parent
    manifest, validation = validate_or_raise(
        root=manifest_root,
        manifest_path=manifest_root / MANIFEST_FILENAME,
        context=build_manifest_context(),
        # Production must never mint a replacement identity while starting.
        # Docker/release packaging owns manifest generation; runtime verifies it.
        repair_missing=False,
    )
    BUILD_MANIFEST = dict(manifest)
    BUILD_MANIFEST_VALIDATION = validation.to_dict()
    return BUILD_MANIFEST_VALIDATION


def build_manifest_health_snapshot():
    return {
        "manifest": dict(BUILD_MANIFEST or {}),
        "validation": dict(BUILD_MANIFEST_VALIDATION or {"status": "not_validated"}),
    }


