def compact_worker_health_snapshot():
    supervisor_workers = {}
    if V20_SERVICES is not None:
        with contextlib.suppress(Exception):
            supervisor_workers = (
                V20_SERVICES.workers.snapshot().get("workers", {})
            )
    with active_worker_jobs_lock:
        active_snapshot = deepcopy(active_worker_jobs)
    worker_ids = set(supervisor_workers) | set(active_snapshot)
    for prefix, count, worker_type in (
        ("DL W", DOWNLOAD_WORKERS, "downloader"),
        ("UP W", UPLOAD_WORKERS, "uploader"),
        ("LINK W", LINK_WORKERS, "link"),
        ("BUTTON W", BUTTON_WORKERS, "button"),
    ):
        for index in range(1, max(1, count) + 1):
            worker_ids.add(f"{prefix}{index}")
    workers = []
    now_ts = time.time()
    for worker_id in sorted(worker_ids):
        state = dict(supervisor_workers.get(worker_id, {}))
        active = dict(active_snapshot.get(worker_id, {}))
        started_at = float(active.get("started_at") or state.get("started_at") or now_ts)
        runtime = max(0.0, now_ts - started_at) if active else 0.0
        status = "busy" if active else str(state.get("status") or "waiting")
        workers.append(
            {
                "worker_id": worker_id,
                "worker_type": str(state.get("worker_type") or active.get("source") or ""),
                "status": status,
                "busy": bool(active),
                "idle": not bool(active),
                "running": str(state.get("status") or "") == "running" or bool(active),
                "waiting": not bool(active),
                "blocked": False,
                "restart_count": int(state.get("restart_count") or 0),
                "processed_jobs": 0,
                "failed_jobs": 0,
                "average_duration": 0.0,
                "current_job": active.get("job_id", ""),
                "last_heartbeat": float(state.get("heartbeat_at") or active.get("last_progress_at") or 0.0),
                "maximum_runtime": runtime,
            }
        )
    return workers


def compact_queue_health_snapshot():
    sizes = current_queue_sizes()
    peak_wait = dict((RUNTIME_METRICS.get("queue_wait_peak_seconds") or {}))
    pressure = local_media_pressure() if "local_media_pressure" in globals() else 0
    oldest = {}
    for name, queue_obj in (("download", channel_download_queue), ("upload", upload_queue)):
        with contextlib.suppress(Exception):
            entries = getattr(queue_obj, "checkpoint_entries", lambda: [])()
            ages = [
                max(0.0, time.monotonic() - float((entry.get("job") or {}).get("_queued_monotonic") or time.monotonic()))
                for entry in entries
            ]
            oldest[name] = max(ages or [0.0])
    return {
        name: {
            "current_size": int(size),
            "peak_size": int(size),
            "oldest_job": oldest.get(name, 0),
            "admission_rate": 0.0,
            "drain_rate": 0.0,
            "pressure": pressure,
            "average_wait_peak": peak_wait.get(name, 0.0),
        }
        for name, size in sizes.items()
    }


def compact_database_health_snapshot():
    return {
        "backend": "sqlite",
        "sqlite_integrity": "degraded" if DB_DEGRADED else "ok",
        "journal_mode": DB_JOURNAL_MODE,
        "busy_count": int(RUNTIME_METRICS.get("slow_db_operations") or 0),
        "write_latency": 0,
        "commit_latency": 0,
        "rollback_count": int(RUNTIME_METRICS.get("upload_session_resets") or 0),
        "open_connections": 0,
        "last_maintenance": str(DB_LAST_READY_AT or ""),
        "recovery_active": bool(DB_RECOVERY_ACTIVE),
        "schema_version": SQLITE_SCHEMA_VERSION,
    }


def compact_source_health_snapshot(limit=200):
    items = []
    with contextlib.suppress(Exception):
        for item in active_channel_state_items()[: max(1, int(limit))]:
            status = str(item.get("status") or "active")
            items.append(
                {
                    "source": item.get("channel_id", ""),
                    "title": item.get("title", ""),
                    "healthy": status == "active",
                    "cooldown": item.get("next_check_at", ""),
                    "circuit_breaker": item.get("circuit_open_until", ""),
                    "pending_jobs": 0,
                    "failures": int(item.get("failure_count") or item.get("consecutive_failures") or 0),
                    "last_success": item.get("last_success_at", ""),
                    "last_failure": item.get("last_failure_at", ""),
                }
            )
    return items


