def incident_context(job=None, worker_name="", queue_name="", exception=None):
    payload = {
        "worker": worker_name,
        "queue": queue_name,
        "queue_sizes": current_queue_sizes(),
        "checkpoint_state": {
            "dirty": bool(RUNTIME_CHECKPOINT_DIRTY),
            "last_written": float(RUNTIME_CHECKPOINT_LAST_WRITTEN or 0.0),
        },
        "recovery_state": {
            "queue_ready": bool(QUEUE_RECOVERY_READY.is_set()),
            "reserved_jobs": persisted_queue_reservations.owner_count(),
        },
        "database_state": compact_database_health_snapshot(),
        "manifest_version": (BUILD_MANIFEST or {}).get("manifest_version", 1),
        "build_identity": {
            "build_id": (BUILD_MANIFEST or {}).get("build_id", ""),
            "build_number": (BUILD_MANIFEST or {}).get("build_number", ""),
            "validation_status": (BUILD_MANIFEST_VALIDATION or {}).get(
                "status", "not_validated"
            ),
            "boot_id": BOOT_ID,
            "validator_schema": MEDIA_VALIDATOR_SCHEMA_VERSION,
        },
    }
    if isinstance(job, dict):
        messages = job.get("messages") or []
        first_message = messages[0] if messages else None
        if isinstance(first_message, dict):
            message_id = first_message.get("message_id", "")
            chat_id = first_message.get("chat_id", "")
            media_uid = first_message.get("media_uid", "")
            album_id = first_message.get("media_group_id", "")
        else:
            message_id = getattr(first_message, "id", "") if first_message else ""
            chat = getattr(first_message, "chat", None) if first_message else None
            chat_id = getattr(chat, "id", "") if chat else ""
            media_uid = get_media_uid(first_message) if first_message else ""
            album_id = (
                getattr(first_message, "media_group_id", "")
                if first_message
                else ""
            )
        payload.update(
            {
                "job_id": job.get("job_id", ""),
                "source": job.get("ch_name") or job.get("source", ""),
                "target": TARGET_CHAT_ID,
                "retry_count": int(job.get("attempt") or 0),
                "message_id": message_id,
                "chat_id": chat_id,
                "media_uid": media_uid,
                "album_id": str(album_id or ""),
                "telegram_method": str(
                    job.get("_telegram_method")
                    or job.get("_delivery_operation")
                    or ""
                ),
            }
        )
    if exception is not None:
        payload["telegram_error"] = format_exception_for_log(exception) if "format_exception_for_log" in globals() else str(exception)
    return payload


def record_production_incident(
    incident_type,
    severity="warning",
    subsystem="runtime",
    *,
    job=None,
    worker_name="",
    queue_name="",
    exception=None,
    recovery=None,
    snapshots=None,
    rate_limit_key="",
):
    with contextlib.suppress(Exception):
        system = production_intelligence_system()
        return system.record_incident(
            incident_type=incident_type,
            severity=severity,
            subsystem=subsystem,
            context=incident_context(job, worker_name, queue_name, exception),
            exception=exception,
            recovery=recovery,
            snapshots=snapshots or {
                "worker_snapshot": compact_worker_health_snapshot(),
                "queue_snapshot": compact_queue_health_snapshot(),
                "runtime_snapshot": {
                    "metrics": runtime_metrics_snapshot(),
                    "phase": PIPELINE_SCAN_STATUS.get("phase", ""),
                },
                "configuration_snapshot": {
                    "deployment_profile": "huggingface-space" if IS_HUGGINGFACE_SPACE else "local",
                    "features": build_manifest_context(),
                },
            },
            rate_limit_key=rate_limit_key,
        )
    return {}


def maybe_record_incident_from_log(text):
    lowered = str(text).lower()
    if "incident manifest" in lowered:
        return
    if "dead media skip list" in lowered or "restore 85%: loaded target index" in lowered:
        return
    with contextlib.suppress(Exception):
        production_intelligence_system().record_from_log(
            str(text),
            context=incident_context(),
            snapshots={
                "queue_snapshot": compact_queue_health_snapshot(),
                "database_snapshot": compact_database_health_snapshot(),
                "runtime_snapshot": {"phase": PIPELINE_SCAN_STATUS.get("phase", "")},
            },
        )


async def health_manifest_loop():
    production_intelligence_system().ensure()
    while True:
        try:
            payload = build_health_manifest_payload()
            await run_blocking(
                "persistence",
                production_intelligence_system().write_health_manifest,
                payload,
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            record_production_incident(
                "Checkpoint Failure",
                "error",
                "health_manifest",
                exception=exc,
                recovery={"attempted": True, "successful": False, "failed": True},
                rate_limit_key="health_manifest_write_failure",
            )
        await asyncio.sleep(HEALTH_MANIFEST_REFRESH_SECONDS)


def v21_existing_recovery_file_paths(checkpoint_payload=None):
    """Return only download-root artifacts still owned by recoverable work.

    Boot cleanup runs before the Telegram clients and queue workers have restored
    their in-memory ownership.  A persisted ``queued_upload`` file is therefore
    live at that point even though it is not yet present in ``active_download_files``.
    Protecting it avoids a needless fresh download (and the local-file-missing
    race that follows), while terminal records remain eligible for normal cleanup.
    """
    paths = set()
    payload = checkpoint_payload if isinstance(checkpoint_payload, dict) else {}
    for item in payload.get("temp_files", []) or []:
        if isinstance(item, dict) and item.get("path"):
            paths.add(str(item.get("path")))
    terminal_statuses = {
        "uploaded",
        "uploaded_partial",
        "failed",
        "failed_invalid_media",
        "failed_recoverable",
        "skipped_duplicate",
        "skipped_dead_media",
        "worker_fallback_queued",
    }
    with contextlib.suppress(Exception):
        with state_mutex:
            states = [
                deepcopy(STATE.get("upload_queue", {}).get("items", {})),
                deepcopy(STATE.get("download_queue", {}).get("items", {})),
            ]
        for records in states:
            for record in records.values():
                if not isinstance(record, dict):
                    continue
                if str(record.get("status") or "").lower() in terminal_statuses:
                    continue
                for key in (
                    "files",
                    "_partial_download_files",
                    "partial_download_files",
                ):
                    for path in record.get(key, []) or []:
                        if path:
                            paths.add(str(path))
    return paths


def run_v21_startup_cleanup(checkpoint_payload=None):
    result = {"deleted": 0, "freed": 0, "skipped": 0, "protected": 0}
    recovery_paths = v21_existing_recovery_file_paths(checkpoint_payload)
    if PURGE_DOWNLOADS_ON_BOOT:
        purge_result = purge_download_root_on_boot(protected_paths=recovery_paths)
        result.update(
            {
                "deleted": result["deleted"] + int(purge_result.get("deleted") or 0),
                "freed": result["freed"] + int(purge_result.get("freed") or 0),
                "skipped": result["skipped"] + int(purge_result.get("skipped") or 0),
                "protected": result["protected"] + int(purge_result.get("protected") or 0),
            }
        )
    if V21_ENGINE is None or not V21_CLEANUP_STALE_TEMP_ON_BOOT:
        return result
    sweep_result = V21_ENGINE.cleanup_engine.startup_sweep(
        protected_paths=tuple(important_runtime_paths()) + tuple(recovery_paths),
    )
    return {
        "deleted": result["deleted"] + int(sweep_result.get("deleted") or 0),
        "freed": result["freed"] + int(sweep_result.get("freed") or 0),
        "skipped": result["skipped"] + int(sweep_result.get("skipped") or 0),
        "protected": result["protected"] + int(sweep_result.get("protected") or 0),
    }


def important_runtime_paths():
    paths = {SESSION_DIR, STATE_DIR, RUNTIME_DIR / "royells.db"}
    paths.update(STATE_FILES.values() if "STATE_FILES" in globals() else [])
    paths.update(
        path
        for path in (
            RUNTIME_CHECKPOINT_FILE if "RUNTIME_CHECKPOINT_FILE" in globals() else None,
            DELIVERY_INTENT_FILE if "DELIVERY_INTENT_FILE" in globals() else None,
            MEDIA_LEDGER_FILE if "MEDIA_LEDGER_FILE" in globals() else None,
        )
        if path
    )
    return tuple(paths)


def purge_download_root_on_boot(protected_paths=()):
    """Remove stale boot artifacts without deleting files owned by recovered jobs.

    ``protected_paths`` is intentionally narrowed to descendants of
    ``DOWNLOAD_DIR``.  Checkpoint data is untrusted/stale input and must never
    influence cleanup outside the dedicated media spool.
    """
    try:
        root = DOWNLOAD_DIR.resolve(strict=False)
        protected_roots = [
            DATA_DIR.resolve(strict=False),
            RUNTIME_DIR.resolve(strict=False),
            STATE_DIR.resolve(strict=False),
            SESSION_DIR.resolve(strict=False),
        ]
        unsafe = any(root == protected or root in protected.parents for protected in protected_roots)
        if unsafe:
            log_event(f"Startup download purge skipped: unsafe download root {root}.")
            return {"deleted": 0, "freed": 0, "skipped": 0, "protected": 1}
        if not root.exists():
            root.mkdir(parents=True, exist_ok=True)
            return {"deleted": 0, "freed": 0, "skipped": 0, "protected": 0}
        protected_files = set()
        for raw_path in protected_paths or ():
            if not raw_path:
                continue
            with contextlib.suppress(Exception):
                candidate = Path(str(raw_path)).expanduser().resolve(strict=False)
                if candidate != root and root in candidate.parents:
                    protected_files.add(candidate)
        deleted = 0
        freed = 0
        skipped = 0
        for item in sorted(root.rglob("*"), key=lambda path: len(path.parts), reverse=True):
            try:
                resolved_item = item.resolve(strict=False)
                if resolved_item in protected_files:
                    skipped += 1
                    continue
                if item.is_file():
                    size = int(item.stat().st_size)
                    item.unlink(missing_ok=True)
                    deleted += 1
                    freed += size
                elif item.is_dir() and item != root:
                    with contextlib.suppress(OSError):
                        item.rmdir()
            except Exception:
                skipped += 1
        if deleted or skipped:
            log_event(
                f"Startup download purge removed {deleted} reconstructable temp file(s), "
                f"freed {freed // (1024 * 1024)} MB, skipped={skipped}."
            )
        return {
            "deleted": deleted,
            "freed": freed,
            "skipped": skipped,
            "protected": len(protected_files),
        }
    except Exception as exc:
        log_event(f"Startup download purge failed safely: {format_exception_for_log(exc)}")
        return {"deleted": 0, "freed": 0, "skipped": 1, "protected": 0}


def choose_data_dir():
    candidates = []
    env_dir = os.getenv("ROYELLS_DATA_DIR")
    if env_dir:
        candidates.append(Path(env_dir).expanduser())
    if IS_HUGGINGFACE_SPACE:
        candidates.append(Path("/data") / DATA_FOLDER_NAME)

    # Visible in Android file managers when shared storage is mounted.
    candidates.append(Path.home() / "storage" / "shared" / DATA_FOLDER_NAME)
    candidates.append(Path.cwd() / DATA_FOLDER_NAME)

    for candidate in candidates:
        try:
            candidate.mkdir(parents=True, exist_ok=True)
            test_file = candidate / ".write_test"
            test_file.write_text("ok", encoding="utf-8")
            test_file.unlink(missing_ok=True)
            return candidate
        except Exception as e:
            continue

    fallback = Path.cwd() / DATA_FOLDER_NAME
    fallback.mkdir(parents=True, exist_ok=True)
    return fallback


def choose_runtime_dir():
    env_dir = os.getenv("ROYELLS_RUNTIME_DIR")
    candidates = []
    if env_dir:
        candidates.append(Path(env_dir).expanduser())
    if IS_HUGGINGFACE_SPACE:
        candidates.append(Path("/data") / DATA_FOLDER_NAME / "runtime")

    # Keep SQLite/session runtime away from Android shared storage.
    # /storage/shared often breaks SQLite file locking.
    candidates.append(Path.home() / ".royells_media_bot_runtime")
    candidates.append(Path.cwd() / ".royells_media_bot_runtime")

    for candidate in candidates:
        try:
            candidate.mkdir(parents=True, exist_ok=True)
            test_file = candidate / ".write_test"
            test_file.write_text("ok", encoding="utf-8")
            test_file.unlink(missing_ok=True)
            return candidate
        except Exception:
            continue

    fallback = Path.cwd() / ".royells_media_bot_runtime"
    fallback.mkdir(parents=True, exist_ok=True)
    return fallback


