class FairJobQueue:
    """Weighted-fair queue; late healthy sources can overtake a source backlog."""

    def __init__(self, maxsize, name="media"):
        self.maxsize = max(0, int(maxsize))
        self.name = str(name or "media")
        self._queue = asyncio.PriorityQueue(maxsize=self.maxsize)
        self._source_finish = {}
        self._served_floor = 0.0
        self._sequence = itertools.count()
        self._job_ids = set()

    @staticmethod
    def _source_key(job):
        source = str((job or {}).get("source") or "unknown")
        messages = (job or {}).get("messages") or []
        chat_id = ""
        if messages:
            chat_id = str(getattr(getattr(messages[0], "chat", None), "id", "") or "")
        return f"{source}:{chat_id or (job or {}).get('ch_name', '')}"

    @staticmethod
    def _cost(job):
        count = max(1, len((job or {}).get("messages") or []))
        source = str((job or {}).get("source") or "")
        weight = 4.0 if source == "telegram_link" else 1.0
        return min(10.0, float(count)) / weight

    def _entry(self, job):
        key = self._source_key(job)
        finish = max(float(self._source_finish.get(key, 0.0)), self._served_floor) + self._cost(job)
        self._source_finish[key] = finish
        return finish, next(self._sequence), job

    @staticmethod
    def _job_id(job):
        return str((job or {}).get("job_id") or "")

    async def put(self, job):
        job_id = self._job_id(job)
        if job_id and job_id in self._job_ids:
            metric_increment("queue_job_deduplications")
            return False
        await self._queue.put(self._entry(job))
        if job_id:
            self._job_ids.add(job_id)
        mark_runtime_checkpoint_dirty(f"{self.name} queue put")
        return True

    def put_nowait(self, job):
        job_id = self._job_id(job)
        if job_id and job_id in self._job_ids:
            metric_increment("queue_job_deduplications")
            return False
        self._queue.put_nowait(self._entry(job))
        if job_id:
            self._job_ids.add(job_id)
        mark_runtime_checkpoint_dirty(f"{self.name} queue put")
        return True

    async def get(self):
        finish, _sequence, job = await self._queue.get()
        job_id = self._job_id(job)
        if job_id:
            self._job_ids.discard(job_id)
        self._served_floor = max(self._served_floor, float(finish))
        if len(self._source_finish) > 10000:
            cutoff = self._served_floor - 100.0
            self._source_finish = {key: value for key, value in self._source_finish.items() if value >= cutoff}
        mark_runtime_checkpoint_dirty(f"{self.name} queue get")
        return job

    def qsize(self):
        return self._queue.qsize()

    def empty(self):
        return self._queue.empty()

    def full(self):
        return self._queue.full()

    def task_done(self):
        self._queue.task_done()

    async def join(self):
        await self._queue.join()

    def job_ids(self):
        return set(self._job_ids)

    def queued_jobs(self):
        return [
            entry[2]
            for entry in list(self._queue._queue)
            if len(entry) >= 3 and isinstance(entry[2], dict)
        ]

    def checkpoint_entries(self):
        return [
            {
                "finish": float(entry[0]),
                "sequence": int(entry[1]),
                "job": serialize_runtime_job(entry[2]),
            }
            for entry in sorted(list(self._queue._queue), key=lambda item: (item[0], item[1]))
            if len(entry) >= 3 and isinstance(entry[2], dict)
        ]

    def restore_checkpoint_entry(self, job, finish=None, sequence=None):
        if self.full():
            raise asyncio.QueueFull
        if finish is None or sequence is None:
            self.put_nowait(job)
            return
        finish = float(finish)
        sequence = int(sequence)
        job_id = self._job_id(job)
        if job_id and job_id in self._job_ids:
            metric_increment("queue_job_deduplications")
            return False
        self._queue.put_nowait((finish, sequence, job))
        if job_id:
            self._job_ids.add(job_id)
        self._source_finish[self._source_key(job)] = max(
            float(self._source_finish.get(self._source_key(job), 0.0)),
            finish,
        )
        self._served_floor = max(self._served_floor, min(self._served_floor, finish))
        self._sequence = itertools.count(max(sequence + 1, next(self._sequence)))
        mark_runtime_checkpoint_dirty(f"{self.name} queue checkpoint restore")
        return True


channel_download_queue = FairJobQueue(
    maxsize=IN_MEMORY_QUEUE_MAX,
    name="download",
)
upload_queue = FairJobQueue(
    maxsize=UPLOAD_READY_QUEUE_MAX,
    name="upload",
)
button_queue = asyncio.Queue(maxsize=0)
link_process_queue = asyncio.Queue(maxsize=0)
job_state_db_queue = asyncio.Queue(maxsize=max(100, env_int("ROYELLS_JOB_STATE_DB_QUEUE_LIMIT", "5000")))
critical_db_write_queue = asyncio.Queue(maxsize=max(100, env_int("ROYELLS_CRITICAL_DB_WRITE_QUEUE_LIMIT", "5000")))
DB_WRITE_BATCH_SIZE = max(1, min(500, env_int("ROYELLS_DB_WRITE_BATCH_SIZE", "100")))
retry_admission_queue = asyncio.PriorityQueue(maxsize=0)
RETRY_SEQUENCE = itertools.count()
RETRY_GENERATIONS = {}
RETRY_LOCK = asyncio.Lock()
# The retry scheduler must never hold the only copy of a delayed descriptor
# outside the priority queue.  Queue healing, checkpoints, and download-file
# protection all inspect this queue to decide whether a retry is already live.
# This event wakes the scheduler when a newly-enqueued retry has an earlier due
# time than the descriptor it is currently waiting to admit.
RETRY_SCHEDULER_WAKEUP = asyncio.Event()


def retry_key(queue_name, job):
    return f"{queue_name}:{(job or {}).get('job_id') or (job or {}).get('url') or id(job)}"


def retry_reason_text(reason):
    if isinstance(reason, BaseException):
        text = str(reason).strip()
        return f"{reason.__class__.__name__}: {text}" if text else reason.__class__.__name__
    return str(reason or "").strip()


def wake_retry_scheduler():
    """Wake the retry scheduler after the priority queue changes.

    The scheduler peeks delayed entries instead of removing one and sleeping.
    Keeping the descriptor in ``retry_admission_queue`` makes it visible to
    queue recovery and runtime checkpoints, while this event lets a short
    retry preempt an earlier long-delay wait without polling once per second.
    """

    RETRY_SCHEDULER_WAKEUP.set()


def peek_retry_admission_entry():
    """Return the next retry descriptor without transferring its ownership."""

    entries = getattr(retry_admission_queue, "_queue", ())
    return entries[0] if entries else None


def schedule_queue_retry(queue_name, job, delay_seconds=0, reason=""):
    key = retry_key(queue_name, job)
    if key in RETRY_GENERATIONS:
        metric_increment("retry_deduplications")
        return True
    generation = int(RETRY_GENERATIONS.get(key, 0)) + 1
    RETRY_GENERATIONS[key] = generation
    due = time.monotonic() + max(0, float(delay_seconds))
    reason_text = retry_reason_text(reason)
    entry = (due, next(RETRY_SEQUENCE), key, generation, queue_name, job, reason_text[:300])
    try:
        if V21_ENGINE is not None:
            V21_ENGINE.retry_manager.request(
                queue_name=queue_name,
                job=job,
                delay_seconds=delay_seconds,
                reason=reason_text,
            )
        retry_admission_queue.put_nowait(entry)
        wake_retry_scheduler()
        metric_increment(f"{queue_name}_retries")
        mark_runtime_checkpoint_dirty(f"retry scheduled {key}")
        return True
    except asyncio.QueueFull:
        RETRY_GENERATIONS.pop(key, None)
        log_event(f"Retry admission full; persisted for recovery: {key}")
        return False


async def retry_scheduler_loop():
    while True:
        entry = peek_retry_admission_entry()
        if entry is None:
            # Clear before checking again so a retry scheduled between the
            # first peek and ``wait`` still wakes us immediately.
            RETRY_SCHEDULER_WAKEUP.clear()
            if peek_retry_admission_entry() is None:
                await RETRY_SCHEDULER_WAKEUP.wait()
            continue

        due, _seq, key, generation, queue_name, job, reason = entry
        if RETRY_GENERATIONS.get(key) != generation:
            # A superseded checkpoint/retry entry is terminally stale.  It is
            # safe to discard because a newer generation owns the descriptor.
            with contextlib.suppress(asyncio.QueueEmpty):
                retry_admission_queue.get_nowait()
                retry_admission_queue.task_done()
            continue

        remaining = float(due) - time.monotonic()
        if remaining > 0:
            # Do not get() a future entry: doing so previously hid it from
            # queue healing for minutes and allowed the healer to re-admit the
            # same stale descriptor.  The re-peek closes the clear/wait race.
            RETRY_SCHEDULER_WAKEUP.clear()
            if peek_retry_admission_entry() != entry:
                continue
            try:
                await asyncio.wait_for(
                    RETRY_SCHEDULER_WAKEUP.wait(),
                    timeout=remaining,
                )
            except asyncio.TimeoutError:
                pass
            continue

        taken_entry = None
        try:
            # Only transfer ownership when the descriptor is due.  No await
            # occurs while it is held, so cancellation cannot lose a retry.
            taken_entry = retry_admission_queue.get_nowait()
            due, _seq, key, generation, queue_name, job, reason = taken_entry
            if RETRY_GENERATIONS.get(key) != generation:
                continue
            if queue_name == "download":
                target = channel_download_queue
            elif queue_name == "link":
                target = link_process_queue
            else:
                target = upload_queue
            if target.full():
                # Never block a worker or this scheduler on a full bounded queue.
                retry_admission_queue.put_nowait(
                    (
                        time.monotonic() + 2.0,
                        next(RETRY_SEQUENCE),
                        key,
                        generation,
                        queue_name,
                        job,
                        reason,
                    )
                )
                wake_retry_scheduler()
                continue
            stamp_queue_job(job, queue_name)
            target.put_nowait(job)
            RETRY_GENERATIONS.pop(key, None)
            mark_runtime_checkpoint_dirty(f"retry admitted {key}")
            log_event(f"Retry admitted: {key} reason={reason[:120]}")
        except asyncio.CancelledError:
            if (
                taken_entry is not None
                and RETRY_GENERATIONS.get(taken_entry[2]) == taken_entry[3]
            ):
                with contextlib.suppress(asyncio.QueueFull):
                    retry_admission_queue.put_nowait(taken_entry)
                    wake_retry_scheduler()
            raise
        except asyncio.QueueFull:
            if (
                taken_entry is not None
                and RETRY_GENERATIONS.get(taken_entry[2]) == taken_entry[3]
            ):
                with contextlib.suppress(asyncio.QueueFull):
                    retry_admission_queue.put_nowait(taken_entry)
                    wake_retry_scheduler()
        except Exception as exc:
            if (
                taken_entry is not None
                and RETRY_GENERATIONS.get(taken_entry[2]) == taken_entry[3]
            ):
                with contextlib.suppress(asyncio.QueueFull):
                    retry_admission_queue.put_nowait(taken_entry)
                    wake_retry_scheduler()
            log_event(f"Retry scheduler error: {exc}")
        finally:
            if taken_entry is not None:
                retry_admission_queue.task_done()


def default_state(name):
    base = {"version": 2, "created_at": now_iso(), "updated_at": now_iso()}
    if name == "channel_manager":
        base.update({"channels": {}, "events": []})
    elif name == "manage_subscribe":
        base.update({"users": {}, "events": []})
    elif name == "sync_source_manager":
        base.update(
            {
                "runs": {},
                "items": {},
                "cursors": {},
                "guard_events": [],
                "startup_hot_scan": {},
                # Telegram forward protection belongs to the source chat, not a
                # particular message.  Keep a bounded capability cache across a
                # clean restart so a known-protected source does not pay for an
                # impossible copy RPC before every first re-upload.
                "copy_restricted_sources": {},
            }
        )
    elif name == "download_queue":
        base.update({"items": {}})
    elif name == "upload_queue":
        base.update({"items": {}})
    elif name == "total_auto_upload":
        base.update({"total_uploaded": 0, "items": {}, "events": []})
    elif name == "subscriptions_list":
        base.update({"active": {}, "expired": {}, "banned": {}, "removed": {}})
    elif name == "clean_duplicate":
        base.update({"items": {}, "target_messages": {}, "events": []})
    elif name == "target_media_index":
        base.update({"items": {}, "target_messages": {}, "events": [], "last_full_scan": ""})
    elif name == "dead_media":
        base.update({"items": {}, "source_counts": {}, "events": []})
    elif name == "worker_queue":
        base.update({"items": {}, "events": []})
    elif name == "runtime_config":
        base.update(
            {
                "workers": {},
                "queue": {},
                "admins": [],
                "target": {},
                "events": [],
                # A durable owner-status cursor prevents a restart or queue
                # healer loop from re-sending the same recovery summary.
                "queue_recovery_notification": {},
            }
        )
    return base


STATE_FILES = {
    "channel_manager": STATE_DIR / "channel_manager.json",
    "manage_subscribe": STATE_DIR / "manage_subscribe.json",
    "sync_source_manager": STATE_DIR / "sync_source_manager.json",
    "download_queue": STATE_DIR / "download_queue.json",
    "upload_queue": STATE_DIR / "upload_queue.json",
    "total_auto_upload": STATE_DIR / "total_auto_upload.json",
    "subscriptions_list": STATE_DIR / "subscriptions_list.json",
    "clean_duplicate": STATE_DIR / "clean_duplicate.json",
    "target_media_index": STATE_DIR / "target_media_index.json",
    "dead_media": STATE_DIR / "dead_media.json",
    "worker_queue": STATE_DIR / "worker_queue.json",
    "runtime_config": STATE_DIR / "runtime_config.json",
}
STATE = {}


def is_persistence_io_error(exc):
    if isinstance(exc, OSError) and getattr(exc, "errno", None) in {
        errno.EIO,
        errno.ENOSPC,
        errno.EROFS,
        errno.ESTALE,
        errno.ETIMEDOUT,
    }:
        return True
    text = str(exc or "").lower()
    return any(
        marker in text
        for marker in (
            "input/output error",
            "disk i/o error",
            "no space left on device",
            "read-only file system",
            "stale file handle",
        )
    )


def persistence_io_backoff_remaining():
    with PERSISTENCE_IO_LOCK:
        return max(0.0, PERSISTENCE_IO_BACKOFF_UNTIL - time.monotonic())


def record_persistence_io_failure(exc):
    global PERSISTENCE_IO_FAILURES, PERSISTENCE_IO_BACKOFF_UNTIL
    global PERSISTENCE_IO_LAST_ERROR, PERSISTENCE_IO_LAST_FAILURE_AT
    global PERSISTENCE_IO_RECOVERY_SUCCESSES
    if not is_persistence_io_error(exc):
        return 0.0
    with PERSISTENCE_IO_LOCK:
        PERSISTENCE_IO_FAILURES += 1
        PERSISTENCE_IO_RECOVERY_SUCCESSES = 0
        delay = min(
            PERSISTENCE_IO_BACKOFF_MAX_SECONDS,
            max(2.0, float(2 ** min(8, PERSISTENCE_IO_FAILURES))),
        )
        PERSISTENCE_IO_BACKOFF_UNTIL = max(
            PERSISTENCE_IO_BACKOFF_UNTIL,
            time.monotonic() + delay,
        )
        PERSISTENCE_IO_LAST_ERROR = (
            f"{type(exc).__name__}: {str(exc)[:300]}"
        )
        PERSISTENCE_IO_LAST_FAILURE_AT = time.time()
        return delay


def record_persistence_io_success():
    global PERSISTENCE_IO_FAILURES, PERSISTENCE_IO_BACKOFF_UNTIL
    global PERSISTENCE_IO_LAST_ERROR, PERSISTENCE_IO_LAST_SUCCESS_AT
    global PERSISTENCE_IO_RECOVERY_SUCCESSES
    with PERSISTENCE_IO_LOCK:
        PERSISTENCE_IO_LAST_SUCCESS_AT = time.time()
        if not PERSISTENCE_IO_FAILURES:
            PERSISTENCE_IO_BACKOFF_UNTIL = 0.0
            PERSISTENCE_IO_LAST_ERROR = ""
            PERSISTENCE_IO_RECOVERY_SUCCESSES = 0
            return
        # A successful write from another destination must not erase a recent
        # mounted-volume failure. Require a small consecutive success streak
        # after the circuit's backoff window before declaring storage healthy.
        if time.monotonic() < PERSISTENCE_IO_BACKOFF_UNTIL:
            return
        PERSISTENCE_IO_RECOVERY_SUCCESSES += 1
        if (
            PERSISTENCE_IO_RECOVERY_SUCCESSES
            < PERSISTENCE_IO_RECOVERY_SUCCESSES_REQUIRED
        ):
            return
        PERSISTENCE_IO_FAILURES = 0
        PERSISTENCE_IO_BACKOFF_UNTIL = 0.0
        PERSISTENCE_IO_LAST_ERROR = ""
        PERSISTENCE_IO_RECOVERY_SUCCESSES = 0


def persistence_io_health_snapshot():
    with PERSISTENCE_IO_LOCK:
        remaining = max(0.0, PERSISTENCE_IO_BACKOFF_UNTIL - time.monotonic())
        return {
            "healthy": not PERSISTENCE_IO_FAILURES and remaining <= 0,
            "circuit_open": remaining > 0,
            "failures": int(PERSISTENCE_IO_FAILURES),
            "recovery_successes": int(PERSISTENCE_IO_RECOVERY_SUCCESSES),
            "recovery_successes_required": int(
                PERSISTENCE_IO_RECOVERY_SUCCESSES_REQUIRED
            ),
            "backoff_remaining_seconds": round(remaining, 3),
            "last_failure_at": float(PERSISTENCE_IO_LAST_FAILURE_AT or 0.0),
            "last_success_at": float(PERSISTENCE_IO_LAST_SUCCESS_AT or 0.0),
            "last_error": str(PERSISTENCE_IO_LAST_ERROR),
        }


def ensure_persistence_write_available():
    with PERSISTENCE_IO_LOCK:
        remaining = max(0.0, PERSISTENCE_IO_BACKOFF_UNTIL - time.monotonic())
        last_error = str(PERSISTENCE_IO_LAST_ERROR)
        if remaining <= 0:
            return
        raise BlockingIOError(
            errno.EAGAIN,
            f"persistent storage circuit open for {remaining:.1f}s: "
            f"{last_error}",
        )


def _atomic_destination_lock(path):
    key = str(Path(path).resolve())
    with ATOMIC_WRITE_LOCKS_GUARD:
        return ATOMIC_WRITE_LOCKS.setdefault(key, threading.RLock())


def _atomic_temp_file(destination, mode):
    destination = Path(destination)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{destination.name}.",
        suffix=".tmp",
        dir=str(destination.parent),
    )
    return Path(temporary_name), os.fdopen(fd, mode)


def atomic_json_save(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    ensure_persistence_write_available()
    last_error = None
    with _atomic_destination_lock(path):
        for attempt in range(3):
            tmp = None
            try:
                tmp, raw_handle = _atomic_temp_file(path, "w")
                with raw_handle as handle:
                    handle.reconfigure(encoding="utf-8", newline="\n")
                    json.dump(data, handle, ensure_ascii=True, separators=(",", ":"))
                    handle.write("\n")
                    handle.flush()
                    if JSON_FSYNC_ENABLED:
                        os.fsync(handle.fileno())
                os.replace(tmp, path)
                _fsync_directory(path)
                record_persistence_io_success()
                return
            except OSError as exc:
                last_error = exc
                record_persistence_io_failure(exc)
                if tmp is not None:
                    with contextlib.suppress(Exception):
                        tmp.unlink(missing_ok=True)
                if is_persistence_io_error(exc):
                    break
                if attempt < 2:
                    time.sleep(0.2 * (attempt + 1))
    raise last_error


def canonical_json_bytes(data):
    return json.dumps(
        data,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _fsync_directory(path):
    if os.name == "nt":
        return
    with contextlib.suppress(Exception):
        fd = os.open(str(Path(path).parent), os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(fd)
        finally:
            os.close(fd)


def atomic_checkpoint_save(path, payload, sequence, previous_path=None):
    """Write a checksummed generation without exposing a partial checkpoint."""
    path = Path(path)
    previous_path = Path(previous_path) if previous_path else None
    path.parent.mkdir(parents=True, exist_ok=True)
    ensure_persistence_write_available()
    envelope = {
        "schema_version": RUNTIME_CHECKPOINT_SCHEMA_VERSION,
        "app_version": APP_VERSION,
        "sequence": int(sequence),
        "created_at": now_iso(),
        "payload": payload,
    }
    envelope["checksum"] = hashlib.sha256(canonical_json_bytes(payload)).hexdigest()
    encoded = canonical_json_bytes(envelope) + b"\n"
    with _atomic_destination_lock(path):
        if previous_path and path.exists():
            previous_tmp = None
            try:
                previous = load_checkpoint_envelope(path)
                if previous is not None:
                    previous_path.parent.mkdir(parents=True, exist_ok=True)
                    previous_tmp, previous_handle = _atomic_temp_file(
                        previous_path,
                        "wb",
                    )
                    with previous_handle as handle:
                        handle.write(path.read_bytes())
                        handle.flush()
                        os.fsync(handle.fileno())
                    os.replace(previous_tmp, previous_path)
                    previous_tmp = None
                    _fsync_directory(previous_path)
            except Exception as exc:
                if is_persistence_io_error(exc):
                    record_persistence_io_failure(exc)
                    raise
            finally:
                if previous_tmp is not None:
                    with contextlib.suppress(Exception):
                        previous_tmp.unlink(missing_ok=True)
        tmp = None
        try:
            tmp, raw_handle = _atomic_temp_file(path, "wb")
            with raw_handle as handle:
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, path)
            tmp = None
            _fsync_directory(path)
            record_persistence_io_success()
        except OSError as exc:
            record_persistence_io_failure(exc)
            raise
        finally:
            if tmp is not None:
                with contextlib.suppress(Exception):
                    tmp.unlink(missing_ok=True)
    return envelope


def load_checkpoint_envelope(path):
    path = Path(path)
    if not path.exists():
        return None
    try:
        envelope = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(envelope, dict):
            raise ValueError("checkpoint root is not an object")
        schema = int(envelope.get("schema_version") or 0)
        if not (RUNTIME_CHECKPOINT_MIN_SCHEMA_VERSION <= schema <= RUNTIME_CHECKPOINT_SCHEMA_VERSION):
            raise ValueError(f"unsupported checkpoint schema {schema}")
        payload = envelope.get("payload")
        checksum = str(envelope.get("checksum") or "")
        if not isinstance(payload, dict) or not checksum:
            raise ValueError("checkpoint payload/checksum is missing")
        actual = hashlib.sha256(canonical_json_bytes(payload)).hexdigest()
        if checksum != actual:
            raise ValueError("checkpoint checksum mismatch")
        created_at = parse_iso_timestamp(envelope.get("created_at"))
        if created_at:
            max_age = timedelta(days=max(1, int(RUNTIME_CHECKPOINT_MAX_AGE_DAYS)))
            if datetime.now() - created_at > max_age:
                raise ValueError("checkpoint is older than allowed retention")
        return envelope
    except Exception as exc:
        record_persistence_io_failure(exc)
        if "log_event" in globals():
            log_event(f"Runtime checkpoint rejected {path.name}: {str(exc)[:180]}")
        else:
            print(f"Runtime checkpoint rejected {path.name}: {exc}", flush=True)
        return None


def load_checkpoint_with_fallback(primary_path, previous_path):
    primary = load_checkpoint_envelope(primary_path)
    if primary is not None:
        return primary, "primary"
    previous = load_checkpoint_envelope(previous_path)
    if previous is not None:
        return previous, "previous"
    return None, ""


def load_json_state(name):
    path = STATE_FILES[name]
    default = default_state(name)
    legacy_path = DATA_DIR / path.name
    if not path.exists() and legacy_path.exists() and legacy_path.resolve() != path.resolve():
        with contextlib.suppress(Exception):
            shutil.copy2(str(legacy_path), str(path))
            log_event(f"Migrated {name} state from shared storage to runtime state folder.")
    if not path.exists():
        atomic_json_save(path, default)
        return default
    try:
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("state root is not an object")
        changed = False
        for key, value in default.items():
            if key not in data:
                data[key] = value
                changed = True
        if changed:
            atomic_json_save(path, data)
        return data
    except Exception:
        bad_path = path.with_suffix(path.suffix + f".bad_{int(time.time())}")
        with contextlib.suppress(Exception):
            path.rename(bad_path)
        snapshot = latest_backup_dir()
        backup_path = snapshot / backup_relative_path(path) if snapshot else None
        if backup_path and backup_path.exists():
            try:
                with backup_path.open("r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    atomic_json_save(path, data)
                    log_event(f"Restored JSON state backup for {name}.")
                    return data
            except Exception as e:
                log_event(f"JSON backup restore failed for {name}: {e}")
        atomic_json_save(path, default)
        return default


def init_state_files():
    with state_mutex:
        for name in STATE_FILES:
            STATE[name] = load_json_state(name)


def _write_state_snapshot(name, snapshot):
    atomic_json_save(STATE_FILES[name], snapshot)


def snapshot_state_for_writer(name):
    """Capture large index maps briefly, then deepcopy outside the shared lock."""
    with state_mutex:
        current = STATE[name]
        if name not in {"target_media_index", "clean_duplicate"}:
            return deepcopy(current)
        header = {key: deepcopy(value) for key, value in current.items() if key not in {"items", "target_messages"}}
        item_pairs = list(current.get("items", {}).items())
        target_pairs = list(current.get("target_messages", {}).items())
    header["items"] = {key: deepcopy(value) for key, value in item_pairs}
    header["target_messages"] = dict(target_pairs)
    return header


def _queue_state_name_locked(name):
    if name in STATE_SAVE_QUEUED or name in STATE_SAVE_INFLIGHT:
        return
    if (
        name in {"target_media_index", "clean_duplicate"}
        and not STATE_SAVE_STOP.is_set()
        and time.monotonic() < float(STATE_SAVE_NEXT_ALLOWED.get(name, 0.0))
    ):
        return
    STATE_SAVE_QUEUED.add(name)
    STATE_SAVE_QUEUE.put_nowait(name)


def _state_save_worker():
    global STATE_SAVE_THREAD
    try:
        while True:
            try:
                name = STATE_SAVE_QUEUE.get(timeout=0.5)
            except queue.Empty:
                with STATE_SAVE_CONDITION:
                    for pending_name, version in STATE_SAVE_REQUESTED.items():
                        if int(version) > int(STATE_SAVE_PERSISTED.get(pending_name, 0)):
                            _queue_state_name_locked(pending_name)
                if STATE_SAVE_STOP.is_set():
                    with STATE_SAVE_CONDITION:
                        if not STATE_SAVE_QUEUED and not STATE_SAVE_INFLIGHT:
                            break
                continue
            if name is None:
                STATE_SAVE_QUEUE.task_done()
                if STATE_SAVE_STOP.is_set():
                    break
                continue
            with STATE_SAVE_CONDITION:
                STATE_SAVE_QUEUED.discard(name)
                target_version = int(STATE_SAVE_REQUESTED.get(name, 0))
                STATE_SAVE_INFLIGHT[name] = target_version
            snapshot = None
            last_error = None
            for attempt in range(8):
                try:
                    # Snapshot in the persistence thread under the state lock. This prevents
                    # dictionary-size races while keeping deepcopy/JSON I/O off the event loop.
                    snapshot = snapshot_state_for_writer(name)
                    last_error = None
                    break
                except (RuntimeError, KeyError) as exc:
                    last_error = exc
                    time.sleep(min(0.25, 0.01 * (attempt + 1)))
            try:
                if snapshot is None:
                    raise RuntimeError(f"state snapshot failed for {name}: {last_error}")
                _write_state_snapshot(name, snapshot)
                with STATE_SAVE_CONDITION:
                    STATE_SAVE_PERSISTED[name] = max(int(STATE_SAVE_PERSISTED.get(name, 0)), target_version)
                    if name in {"target_media_index", "clean_duplicate"}:
                        STATE_SAVE_NEXT_ALLOWED[name] = (
                            time.monotonic() + LARGE_STATE_SAVE_MIN_INTERVAL_SECONDS
                        )
            except Exception as exc:
                log_event(f"State writer failed for {name} v{target_version}: {exc}")
                remaining = persistence_io_backoff_remaining()
                time.sleep(
                    max(
                        1.0,
                        min(
                            float(PERSISTENCE_IO_BACKOFF_MAX_SECONDS),
                            remaining or 1.0,
                        ),
                    )
                )
            finally:
                with STATE_SAVE_CONDITION:
                    STATE_SAVE_INFLIGHT.pop(name, None)
                    if int(STATE_SAVE_REQUESTED.get(name, 0)) > int(STATE_SAVE_PERSISTED.get(name, 0)):
                        _queue_state_name_locked(name)
                    STATE_SAVE_CONDITION.notify_all()
                STATE_SAVE_QUEUE.task_done()
    finally:
        with STATE_SAVE_CONDITION:
            STATE_SAVE_THREAD = None
            STATE_SAVE_CONDITION.notify_all()


def start_state_save_worker():
    global STATE_SAVE_THREAD
    previous = None
    with STATE_SAVE_CONDITION:
        if STATE_SAVE_THREAD and STATE_SAVE_THREAD.is_alive() and not STATE_SAVE_STOP.is_set():
            return True
        previous = STATE_SAVE_THREAD if STATE_SAVE_THREAD and STATE_SAVE_THREAD.is_alive() else None
        STATE_SAVE_STOP.clear()
    if previous:
        previous.join(timeout=5)
    with STATE_SAVE_CONDITION:
        if STATE_SAVE_THREAD and STATE_SAVE_THREAD.is_alive():
            return True
        STATE_SAVE_THREAD = threading.Thread(target=_state_save_worker, name="royells-state-writer", daemon=False)
        STATE_SAVE_THREAD.start()
        for name in STATE_SAVE_REQUESTED:
            if int(STATE_SAVE_REQUESTED.get(name, 0)) > int(STATE_SAVE_PERSISTED.get(name, 0)):
                _queue_state_name_locked(name)
    return True


def flush_state_saves(timeout=30):
    deadline = time.monotonic() + max(0.1, timeout)
    with STATE_SAVE_CONDITION:
        for name in ("target_media_index", "clean_duplicate"):
            STATE_SAVE_NEXT_ALLOWED[name] = 0.0
            if int(STATE_SAVE_REQUESTED.get(name, 0)) > int(STATE_SAVE_PERSISTED.get(name, 0)):
                _queue_state_name_locked(name)
        while True:
            complete = (
                all(int(STATE_SAVE_PERSISTED.get(name, 0)) >= int(version) for name, version in STATE_SAVE_REQUESTED.items())
                and not STATE_SAVE_QUEUED
                and not STATE_SAVE_INFLIGHT
            )
            if complete:
                return True
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False
            STATE_SAVE_CONDITION.wait(timeout=min(0.25, remaining))


def stop_state_save_worker(timeout=30):
    global STATE_SAVE_THREAD
    flushed = flush_state_saves(timeout=max(1, timeout * 0.75))
    with STATE_SAVE_CONDITION:
        STATE_SAVE_STOP.set()
        thread = STATE_SAVE_THREAD
    STATE_SAVE_QUEUE.put_nowait(None)
    if thread:
        thread.join(timeout=max(1, timeout * 0.25))
    with STATE_SAVE_CONDITION:
        stopped = not (STATE_SAVE_THREAD and STATE_SAVE_THREAD.is_alive())
    return bool(flushed and stopped)


def save_state(name):
    # O(1) event-loop path: mutation version only. Snapshot and JSON I/O are writer-thread work.
    with state_mutex:
        STATE[name]["updated_at"] = now_iso()
    mark_runtime_checkpoint_dirty(f"state {name}")
    with STATE_SAVE_CONDITION:
        version = int(STATE_SAVE_REQUESTED.get(name, 0)) + 1
        STATE_SAVE_REQUESTED[name] = version
        if not (STATE_SAVE_THREAD and STATE_SAVE_THREAD.is_alive() and not STATE_SAVE_STOP.is_set()):
            start_needed = True
        else:
            start_needed = False
            _queue_state_name_locked(name)
    if start_needed:
        start_state_save_worker()
        with STATE_SAVE_CONDITION:
            _queue_state_name_locked(name)
    return version


def is_backup_excluded_file(path):
    p = Path(path)
    name = p.name.lower()
    parts = {part.lower() for part in p.parts}
    if name == "bot.log" or ".session" in name:
        return True
    if name.endswith((".tmp", ".temp", ".cache", ".lock", "-journal", "-wal", "-shm")):
        return True
    if "downloads" in parts or "__pycache__" in parts:
        return True
    return False


def managed_state_files():
    files = set(STATE_FILES.values())
    files.update(
        {
            DB_FILE,
            RUNTIME_CHECKPOINT_FILE,
            RUNTIME_CHECKPOINT_PREVIOUS_FILE,
            DELIVERY_INTENT_FILE,
            DELIVERY_INTENT_PREVIOUS_FILE,
            MEDIA_LEDGER_FILE,
        }
    )
    return [
        p
        for p in files
        if p
        and p.exists()
        and p.is_file()
        and not is_backup_excluded_file(p)
    ]


def managed_archive_files():
    """Return essential non-DB files for portable restore archives; logs/downloads are intentionally excluded."""
    files = set(STATE_FILES.values())
    files.update(
        {
            RUNTIME_CHECKPOINT_FILE,
            RUNTIME_CHECKPOINT_PREVIOUS_FILE,
            DELIVERY_INTENT_FILE,
            DELIVERY_INTENT_PREVIOUS_FILE,
            MEDIA_LEDGER_FILE,
        }
    )
    return [
        p
        for p in files
        if p
        and p.exists()
        and p.is_file()
        and not is_backup_excluded_file(p)
    ]


def backup_relative_path(path):
    path = Path(path).resolve()
    for root_name, root in (("runtime", RUNTIME_DIR.resolve()), ("data", DATA_DIR.resolve())):
        with contextlib.suppress(ValueError):
            return Path(root_name) / path.relative_to(root)
    return Path("misc") / path.name


def copy_file_atomic(src, dst):
    dst = Path(dst)
    dst.parent.mkdir(parents=True, exist_ok=True)
    ensure_persistence_write_available()
    with _atomic_destination_lock(dst):
        tmp = None
        try:
            fd, temporary_name = tempfile.mkstemp(
                prefix=f".{dst.name}.",
                suffix=".tmp",
                dir=str(dst.parent),
            )
            os.close(fd)
            tmp = Path(temporary_name)
            shutil.copy2(str(src), str(tmp))
            with tmp.open("rb") as handle:
                os.fsync(handle.fileno())
            os.replace(tmp, dst)
            tmp = None
            _fsync_directory(dst)
            record_persistence_io_success()
        except OSError as exc:
            record_persistence_io_failure(exc)
            raise
        finally:
            if tmp is not None:
                with contextlib.suppress(Exception):
                    tmp.unlink(missing_ok=True)


def sqlite_sidecar_paths(path):
    """Return transient SQLite files that must never survive a DB replacement."""
    db_path = Path(path)
    return [Path(str(db_path) + suffix) for suffix in ("-wal", "-shm", "-journal")]


def remove_sqlite_sidecars(path):
    removed = 0
    for sidecar in sqlite_sidecar_paths(path):
        try:
            if sidecar.exists():
                sidecar.unlink()
                removed += 1
        except Exception as exc:
            log_event(f"SQLite sidecar cleanup failed for {sidecar.name}: {str(exc)[:140]}")
    return removed


def sqlite_integrity_status(path):
    db_path = Path(path)
    if not db_path.exists():
        return "missing"
    conn = None
    try:
        conn = sqlite3.connect(str(db_path), timeout=30.0)
        conn.execute("PRAGMA foreign_keys=ON;")
        result = conn.execute("PRAGMA integrity_check;").fetchone()
        status = str(result[0]) if result else "unknown"
        if status != "ok":
            return status
        foreign_key_error = conn.execute("PRAGMA foreign_key_check;").fetchone()
        if foreign_key_error:
            return f"foreign key violation: {foreign_key_error}"
        return "ok"
    except Exception as exc:
        return f"error: {str(exc)[:120]}"
    finally:
        if conn is not None:
            with contextlib.suppress(Exception):
                conn.close()


def sqlite_integrity_ok(path):
    return sqlite_integrity_status(path) == "ok"


def is_sqlite_corruption_error(error):
    text = str(error or "").lower()
    return any(
        marker in text
        for marker in (
            "database disk image is malformed",
            "database corruption",
            "database corrupt",
            "file is not a database",
            "malformed database schema",
        )
    )


def is_sqlite_open_error(error):
    text = str(error or "").lower()
    return any(
        marker in text
        for marker in (
            "unable to open database file",
            "attempt to write a readonly database",
            "readonly database",
            "disk i/o error",
            "vfs",
        )
    )


def prepare_sqlite_runtime_paths(force=False):
    """Probe the mounted runtime path once, then repeat only after an open failure."""
    global DB_RUNTIME_PATHS_READY
    if DB_RUNTIME_PATHS_READY and not force and DB_FILE.parent.exists():
        return True
    DB_FILE.parent.mkdir(parents=True, exist_ok=True)
    RUNTIME_DIR.mkdir(parents=True, exist_ok=True)
    probe = DB_FILE.parent / f".sqlite_open_probe_{BOOT_ID}_{threading.get_ident()}"
    try:
        with probe.open("w", encoding="utf-8") as handle:
            handle.write("ok")
            handle.flush()
            with contextlib.suppress(Exception):
                os.fsync(handle.fileno())
        DB_RUNTIME_PATHS_READY = True
        return True
    except Exception:
        DB_RUNTIME_PATHS_READY = False
        raise
    finally:
        with contextlib.suppress(Exception):
            probe.unlink(missing_ok=True)


def reset_sqlite_open_state(reason="", remove_sidecars=False):
    global DB_JOURNAL_INITIALIZED, DB_RUNTIME_PATHS_READY
    with DB_OPEN_REPAIR_LOCK:
        DB_JOURNAL_INITIALIZED = False
        DB_RUNTIME_PATHS_READY = False
        prepare_sqlite_runtime_paths(force=True)
        if remove_sidecars and DB_OPEN_STARTUP_SIDECAR_REPAIR and DB_FILE.exists():
            removed = remove_sqlite_sidecars(DB_FILE)
            if removed:
                log_event(f"SQLite startup open repair removed {removed} stale sidecar file(s): {reason}")


def ensure_sqlite_runtime_ready(
    reason="startup",
    attempts=None,
    require_write=True,
    startup_sidecar_repair=False,
):
    attempts = max(1, int(attempts or DB_STARTUP_READY_ATTEMPTS))
    last_error = None
    for attempt in range(1, attempts + 1):
        try:
            reset_sqlite_open_state(reason, remove_sidecars=False)
            with db_mutex:
                conn = db_connect()
                try:
                    quick = conn.execute("PRAGMA quick_check;").fetchone()
                    if not quick or str(quick[0]).lower() != "ok":
                        raise RuntimeError(f"SQLite quick_check failed: {quick[0] if quick else 'missing result'}")
                    foreign_key_error = conn.execute(
                        "PRAGMA foreign_key_check;"
                    ).fetchone()
                    if foreign_key_error:
                        raise RuntimeError(
                            f"SQLite foreign_key_check failed: {foreign_key_error}"
                        )
                    if require_write:
                        conn.execute(
                            """
                            CREATE TABLE IF NOT EXISTS runtime_health (
                                id TEXT PRIMARY KEY,
                                boot_id TEXT DEFAULT '',
                                reason TEXT DEFAULT '',
                                last_seen TEXT DEFAULT ''
                            )
                            """
                        )
                        conn.execute(
                            """
                            INSERT INTO runtime_health (id, boot_id, reason, last_seen)
                            VALUES ('sqlite_ready', ?, ?, ?)
                            ON CONFLICT(id) DO UPDATE SET
                                boot_id=excluded.boot_id,
                                reason=excluded.reason,
                                last_seen=excluded.last_seen
                            """,
                            (BOOT_ID, str(reason)[:120], now_iso()),
                        )
                        conn.commit()
                    with contextlib.suppress(Exception):
                        conn.execute("PRAGMA wal_checkpoint(PASSIVE);")
                finally:
                    conn.close()
            if attempt > 1:
                log_event(f"SQLite readiness recovered for {reason} on attempt {attempt}/{attempts}.")
            return True
        except Exception as exc:
            last_error = exc
            if startup_sidecar_repair and is_sqlite_open_error(exc) and attempt >= 2:
                with contextlib.suppress(Exception):
                    reset_sqlite_open_state(
                        f"{reason} readiness attempt {attempt}/{attempts}: {exc}",
                        remove_sidecars=True,
                    )
            log_event(
                f"SQLite readiness probe failed for {reason} attempt {attempt}/{attempts}: "
                f"{type(exc).__name__}: {str(exc)[:180]}"
            )
            if attempt < attempts:
                time.sleep(min(10.0, DB_STARTUP_READY_DELAY_SECONDS * attempt))
    raise RuntimeError(
        f"SQLite is not ready for {reason} after {attempts} attempt(s): "
        f"{type(last_error).__name__}: {str(last_error)[:180]}"
    )


def restore_file_tree(snapshot_dir):
    restored = 0
    for root_name, root in (("runtime", RUNTIME_DIR), ("data", DATA_DIR)):
        source_root = snapshot_dir / root_name
        if not source_root.exists():
            continue
        for src in source_root.rglob("*"):
            if not src.is_file():
                continue
            if is_backup_excluded_file(src):
                continue
            dst = root / src.relative_to(source_root)
            if dst.exists():
                continue
            with contextlib.suppress(Exception):
                if dst == DB_FILE:
                    remove_sqlite_sidecars(DB_FILE)
                copy_file_atomic(src, dst)
                restored += 1
    return restored


def latest_backup_dir():
    latest = BACKUP_DIR / "latest"
    if latest.exists():
        return latest
    snapshots = sorted([p for p in BACKUP_DIR.glob("snapshot_*") if p.is_dir()])
    return snapshots[-1] if snapshots else None


def restore_state_backup_if_needed():
    snapshot = latest_backup_dir()
    if not snapshot:
        return 0
    return restore_file_tree(snapshot)


def db_integrity_ok():
    if not DB_FILE.exists():
        return True
    return sqlite_integrity_ok(DB_FILE)


def db_integrity_status():
    return sqlite_integrity_status(DB_FILE)


def log_db_startup_status():
    size_mb = 0.0
    with contextlib.suppress(Exception):
        size_mb = DB_FILE.stat().st_size / (1024 * 1024)
    counts = {}
    try:
        with db_mutex:
            conn = db_connect()
            for table in ("posted", "target_media", "target_media_full_index", "channels", "subscriptions", "dead_media", "media_job_state"):
                with contextlib.suppress(Exception):
                    counts[table] = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            conn.close()
    except Exception as e:
        counts["error"] = str(e)[:120]
    log_event(
        "DB startup status: "
        f"path={DB_FILE} | size={size_mb:.2f} MB | integrity={db_integrity_status()} | counts={counts}"
    )


def load_source_link_report_config():
    global SOURCE_LINK_REPORT_CHAT_ID
    with state_mutex:
        saved = STATE["sync_source_manager"].get("source_link_report_chat_id")
    if saved not in (None, ""):
        SOURCE_LINK_REPORT_CHAT_ID = normalize_channel_id(saved) if str(saved) != "0" else 0
    return SOURCE_LINK_REPORT_CHAT_ID


def save_source_link_report_config(chat_id, title="", source_link="", username=""):
    global SOURCE_LINK_REPORT_CHAT_ID
    norm = normalize_channel_id(chat_id) if chat_id else 0
    norm_text = str(norm)
    target_text = str(normalize_channel_id(TARGET_CHAT_ID)) if TARGET_CHAT_ID else ""
    queue_text = str(normalize_channel_id(WORKER_QUEUE_GROUP_ID)) if WORKER_QUEUE_GROUP_ID else ""
    if norm and norm_text == target_text:
        raise ValueError("Target channel cannot be used as source-link report channel.")
    if norm and queue_text and norm_text == queue_text:
        raise ValueError("Worker queue group cannot be used as source-link report channel.")
    SOURCE_LINK_REPORT_CHAT_ID = norm
    with state_mutex:
        STATE["sync_source_manager"]["source_link_report_chat_id"] = str(norm or 0)
        STATE["sync_source_manager"]["source_link_report_title"] = title or ""
        STATE["sync_source_manager"]["source_link_report_link"] = source_link or ""
        STATE["sync_source_manager"]["source_link_report_username"] = username or ""
        STATE["sync_source_manager"]["source_link_report_updated_at"] = now_iso()
        save_state("sync_source_manager")
    log_event(f"Source link report channel set to {norm or 'disabled'} ({title or 'no title'}).")
    return norm


def get_source_link_report_config():
    with state_mutex:
        manager = STATE["sync_source_manager"]
        return {
            "chat_id": str(SOURCE_LINK_REPORT_CHAT_ID or manager.get("source_link_report_chat_id") or "0"),
            "title": manager.get("source_link_report_title", ""),
            "link": manager.get("source_link_report_link", ""),
            "username": manager.get("source_link_report_username", ""),
            "updated_at": manager.get("source_link_report_updated_at", ""),
        }


def repair_db_indexes_in_place(path=None):
    db_path = Path(path or DB_FILE)
    if not db_path.exists():
        return False
    conn = None
    try:
        conn = sqlite3.connect(str(db_path), timeout=60.0)
        conn.execute("REINDEX")
        conn.commit()
        result = conn.execute("PRAGMA integrity_check;").fetchone()
        return bool(result and result[0] == "ok")
    except Exception as exc:
        log_event(f"SQLite in-place index repair failed: {str(exc)[:180]}")
        return False
    finally:
        if conn is not None:
            with contextlib.suppress(Exception):
                conn.close()


def quarantine_sqlite_bundle(source_path, quarantined_path):
    """Move a database and any matching WAL/SHM/journal files as one recovery bundle."""
    source_path = Path(source_path)
    quarantined_path = Path(quarantined_path)
    moved = []
    members = [(source_path, quarantined_path)]
    members.extend(
        (Path(str(source_path) + suffix), Path(str(quarantined_path) + suffix))
        for suffix in ("-wal", "-shm", "-journal")
    )
    for source, destination in members:
        if not source.exists():
            continue
        destination.parent.mkdir(parents=True, exist_ok=True)
        try:
            os.replace(source, destination)
        except Exception:
            shutil.copy2(source, destination)
            source.unlink()
        moved.append(destination)
    return moved


def quote_sqlite_identifier(value):
    return '"' + str(value).replace('"', '""') + '"'


def salvage_sqlite_table(source_conn, destination_conn, table_name, batch_size=256):
    """Recover readable rowid ranges while skipping only pages SQLite cannot decode."""
    table_sql = quote_sqlite_identifier(table_name)
    source_columns = {
        str(row[1])
        for row in source_conn.execute(f"PRAGMA table_info({table_sql})").fetchall()
    }
    destination_columns = [
        str(row[1])
        for row in destination_conn.execute(f"PRAGMA table_info({table_sql})").fetchall()
    ]
    columns = [column for column in destination_columns if column in source_columns]
    if not columns:
        return 0, 0

    quoted_columns = ", ".join(quote_sqlite_identifier(column) for column in columns)
    parameter_marks = ", ".join("?" for _ in columns)
    insert_sql = (
        f"INSERT OR IGNORE INTO {table_sql} ({quoted_columns}) "
        f"VALUES ({parameter_marks})"
    )
    bounds = source_conn.execute(
        f"SELECT MIN(rowid), MAX(rowid) FROM {table_sql}"
    ).fetchone()
    if not bounds or bounds[0] is None or bounds[1] is None:
        return 0, 0

    recovered = 0
    skipped = 0

    def insert_rows(rows):
        nonlocal recovered, skipped
        try:
            destination_conn.executemany(insert_sql, rows)
            recovered += len(rows)
            return
        except Exception:
            pass
        for row in rows:
            try:
                destination_conn.execute(insert_sql, row)
                recovered += 1
            except Exception:
                skipped += 1

    def recover_range(start_rowid, end_rowid):
        nonlocal skipped
        if start_rowid > end_rowid:
            return
        try:
            rows = source_conn.execute(
                f"SELECT {quoted_columns} FROM {table_sql} "
                "WHERE rowid BETWEEN ? AND ? ORDER BY rowid",
                (start_rowid, end_rowid),
            ).fetchall()
        except sqlite3.DatabaseError:
            if start_rowid == end_rowid:
                skipped += 1
                return
            midpoint = start_rowid + ((end_rowid - start_rowid) // 2)
            recover_range(start_rowid, midpoint)
            recover_range(midpoint + 1, end_rowid)
            return
        insert_rows(rows)

    first_rowid, last_rowid = int(bounds[0]), int(bounds[1])
    batch_size = max(32, int(batch_size))
    for start_rowid in range(first_rowid, last_rowid + 1, batch_size):
        recover_range(start_rowid, min(last_rowid, start_rowid + batch_size - 1))
    return recovered, skipped


def salvage_pending_database_rows(destination_conn):
    global DB_PENDING_SALVAGE_SOURCES
    if not DB_PENDING_SALVAGE_SOURCES:
        return 0

    tables = (
        "posted",
        "channels",
        "subscriptions",
        "target_media",
        "target_media_full_index",
        "dead_media",
        "content_filter_hashes",
        "media_job_state",
    )
    total_recovered = 0
    total_skipped = 0
    sources = list(dict.fromkeys(Path(path) for path in DB_PENDING_SALVAGE_SOURCES if path))
    DB_PENDING_SALVAGE_SOURCES = []

    for source_path in sources:
        if not source_path.exists():
            continue
        source_conn = None
        source_recovered = 0
        source_skipped = 0
        try:
            source_conn = sqlite3.connect(str(source_path), timeout=30.0)
            source_conn.execute("PRAGMA query_only=ON;")
            for table_name in tables:
                try:
                    recovered, skipped = salvage_sqlite_table(
                        source_conn,
                        destination_conn,
                        table_name,
                    )
                    source_recovered += recovered
                    source_skipped += skipped
                except Exception as exc:
                    log_event(
                        f"SQLite salvage skipped unreadable table {table_name} from "
                        f"{source_path.name}: {str(exc)[:160]}"
                    )
            destination_conn.commit()
        except Exception as exc:
            log_event(f"SQLite salvage source could not be opened {source_path.name}: {str(exc)[:180]}")
        finally:
            if source_conn is not None:
                with contextlib.suppress(Exception):
                    source_conn.close()
        total_recovered += source_recovered
        total_skipped += source_skipped
        log_event(
            f"SQLite salvage source {source_path.name}: recovered={source_recovered}, "
            f"unreadable_or_rejected={source_skipped}."
        )

    integrity = destination_conn.execute("PRAGMA integrity_check;").fetchone()
    if not integrity or integrity[0] != "ok":
        raise RuntimeError(f"rebuilt SQLite failed integrity after salvage: {integrity}")
    log_event(
        f"SQLite salvage complete: recovered={total_recovered}, "
        f"unreadable_or_rejected={total_skipped}, integrity=ok."
    )
    return total_recovered


def repair_db_from_backup_if_needed():
    global DB_JOURNAL_INITIALIZED, DB_REQUIRES_TARGET_REINDEX, DB_PENDING_SALVAGE_SOURCES
    if not DB_FILE.exists():
        remove_sqlite_sidecars(DB_FILE)
        DB_REQUIRES_TARGET_REINDEX = True
        return False
    if db_integrity_ok():
        prune_db_recovery_artifacts()
        return False
    original_status = db_integrity_status()
    if "index" in original_status.lower() and repair_db_indexes_in_place(DB_FILE):
        log_event(f"DB index corruption repaired in place: {original_status}")
        prune_db_recovery_artifacts()
        return True
    bad_path = DB_FILE.with_suffix(DB_FILE.suffix + f".corrupt_{int(time.time())}")
    try:
        quarantine_sqlite_bundle(DB_FILE, bad_path)
    except Exception as exc:
        log_event(f"SQLite corrupt bundle quarantine failed: {str(exc)[:180]}")
        with contextlib.suppress(Exception):
            shutil.copy2(DB_FILE, bad_path)
            DB_FILE.unlink()
    remove_sqlite_sidecars(DB_FILE)
    DB_JOURNAL_INITIALIZED = False
    snapshot = latest_backup_dir()
    backup_db = snapshot / "runtime" / DB_FILE.name if snapshot else None
    if backup_db and backup_db.exists() and sqlite_integrity_ok(backup_db):
        copy_file_atomic(backup_db, DB_FILE)
        remove_sqlite_sidecars(DB_FILE)
        if not db_integrity_ok() and "index" in db_integrity_status().lower():
            repair_db_indexes_in_place(DB_FILE)
        if db_integrity_ok():
            log_event(f"DB integrity failed; restored and validated backup DB from {backup_db}.")
            prune_db_recovery_artifacts()
            return True
        restored_bad = DB_FILE.with_suffix(DB_FILE.suffix + f".restored_corrupt_{int(time.time())}")
        with contextlib.suppress(Exception):
            os.replace(DB_FILE, restored_bad)
        remove_sqlite_sidecars(DB_FILE)
        DB_REQUIRES_TARGET_REINDEX = True
        DB_PENDING_SALVAGE_SOURCES = [bad_path, restored_bad]
        prune_db_recovery_artifacts()
        log_event(
            f"Backup DB also failed integrity; quarantined as {restored_bad.name}. "
            "A fresh DB will salvage every readable row from both recovery sources."
        )
        return False
    if backup_db and backup_db.exists():
        log_event(f"Backup DB failed validation and was not restored: {backup_db}.")
    DB_REQUIRES_TARGET_REINDEX = True
    DB_PENDING_SALVAGE_SOURCES = [bad_path]
    if backup_db and backup_db.exists():
        DB_PENDING_SALVAGE_SOURCES.append(backup_db)
    prune_db_recovery_artifacts()
    log_event(
        "DB integrity failed; no valid backup DB found. "
        "A fresh DB will salvage every readable row before normal startup."
    )
    return False


def request_db_online_recovery(reason):
    """Schedule an in-process SQLite repair without restarting queue workers."""
    global DB_RECOVERY_REASON
    reason_text = str(reason or "SQLite health check failed")[:500]
    with DB_OPEN_REPAIR_LOCK:
        DB_RECOVERY_REASON = reason_text
        DB_RECOVERY_REQUESTED.set()
    record_production_incident(
        "Database Busy" if "corrupt" not in reason_text.lower() else "SQLite Corruption",
        "critical" if "corrupt" in reason_text.lower() else "warning",
        "database",
        exception=RuntimeError(reason_text),
        recovery={"attempted": True, "successful": False},
        rate_limit_key=f"db_recovery:{reason_text[:120]}",
    )
    return True


def rehydrate_db_from_authoritative_state_sync():
    """Restore rebuildable DB rows from JSON state after an online repair."""
    with state_mutex:
        channels = [
            deepcopy(item)
            for item in STATE.get("channel_manager", {}).get("channels", {}).values()
            if str((item or {}).get("status") or "active")
            not in {"removed", "expired_or_deleted", "ignored_system", RESOLVED_ALIAS_STATUS}
        ]
        subscriptions = [
            (str(uid), deepcopy(item))
            for uid, item in STATE.get("manage_subscribe", {}).get("users", {}).items()
            if str((item or {}).get("status") or "") == "active"
        ]
        target_items = {
            str(uid): deepcopy(item)
            for uid, item in STATE.get("target_media_index", {}).get("items", {}).items()
            if uid
        }
        clean_items = {
            str(uid): deepcopy(item)
            for uid, item in STATE.get("clean_duplicate", {}).get("items", {}).items()
            if uid
        }
    with db_mutex:
        conn = db_connect()
        try:
            conn.execute("BEGIN IMMEDIATE")
            for item in channels:
                cid = normalize_channel_id(item.get("channel_id", ""))
                if cid in (None, "") or is_reserved_source_channel(cid):
                    continue
                conn.execute(
                    """
                    INSERT OR REPLACE INTO channels
                    (channel_id, title, source_link, username, added_at, updated_at)
                    VALUES (?,?,?,?,?,?)
                    """,
                    (
                        str(cid),
                        str(item.get("title") or cid),
                        str(item.get("source_link") or ""),
                        str(item.get("username") or ""),
                        str(item.get("added_at") or item.get("created_at") or now_iso()),
                        str(item.get("updated_at") or now_iso()),
                    ),
                )
            for uid, item in subscriptions:
                expire_date = str(item.get("expire_date") or "")
                if not expire_date:
                    continue
                conn.execute(
                    """
                    INSERT OR REPLACE INTO subscriptions
                    (user_id, expire_date, first_name, last_name, username, profile_updated_at)
                    VALUES (?,?,?,?,?,?)
                    """,
                    (
                        uid,
                        expire_date,
                        str(item.get("first_name") or ""),
                        str(item.get("last_name") or ""),
                        str(item.get("username") or "").lstrip("@"),
                        str(item.get("profile_updated_at") or ""),
                    ),
                )
            merged_targets = dict(clean_items)
            merged_targets.update(target_items)
            for uid, item in merged_targets.items():
                message_id = int(
                    item.get("message_id")
                    or (item.get("target_message_ids") or [0])[-1]
                    or 0
                )
                conn.execute(
                    """
                    INSERT OR REPLACE INTO target_media_full_index
                    (uid, message_id, indexed_at, source)
                    VALUES (?,?,?,?)
                    """,
                    (
                        uid,
                        message_id,
                        "",
                        "",
                    ),
                )
            conn.commit()
        except Exception:
            with contextlib.suppress(Exception):
                conn.rollback()
            raise
        finally:
            conn.close()
    return {
        "channels": len(channels),
        "subscriptions": len(subscriptions),
        "targets": len(set(target_items) | set(clean_items)),
    }


def perform_db_online_recovery_sync(reason=""):
    """Repair, rebuild, and rehydrate SQLite while keeping the process alive."""
    global DB_RECOVERY_ACTIVE, DB_RECOVERY_THREAD_ID
    global DB_LAST_RECOVERY_AT, DB_RECOVERY_REASON
    global DB_DIAGNOSTIC_WRITES_DISABLED, DB_DEGRADED, DB_RUNTIME_PATHS_READY
    global DB_REQUIRES_TARGET_REINDEX
    now_ts = time.time()
    with DB_OPEN_REPAIR_LOCK:
        if DB_RECOVERY_ACTIVE:
            return False
        if (
            now_ts - DB_LAST_RECOVERY_AT < DB_ONLINE_RECOVERY_COOLDOWN_SECONDS
            and not DB_RECOVERY_REQUESTED.is_set()
        ):
            return False
        DB_RECOVERY_ACTIVE = True
        DB_RECOVERY_THREAD_ID = threading.get_ident()
        DB_RECOVERY_REQUESTED.clear()
        recovery_reason = str(reason or DB_RECOVERY_REASON or "periodic SQLite guard")[:500]
    try:
        log_event(f"SQLite online recovery started: {recovery_reason}")
        with db_mutex:
            status = db_integrity_status()
            if status != "ok":
                repair_db_from_backup_if_needed()
            DB_RUNTIME_PATHS_READY = False
        # Each stage owns its lock briefly; never hold SQLite while snapshotting JSON state.
        init_db()
        rehydrate = rehydrate_db_from_authoritative_state_sync()
        replayed = replay_media_delivery_ledger_sync()
        ensure_sqlite_runtime_ready(
            "online recovery",
            attempts=DB_STARTUP_READY_ATTEMPTS,
            require_write=True,
            startup_sidecar_repair=True,
        )
        DB_DIAGNOSTIC_WRITES_DISABLED = not DB_DIAGNOSTIC_WRITES_CONFIGURED
        DB_DEGRADED = False
        DB_STATS_CACHE["loaded_at"] = 0.0
        DB_LAST_RECOVERY_AT = time.time()
        DB_RECOVERY_REASON = ""
        needs_target_scan = bool(
            DB_REQUIRES_TARGET_REINDEX and not rehydrate.get("targets")
        )
        DB_REQUIRES_TARGET_REINDEX = False
        if needs_target_scan and RUNTIME_CHECKPOINT_LOOP and not RUNTIME_CHECKPOINT_LOOP.is_closed():
            def schedule_target_reindex():
                asyncio.create_task(
                    build_target_media_index(
                        delete_duplicates=False,
                        reason="online_db_recovery",
                    )
                )

            RUNTIME_CHECKPOINT_LOOP.call_soon_threadsafe(schedule_target_reindex)
        log_event(
            "SQLite online recovery complete: "
            f"channels={rehydrate['channels']}, subscriptions={rehydrate['subscriptions']}, "
            f"targets={rehydrate['targets']}, ledger={replayed}, integrity=ok."
        )
        return True
    except Exception as exc:
        DB_DEGRADED = True
        DB_RECOVERY_REASON = f"{type(exc).__name__}: {str(exc)[:400]}"
        log_event_rate_limited(
            "db_online_recovery_failed",
            f"SQLite online recovery deferred: {DB_RECOVERY_REASON}",
            interval_seconds=120,
        )
        return False
    finally:
        with DB_OPEN_REPAIR_LOCK:
            DB_RECOVERY_ACTIVE = False
            DB_RECOVERY_THREAD_ID = 0


async def db_health_guard_loop():
    next_periodic_check = time.monotonic()
    while True:
        try:
            await asyncio.sleep(2)
            reason = ""
            if DB_RECOVERY_REQUESTED.is_set():
                reason = DB_RECOVERY_REASON or "writer requested recovery"
            elif time.monotonic() >= next_periodic_check:
                status = await run_blocking("db", db_integrity_status)
                next_periodic_check = (
                    time.monotonic() + DB_HEALTH_CHECK_INTERVAL_SECONDS
                )
                if status != "ok":
                    reason = f"periodic integrity check: {status}"
            if reason:
                await run_blocking("db", perform_db_online_recovery_sync, reason)
                next_periodic_check = (
                    time.monotonic() + DB_HEALTH_CHECK_INTERVAL_SECONDS
                )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log_event_rate_limited(
                "db_health_guard",
                f"SQLite health guard warning: {str(exc)[:180]}",
                interval_seconds=120,
            )


def checkpoint_db_for_backup():
    if not DB_FILE.exists():
        return
    conn = None
    try:
        with db_mutex:
            conn = db_connect()
            try:
                conn.execute("PRAGMA wal_checkpoint(PASSIVE);")
            finally:
                conn.close()
                conn = None
    except Exception as exc:
        log_event(f"SQLite backup checkpoint skipped: {str(exc)[:140]}")
    finally:
        if conn is not None:
            with contextlib.suppress(Exception):
                conn.close()


def prune_db_recovery_artifacts():
    patterns = (
        f"{DB_FILE.name}.corru*",
        f"{DB_FILE.name}.restor*",
        "royells_compact_*.db",
    )
    keep = max(1, DB_RECOVERY_ARTIFACT_KEEP)
    for pattern in patterns:
        files = sorted(
            [path for path in RUNTIME_DIR.glob(pattern) if path.is_file()],
            key=lambda path: path.stat().st_mtime,
        )
        for path in files[:-keep]:
            with contextlib.suppress(Exception):
                path.unlink()


def create_compact_db_backup_copy():
    if not DB_FILE.exists():
        return None
    compact_path = RUNTIME_DIR / f"royells_compact_backup_{uuid.uuid4().hex}.db"
    try:
        with db_mutex:
            checkpoint_db_for_backup()
            source_conn = db_connect()
            try:
                dest_conn = sqlite3.connect(str(compact_path), timeout=60.0)
                try:
                    source_conn.backup(dest_conn)
                    dest_conn.commit()
                finally:
                    dest_conn.close()
            finally:
                source_conn.close()
        # Destination-only compaction must not block every live DB caller.
        dest_conn = sqlite3.connect(str(compact_path), timeout=60.0)
        try:
            dest_conn.execute("PRAGMA optimize;")
            dest_conn.commit()
            dest_conn.execute("VACUUM;")
            dest_conn.commit()
        finally:
            dest_conn.close()
        if not sqlite_integrity_ok(compact_path):
            raise RuntimeError("compact SQLite backup failed integrity validation")
    except Exception:
        cleanup(compact_path)
        raise
    return compact_path


def sqlite_page_stats(conn):
    page_size = int(conn.execute("PRAGMA page_size").fetchone()[0] or 0)
    page_count = int(conn.execute("PRAGMA page_count").fetchone()[0] or 0)
    freelist_count = int(conn.execute("PRAGMA freelist_count").fetchone()[0] or 0)
    auto_vacuum = int(conn.execute("PRAGMA auto_vacuum").fetchone()[0] or 0)
    return {
        "page_size": page_size,
        "page_count": page_count,
        "freelist_count": freelist_count,
        "size_bytes": page_size * page_count,
        "freelist_bytes": page_size * freelist_count,
        "auto_vacuum": auto_vacuum,
    }


def sqlite_table_exists(conn, table_name):
    return bool(
        conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
            (str(table_name),),
        ).fetchone()
    )


def prune_sqlite_history(conn):
    """Remove only rebuildable/terminal history; unfinished queue jobs are retained."""
    terminal_statuses = tuple(
        sorted(
            {
                "uploaded",
                "uploaded_partial",
                "completed",
                "failed",
                "failed_invalid_media",
                "skipped_duplicate",
                "skipped_partial_album",
                "skipped_content_filter",
                "skipped_dead_media",
                "skipped_source_retired",
            }
        )
    )
    status_parameter_marks = ",".join("?" for _ in terminal_statuses)
    deleted = {
        "media_job_state": 0,
        "posted_uid_duplicates": 0,
        "posted_compat_history": 0,
        "target_media_legacy": 0,
        "target_metadata_compacted": 0,
        "posted_metadata_compacted": 0,
        "content_filter_hashes": 0,
        "audit_events": 0,
        "metrics": 0,
    }

    if sqlite_table_exists(conn, "media_job_state"):
        # Terminal payloads are not needed for recovery. Keep only their small
        # diagnostic summary, then bound the number of retained summaries.
        conn.execute(
            f"""
            UPDATE media_job_state
            SET messages_json='[]'
            WHERE status IN ({status_parameter_marks})
              AND COALESCE(messages_json, '') NOT IN ('', '[]')
            """,
            terminal_statuses,
        )
        cursor = conn.execute(
            f"""
            DELETE FROM media_job_state
            WHERE status IN ({status_parameter_marks})
              AND datetime(COALESCE(NULLIF(updated_at, ''), created_at))
                  < datetime('now', ?)
            """,
            (*terminal_statuses, f"-{DB_TERMINAL_JOB_RETENTION_DAYS} days"),
        )
        deleted["media_job_state"] += max(0, int(cursor.rowcount or 0))
        cursor = conn.execute(
            f"""
            DELETE FROM media_job_state
            WHERE job_id IN (
                SELECT job_id
                FROM media_job_state
                WHERE status IN ({status_parameter_marks})
                ORDER BY COALESCE(NULLIF(updated_at, ''), created_at) DESC, job_id DESC
                LIMIT -1 OFFSET ?
            )
            """,
            (*terminal_statuses, DB_TERMINAL_JOB_MAX_ROWS),
        )
        deleted["media_job_state"] += max(0, int(cursor.rowcount or 0))

    if sqlite_table_exists(conn, "target_media") and sqlite_table_exists(
        conn,
        "target_media_full_index",
    ):
        # target_media was the v19 UID set. The full index is a strict
        # superset, so migrate any legacy-only UID and remove the duplicate
        # physical copy. The compatibility table remains available but empty.
        conn.execute(
            """
            INSERT OR IGNORE INTO target_media_full_index
                (uid, message_id, indexed_at, source)
            SELECT uid, 0, ?, 'legacy_target_media'
            FROM target_media
            """,
            (now_iso(),),
        )
        cursor = conn.execute("DELETE FROM target_media")
        deleted["target_media_legacy"] = max(0, int(cursor.rowcount or 0))

    if sqlite_table_exists(conn, "posted") and sqlite_table_exists(
        conn,
        "target_media_full_index",
    ):
        target_count = int(
            conn.execute("SELECT COUNT(*) FROM target_media_full_index").fetchone()[0]
            or 0
        )
        if target_count:
            cursor = conn.execute(
                """
                DELETE FROM posted
                WHERE EXISTS (
                    SELECT 1 FROM target_media_full_index
                    WHERE target_media_full_index.uid=posted.hash
                )
                """
            )
            deleted["posted_uid_duplicates"] = max(0, int(cursor.rowcount or 0))
        cursor = conn.execute(
            """
            UPDATE posted
            SET channel='', posted_at=''
            WHERE COALESCE(channel, '') != '' OR COALESCE(posted_at, '') != ''
            """
        )
        deleted["posted_metadata_compacted"] = max(0, int(cursor.rowcount or 0))
        # No production query filters posted by channel; this legacy index
        # duplicates every retained row and was a major source of bloat.
        conn.execute("DROP INDEX IF EXISTS idx_posted_channel")
        cursor = conn.execute(
            """
            DELETE FROM posted
            WHERE rowid IN (
                SELECT rowid
                FROM posted
                ORDER BY rowid DESC
                LIMIT -1 OFFSET ?
            )
            """,
            (DB_POSTED_COMPAT_MAX_ROWS,),
        )
        deleted["posted_compat_history"] = max(0, int(cursor.rowcount or 0))

    if sqlite_table_exists(conn, "target_media_full_index"):
        cursor = conn.execute(
            """
            UPDATE target_media_full_index
            SET indexed_at='', source=''
            WHERE COALESCE(indexed_at, '') != '' OR COALESCE(source, '') != ''
            """
        )
        deleted["target_metadata_compacted"] = max(0, int(cursor.rowcount or 0))
        # No production query searches the full index by target message_id.
        # The JSON target_messages map owns that reverse lookup.
        conn.execute("DROP INDEX IF EXISTS idx_target_media_full_message")

    if not CONTENT_FILTER_ENABLED and sqlite_table_exists(
        conn,
        "content_filter_hashes",
    ):
        cursor = conn.execute("DELETE FROM content_filter_hashes")
        deleted["content_filter_hashes"] = max(0, int(cursor.rowcount or 0))

    if sqlite_table_exists(conn, "v20_audit_events"):
        cursor = conn.execute(
            """
            DELETE FROM v20_audit_events
            WHERE rowid IN (
                SELECT rowid FROM v20_audit_events
                ORDER BY CAST(created_at AS REAL) DESC, rowid DESC
                LIMIT -1 OFFSET ?
            )
            """,
            (DB_AUDIT_MAX_ROWS,),
        )
        deleted["audit_events"] = max(0, int(cursor.rowcount or 0))

    if sqlite_table_exists(conn, "book17_metrics"):
        cursor = conn.execute(
            """
            DELETE FROM book17_metrics
            WHERE rowid IN (
                SELECT rowid FROM book17_metrics
                ORDER BY recorded_at DESC, rowid DESC
                LIMIT -1 OFFSET ?
            )
            """,
            (DB_METRICS_MAX_ROWS,),
        )
        deleted["metrics"] = max(0, int(cursor.rowcount or 0))
    return deleted


def compact_live_database_locked():
    """Build, validate, and atomically swap a compact DB while DB writers wait."""
    global DB_JOURNAL_INITIALIZED, DB_RUNTIME_PATHS_READY
    compact_path = None
    try:
        current_size = DB_FILE.stat().st_size if DB_FILE.exists() else 0
        disk_snapshot = sane_disk_snapshot(DB_FILE.parent)
        if not disk_snapshot.get("trusted"):
            return {
                "compacted": False,
                "reason": "disk capacity is untrusted on this virtual filesystem",
                "disk_status": disk_snapshot.get("status", "unavailable"),
            }
        free_bytes = int(disk_snapshot.get("free") or 0)
        required_free = int(
            max(
                256 * 1024 * 1024,
                current_size * DB_COMPACT_MIN_FREE_MULTIPLIER,
            )
        )
        if free_bytes < required_free:
            return {
                "compacted": False,
                "reason": "insufficient_free_space",
                "required_free": required_free,
                "free": free_bytes,
            }

        fd, temporary_name = tempfile.mkstemp(
            prefix=f".{DB_FILE.name}.compact.",
            suffix=".db",
            dir=str(DB_FILE.parent),
        )
        os.close(fd)
        compact_path = Path(temporary_name)
        source_conn = db_connect()
        try:
            if str(source_conn.execute("PRAGMA journal_mode").fetchone()[0]).lower() == "wal":
                source_conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            destination_conn = sqlite3.connect(str(compact_path), timeout=120.0)
            try:
                source_conn.backup(destination_conn, pages=2048, sleep=0.01)
                destination_conn.commit()
            finally:
                destination_conn.close()
        finally:
            source_conn.close()

        destination_conn = sqlite3.connect(str(compact_path), timeout=120.0)
        try:
            destination_conn.execute("PRAGMA journal_mode=DELETE")
            destination_conn.execute("PRAGMA synchronous=FULL")
            destination_conn.execute("PRAGMA auto_vacuum=INCREMENTAL")
            destination_conn.execute("VACUUM")
            destination_conn.execute("PRAGMA optimize")
            destination_conn.commit()
            integrity = destination_conn.execute("PRAGMA integrity_check").fetchone()
            if not integrity or str(integrity[0]).strip().lower() != "ok":
                raise RuntimeError(
                    f"compacted SQLite integrity failed: {integrity}"
                )
        finally:
            destination_conn.close()

        with compact_path.open("rb") as handle:
            try:
                os.fsync(handle.fileno())
            except OSError:
                if os.name != "nt":
                    raise
        remove_sqlite_sidecars(DB_FILE)
        os.replace(compact_path, DB_FILE)
        compact_path = None
        _fsync_directory(DB_FILE)
        DB_JOURNAL_INITIALIZED = False
        DB_RUNTIME_PATHS_READY = False
        return {
            "compacted": True,
            "before_bytes": current_size,
            "after_bytes": DB_FILE.stat().st_size,
        }
    finally:
        if compact_path is not None:
            with contextlib.suppress(Exception):
                compact_path.unlink(missing_ok=True)


def run_db_maintenance_sync(reason="periodic", allow_compact=True):
    """Bound live growth without deleting any unfinished or authoritative media row."""
    global DB_LAST_MAINTENANCE_AT, DB_LAST_COMPACT_AT
    global DB_DIAGNOSTIC_WRITES_DISABLED
    if not DB_MAINTENANCE_ENABLED or not DB_FILE.exists() or DB_RECOVERY_ACTIVE:
        return {"skipped": True, "reason": "disabled_or_recovery"}
    if not DB_MAINTENANCE_LOCK.acquire(blocking=False):
        return {"skipped": True, "reason": "already_running"}
    try:
        with db_mutex:
            conn = db_connect()
            try:
                before = sqlite_page_stats(conn)
                conn.execute("BEGIN IMMEDIATE")
                deleted = prune_sqlite_history(conn)
                conn.commit()
                conn.execute("PRAGMA optimize")
                after_delete = sqlite_page_stats(conn)
                if (
                    after_delete["auto_vacuum"] == 2
                    and after_delete["freelist_count"]
                ):
                    conn.execute(
                        f"PRAGMA incremental_vacuum({DB_INCREMENTAL_VACUUM_PAGES})"
                    )
                conn.commit()
                after_prune = sqlite_page_stats(conn)
            except Exception:
                with contextlib.suppress(Exception):
                    conn.rollback()
                raise
            finally:
                conn.close()

            size_mb = after_prune["size_bytes"] / (1024 * 1024)
            freelist_mb = after_prune["freelist_bytes"] / (1024 * 1024)
            reclaim_percent = (
                (after_prune["freelist_count"] / after_prune["page_count"]) * 100
                if after_prune["page_count"]
                else 0.0
            )
            should_compact = bool(
                allow_compact
                and (
                    after_prune["auto_vacuum"] != 2
                    or
                    (
                        size_mb >= DB_COMPACT_MIN_SIZE_MB
                        and (
                            freelist_mb >= DB_COMPACT_MIN_FREELIST_MB
                            or reclaim_percent >= DB_COMPACT_MIN_RECLAIM_PERCENT
                        )
                    )
                )
            )
            compact_result = (
                compact_live_database_locked()
                if should_compact
                else {"compacted": False, "reason": "threshold_not_met"}
            )

        DB_LAST_MAINTENANCE_AT = time.time()
        if compact_result.get("compacted"):
            DB_LAST_COMPACT_AT = DB_LAST_MAINTENANCE_AT
        if DB_DIAGNOSTIC_WRITES_CONFIGURED:
            DB_DIAGNOSTIC_WRITES_DISABLED = False
        DB_STATS_CACHE["loaded_at"] = 0.0
        result = {
            "reason": str(reason),
            "deleted": deleted,
            "before": before,
            "after_prune": after_prune,
            **compact_result,
        }
        log_event(
            "SQLite maintenance complete: "
            f"reason={reason}, deleted={deleted}, "
            f"size={before['size_bytes'] / (1024 * 1024):.2f}MB, "
            f"free_pages={before['freelist_count']}, "
            f"compacted={bool(compact_result.get('compacted'))}, "
            f"final_size={DB_FILE.stat().st_size / (1024 * 1024):.2f}MB."
        )
        return result
    except Exception as exc:
        if is_sqlite_corruption_error(exc):
            request_db_online_recovery(f"maintenance corruption: {exc}")
        log_event_rate_limited(
            "db_maintenance_failed",
            f"SQLite maintenance deferred safely: {format_exception_for_log(exc)}",
            interval_seconds=300,
        )
        return {"skipped": True, "reason": format_exception_for_log(exc)}
    finally:
        DB_MAINTENANCE_LOCK.release()


async def db_maintenance_loop():
    if not DB_MAINTENANCE_ENABLED:
        await asyncio.Event().wait()
    await asyncio.sleep(DB_MAINTENANCE_START_DELAY_SECONDS)
    while True:
        try:
            pipeline_idle = pipeline_job_count() == 0
            await run_blocking(
                "db",
                run_db_maintenance_sync,
                "periodic_idle" if pipeline_idle else "periodic_busy",
                pipeline_idle,
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log_event_rate_limited(
                "db_maintenance_loop",
                f"SQLite maintenance loop warning: {str(exc)[:180]}",
                interval_seconds=300,
            )
        await asyncio.sleep(DB_MAINTENANCE_INTERVAL_SECONDS)


def prune_old_backups():
    snapshots = sorted([p for p in BACKUP_DIR.glob("snapshot_*") if p.is_dir()])
    keep = max(1, STATE_BACKUP_KEEP)
    for snapshot in snapshots[:-keep]:
        with contextlib.suppress(Exception):
            shutil.rmtree(snapshot)
    archives = sorted([p for p in BACKUP_DIR.glob("royells_backup_*.zip") if p.is_file()], key=lambda p: p.stat().st_mtime)
    for archive in archives[:-keep]:
        with contextlib.suppress(Exception):
            archive.unlink(missing_ok=True)


def backup_state_snapshot():
    compact_db = None
    try:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        snapshot = BACKUP_DIR / f"snapshot_{timestamp}"
        latest = BACKUP_DIR / "latest"
        flush_state_saves(timeout=60)
        try:
            compact_db = create_compact_db_backup_copy()
        except Exception as exc:
            request_db_online_recovery(f"compact backup validation failed: {exc}")
            log_event_rate_limited(
                "compact_backup_failed",
                f"Compact SQLite backup skipped; JSON/checkpoint backup continues: {str(exc)[:180]}",
                interval_seconds=300,
            )
        for src in managed_state_files():
            if src.resolve() == DB_FILE.resolve():
                continue
            rel = backup_relative_path(src)
            copy_file_atomic(src, snapshot / rel)
            copy_file_atomic(src, latest / rel)
        if compact_db and compact_db.exists():
            db_rel = Path("runtime") / DB_FILE.name
            copy_file_atomic(compact_db, snapshot / db_rel)
            copy_file_atomic(compact_db, latest / db_rel)
        prune_old_backups()
        prune_db_recovery_artifacts()
        return True
    except Exception as e:
        log_event(f"State backup failed: {e}")
        return False
    finally:
        cleanup(compact_db)


def create_backup_archive():
    backup_state_snapshot()
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    archive_path = BACKUP_DIR / f"royells_backup_{timestamp}.zip"
    compact_db = None
    try:
        with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=BACKUP_ZIP_COMPRESSLEVEL) as zf:
            manifest = {
                "created_at": now_iso(),
                "bot": "royells",
                "runtime_dir": str(RUNTIME_DIR),
                "data_dir": str(DATA_DIR),
                "db_integrity": db_integrity_status(),
                "db_size_bytes": DB_FILE.stat().st_size if DB_FILE.exists() else 0,
                "files": [],
            }
            try:
                compact_db = create_compact_db_backup_copy()
            except Exception as exc:
                request_db_online_recovery(f"portable backup validation failed: {exc}")
                manifest["db_backup_error"] = str(exc)[:300]
                compact_db = None
            if compact_db and compact_db.exists():
                zf.write(compact_db, "runtime/royells.db")
                manifest["files"].append("runtime/royells.db")
                manifest["compact_db_size_bytes"] = compact_db.stat().st_size
            for src in managed_archive_files():
                if src.resolve() == DB_FILE.resolve():
                    continue
                rel = backup_relative_path(src).as_posix()
                zf.write(src, rel)
                manifest["files"].append(rel)
            zf.writestr("manifest.json", json.dumps(manifest, indent=2, ensure_ascii=True))
    finally:
        cleanup(compact_db)
    prune_old_backups()
    log_event(f"Backup archive created: {archive_path.name} ({archive_path.stat().st_size / (1024 * 1024):.2f} MB)")
    return archive_path


def safe_zip_members(zip_path):
    """Validate restore archives against traversal, symlinks, zip bombs, and abuse."""
    max_members = max(10, env_int("ROYELLS_RESTORE_MAX_MEMBERS", "500"))
    max_bytes = max(1, env_int("ROYELLS_RESTORE_MAX_UNCOMPRESSED_MB", "2048")) * 1024 * 1024
    max_ratio = max(10, env_int("ROYELLS_RESTORE_MAX_COMPRESSION_RATIO", "200"))
    with zipfile.ZipFile(zip_path) as zf:
        members = zf.infolist()
        if len(members) > max_members:
            raise ValueError(f"backup has too many members: {len(members)} > {max_members}")
        total_size = 0
        for info in members:
            name = info.filename.replace("\\", "/")
            path = Path(name)
            if path.is_absolute() or ".." in path.parts:
                raise ValueError(f"unsafe backup path: {name}")
            if (info.external_attr >> 16) & 0o170000 == 0o120000:
                raise ValueError(f"backup symlink is not allowed: {name}")
            total_size += int(info.file_size or 0)
            if total_size > max_bytes:
                raise ValueError(f"backup expands beyond {max_bytes // (1024 * 1024)} MB")
            compressed = max(1, int(info.compress_size or 0))
            if info.file_size > 1024 * 1024 and info.file_size / compressed > max_ratio:
                raise ValueError(f"suspicious compression ratio for: {name}")
        return members


def restore_backup_archive(zip_path):
    global DB_JOURNAL_INITIALIZED
    safe_zip_members(zip_path)
    restore_root = RUNTIME_DIR / f"restore_{int(time.time())}"
    restore_root.mkdir(parents=True, exist_ok=True)
    restored = 0
    try:
        with zipfile.ZipFile(zip_path) as zf:
            zf.extractall(restore_root)
        for root_name, root in (("runtime", RUNTIME_DIR), ("data", DATA_DIR)):
            source_root = restore_root / root_name
            if not source_root.exists():
                continue
            for src in source_root.rglob("*"):
                if not src.is_file():
                    continue
                if src.name == "bot.lock":
                    continue
                dst = root / src.relative_to(source_root)
                if dst == DB_FILE:
                    if not sqlite_integrity_ok(src):
                        raise ValueError("backup archive contains an invalid SQLite database")
                    with db_mutex:
                        remove_sqlite_sidecars(DB_FILE)
                        copy_file_atomic(src, dst)
                        remove_sqlite_sidecars(DB_FILE)
                        DB_JOURNAL_INITIALIZED = False
                    if not db_integrity_ok():
                        raise RuntimeError("restored SQLite database failed integrity validation")
                else:
                    copy_file_atomic(src, dst)
                restored += 1
        return restored
    finally:
        shutil.rmtree(restore_root, ignore_errors=True)


def restore_json_backup_file(json_path):
    max_bytes = max(1, env_int("ROYELLS_RESTORE_MAX_JSON_MB", "256")) * 1024 * 1024
    if Path(json_path).stat().st_size > max_bytes:
        raise ValueError(f"JSON backup exceeds {max_bytes // (1024 * 1024)} MB")
    name = Path(json_path).name
    allowed = {path.name: state_name for state_name, path in STATE_FILES.items()}
    if name not in allowed:
        raise ValueError(f"unknown JSON state file: {name}")
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")
    state_name = allowed[name]
    atomic_json_save(STATE_FILES[state_name], data)
    with state_mutex:
        STATE[state_name] = load_json_state(state_name)
    return state_name


def reload_runtime_state_sync():
    init_state_files()
    load_source_link_report_config()
    init_db()
    ensure_sqlite_runtime_ready(
        "runtime reload",
        attempts=max(3, DB_STARTUP_READY_ATTEMPTS // 2),
        require_write=True,
        startup_sidecar_repair=True,
    )
    load_channels()
    loaded_target = load_target_full_index_from_db()
    loaded_dead = load_dead_media_from_state()
    get_db_stats(force=True)
    log_db_startup_status()
    return loaded_target, loaded_dead


async def reload_runtime_after_restore(progress=None):
    def step(text):
        log_event(text)
        if progress:
            return progress(text)
        return None

    maybe_await = step("Restore 70%: reloading JSON state and database.")
    if asyncio.iscoroutine(maybe_await):
        await maybe_await
    loaded_target, loaded_dead = await run_blocking("persistence", reload_runtime_state_sync)
    maybe_await = step(
        f"Restore 85%: loaded persisted target-index snapshot {loaded_target} uid(s), "
        f"dead media {loaded_dead} uid(s); readiness pending rebuild."
    )
    if asyncio.iscoroutine(maybe_await):
        await maybe_await
    with contextlib.suppress(Exception):
        await refresh_userbot_dialog_cache(force=True)
    with contextlib.suppress(Exception):
        await startup_peer_warmup(include_userbot=True)
    if RESTORE_RELOAD_TARGET_INDEX and TARGET_MEDIA_INDEX_ENABLED:
        maybe_await = step("Restore 90%: rebuilding target index before source admission resumes.")
        if asyncio.iscoroutine(maybe_await):
            await maybe_await
        await build_target_media_index(
            delete_duplicates=False,
            reason="restore_reload",
        )
    maybe_await = step(
        "Restore 100%: runtime and target index are ready. "
        "Source guard and sync loops continue automatically."
    )
    if asyncio.iscoroutine(maybe_await):
        await maybe_await
    return loaded_target, loaded_dead


async def restore_from_document_message(client, document_message, status_msg):
    reply = document_message
    if not reply or not reply.document:
        await safe_edit(status_msg, "Restore failed: no backup document found.")
        return

    file_name = (reply.document.file_name or "").lower()
    if not (file_name.endswith(".zip") or file_name.endswith(".json")):
        await safe_edit(status_msg, "Unsupported restore file. Send a Royells .zip backup or known state .json file.")
        return

    restore_path = DOWNLOAD_DIR / f"restore_{uuid.uuid4().hex}_{Path(file_name).name}"

    async def progress(text):
        with contextlib.suppress(Exception):
            await safe_edit(status_msg, text)

    try:
        await progress("Restore 5%: downloading backup file...")
        downloaded = await telegram_gateway_await('client.download_media', lambda: client.download_media(reply, file_name=str(restore_path)))
        restore_path = Path(downloaded or restore_path)
        await progress("Restore 20%: creating safety snapshot before restore...")
        await run_blocking("persistence", backup_state_snapshot)

        if restore_path.suffix.lower() == ".zip":
            await progress("Restore 35%: validating and extracting backup zip...")
            restored = await run_blocking("persistence", restore_backup_archive, restore_path)
            await progress(f"Restore 60%: restored {restored} file(s).")
            loaded_target, loaded_dead = await reload_runtime_after_restore(progress=progress)
            await safe_edit(
                status_msg,
                (
                    "Restore complete.\n"
                    f"Files restored: {restored}\n"
                    f"Target index loaded: {loaded_target}\n"
                    f"Dead media loaded: {loaded_dead}\n"
                    "Runtime reloaded; restart is optional unless session files were replaced."
                ),
                reply_markup=tools_keyboard(),
            )
        else:
            await progress("Restore 40%: restoring JSON state file...")
            state_name = await run_blocking("persistence", restore_json_backup_file, restore_path)
            loaded_target, loaded_dead = await reload_runtime_after_restore(progress=progress)
            await safe_edit(
                status_msg,
                (
                    "JSON restore complete.\n"
                    f"State: {state_name}\n"
                    f"Target index loaded: {loaded_target}\n"
                    f"Dead media loaded: {loaded_dead}"
                ),
                reply_markup=tools_keyboard(),
            )
        log_event(f"Restore completed from {file_name}.")
    except Exception as e:
        await safe_edit(status_msg, f"Restore failed:\n{str(e)[:900]}", reply_markup=tools_keyboard())
        log_event(f"Manual restore failed: {e}")
    finally:
        cleanup(restore_path)


async def persistent_backup_loop():
    while True:
        try:
            ok = await run_blocking("persistence", backup_state_snapshot)
            if ok:
                log_event("Persistent state backup complete.")
        except Exception as e:
            log_event(f"Persistent backup loop error: {e}")
        await asyncio.sleep(max(300, STATE_BACKUP_INTERVAL_SECONDS))


async def telegram_backup_loop():
    if not TELEGRAM_BACKUP_ENABLED or not OWNER_ID:
        log_event("Telegram auto backup disabled.")
        await asyncio.Event().wait()
    await asyncio.sleep(120)
    while True:
        archive_path = None
        try:
            archive_path = await run_blocking("persistence", create_backup_archive)
            await send_backup_document(app, OWNER_ID, archive_path, f"Royells auto backup\nTime: {format_display_datetime(seconds=True)}")
            log_event("Telegram auto backup sent to owner.")
        except Exception as e:
            log_event(f"Telegram auto backup failed: {e}")
        finally:
            cleanup(archive_path)
        await asyncio.sleep(max(3600, TELEGRAM_BACKUP_INTERVAL_SECONDS))


def diagnostic_log_event_is_actionable(text):
    """Return ``True`` only for terminal-looking log events.

    ``log_event`` is intentionally used for progress, retry and backoff telemetry.
    Feeding every line containing words such as ``timeout`` or ``invalid`` into the
    daily error counter made a healthy retry storm look like hundreds of independent
    failures. Direct worker exception reports still use ``diagnostic_increment_error``;
    this filter is only the conservative bridge for plain log text.
    """
    message = str(text or "").strip()
    lowered = message.lower()
    if not message:
        return False
    if re.search(
        r"\b(?:retry|retries|retrying|requeued|deferred|backoff|recoverable|scheduled|fallback)\b"
        r"|cooling down|waiting for|will retry",
        lowered,
    ):
        return False
    return bool(
        re.search(r"\[[^\]\r\n]{0,80}\berror\b[^\]\r\n]*\]", message, re.IGNORECASE)
        or re.search(r"\b(?:critical|fatal|unhandled exception)\b", message, re.IGNORECASE)
    )


def diagnostic_increment_error(error, context="", traceback_text=""):
    """Record an explicit exception without converting routine retries into errors."""
    text = f"{error.__class__.__name__}: {error}" if not isinstance(error, str) else error
    lowered = text.lower()
    if str(context or "") == "log_event":
        if not diagnostic_log_event_is_actionable(text):
            return
    elif not any(
        marker in lowered
        for marker in ("error", "failed", "timeout", "flood", "invalid", "0-byte", "exception", "warning")
    ) and not traceback_text:
        return
    if "0-byte" in lowered or "0 byte" in lowered:
        key = "0-byte media"
    elif "flood" in lowered:
        key = "FloodWait"
    elif "timeout" in lowered or "timed out" in lowered:
        key = "Timeout"
    elif "filenotfound" in lowered or "no such file" in lowered:
        key = "FileNotFound"
    elif "media_empty" in lowered or "media empty" in lowered:
        key = "MEDIA_EMPTY"
    elif "peer id invalid" in lowered or "peer_id_invalid" in lowered:
        key = "PEER_ID_INVALID"
    elif "channel_private" in lowered or "not accessible" in lowered:
        key = "CHANNEL_PRIVATE"
    else:
        key = text.split(":", 1)[0][:60] or "Unknown"
    diagnostic_stats["error_counts"][key] = int(diagnostic_stats["error_counts"].get(key) or 0) + 1
    recent = diagnostic_stats.setdefault("recent_errors", [])
    recent.append(
        {
            "time": now_iso(),
            "key": key,
            "context": str(context or "")[:120],
            "error": text[:500],
            "traceback": str(traceback_text or "")[-1600:],
        }
    )
    if len(recent) > 30:
        del recent[:-30]


def diagnostic_update_queue_peak():
    total = channel_download_queue.qsize() + upload_queue.qsize() + link_process_queue.qsize()
    diagnostic_stats["max_queue"] = max(int(diagnostic_stats.get("max_queue") or 0), total)
    return total


def diagnostic_note_source_retired(channel_id, reason):
    items = diagnostic_stats.setdefault("sources_retired", [])
    items.append({"time": now_iso(), "channel_id": str(channel_id), "reason": str(reason)[:180]})
    if len(items) > 200:
        del items[:-200]


def diagnostic_reset_after_success():
    diagnostic_stats["period_started_at"] = now_iso()
    diagnostic_stats["error_counts"] = {}
    diagnostic_stats["recent_errors"] = []
    diagnostic_stats["max_queue"] = diagnostic_update_queue_peak()
    diagnostic_stats["sources_retired"] = []
    diagnostic_stats["dead_media_added"] = 0
    diagnostic_stats["uploads"] = 0
    diagnostic_stats["duplicates_deleted"] = 0
    diagnostic_stats["restore_events"] = []


def diagnostic_disk_line(label, snapshot):
    """Render trusted capacity only; virtual-provider values are never advertised."""

    if bool((snapshot or {}).get("trusted")):
        return (
            f"{label}: free {int(snapshot.get('free') or 0) // (1024 * 1024)} MB "
            f"/ total {int(snapshot.get('total') or 0) // (1024 * 1024)} MB"
        )
    anomaly = str((snapshot or {}).get("anomaly") or "unavailable")
    return f"{label}: unavailable ({anomaly}; virtual filesystem capacity is untrusted)"


def generate_daily_diagnostic_report():
    diagnostic_update_queue_peak()
    subs, posted = get_db_stats()
    health = channel_status_counts()
    disk = sane_disk_snapshot(DATA_DIR)
    runtime_disk = sane_disk_snapshot(RUNTIME_DIR)
    db_size = DB_FILE.stat().st_size if DB_FILE.exists() else 0
    manifest = dict(BUILD_MANIFEST or {})
    manifest_validation = dict(BUILD_MANIFEST_VALIDATION or {})
    build_identity = str(
        manifest.get("build_id")
        or manifest.get("build_uuid")
        or manifest.get("build_number")
        or "unavailable"
    )
    build_number = str(manifest.get("build_number") or os.getenv("ROYELLS_BUILD_NUMBER") or APP_VERSION)
    manifest_status = str(manifest_validation.get("status") or "not_validated")
    runtime_identity = (
        f"boot {str(BOOT_ID or 'unknown')[:20]} | workers D{DOWNLOAD_WORKERS}/U{UPLOAD_WORKERS}/"
        f"L{LINK_WORKERS}/B{BUTTON_WORKERS} | Telegram API {TELEGRAM_API_CONCURRENCY}, "
        f"media {TELEGRAM_MEDIA_CONCURRENCY} | queue caps D{IN_MEMORY_QUEUE_MAX}/U{UPLOAD_READY_QUEUE_MAX}"
    )
    if ADAPTIVE_INTAKE_ENABLED:
        intake_status = (
            "adaptive enabled: cursor-based, sequential, pressure-aware "
            f"(startup gate {'released' if STARTUP_HOT_SCAN_COMPLETE.is_set() else 'awaiting'})"
        )
    else:
        intake_status = "adaptive disabled: startup catch-up/source guard workers own source admission"
    with state_mutex:
        clean_count = len(STATE["clean_duplicate"].get("items", {}))
        target_index_count = len(STATE.get("target_media_index", {}).get("items", {}))
        total_uploaded = STATE["total_auto_upload"].get("total_uploaded", 0)
        dead_total = len(STATE.get("dead_media", {}).get("items", {}))
    errors = diagnostic_stats.get("error_counts", {})
    error_lines = [f"- {key}: {value}" for key, value in sorted(errors.items(), key=lambda kv: (-kv[1], kv[0]))[:20]]
    recent_errors = diagnostic_stats.get("recent_errors", [])[-8:]
    recent_error_lines = []
    for item in recent_errors:
        recent_error_lines.append(f"- {item.get('time')} | {item.get('context') or item.get('key')}: {item.get('error')}")
        tb = str(item.get("traceback") or "").strip()
        if tb:
            recent_error_lines.extend("  " + line for line in tb.splitlines()[-8:])
    retired = diagnostic_stats.get("sources_retired", [])[-20:]
    retired_lines = [f"- {item['time']} | {item['channel_id']} | {item['reason']}" for item in retired]
    log_lines = list(console_logs)[-20:]
    lines = [
        "=== Royells Bot Daily Diagnostic Report ===",
        f"Generated: {format_display_datetime(seconds=True)}",
        f"Period started: {diagnostic_stats.get('period_started_at')}",
        "",
        "[System]",
        f"Uptime: {uptime()}",
        f"Memory: {current_memory_mb():.0f} MB" if current_memory_mb() else "Memory: N/A",
        f"Build: {build_identity} | number {build_number} | manifest {manifest_status}",
        f"Runtime: {runtime_identity}",
        f"Intake: {intake_status}",
        f"Pipeline phase: {str(PIPELINE_SCAN_STATUS.get('phase') or 'boot')}",
        diagnostic_disk_line("Data disk", disk),
        diagnostic_disk_line("Runtime disk", runtime_disk),
        f"DB size: {db_size / (1024 * 1024):.2f} MB",
        f"DB integrity: {db_integrity_status()}",
        f"Persistence: {persistence_io_health_snapshot()}",
        f"Session: {'BAD ' + SESSION_AUTH_INVALID_REASON[:120] if SESSION_AUTH_INVALID else 'OK'}",
        "",
        "[Queue]",
        f"Current queue: D{channel_download_queue.qsize()} U{upload_queue.qsize()} L{link_process_queue.qsize()}",
        f"Max queue this period: {diagnostic_stats.get('max_queue', 0)}",
        "",
        "[Sources]",
        f"Active: {health['active']} | Issues: {health['issues']} | Removed: {health['removed']}",
        f"Guard: {last_source_guard.get('status')} | {short_dt(last_source_guard.get('time'))}",
        f"Sync: {last_auto_sync.get('status')} | {short_dt(last_auto_sync.get('time'))}",
        f"Retired this period: {len(retired)}",
        *(retired_lines or ["- none"]),
        "",
        "[Media]",
        f"Total uploaded: {max(auto_count, total_uploaded)}",
        f"Uploads this period: {diagnostic_stats.get('uploads', 0)}",
        f"Ledger: {clean_count} | DB posted: {posted} | Target index: {target_index_count}",
        f"Dead media total: {dead_total}",
        f"Dead media added this period: {diagnostic_stats.get('dead_media_added', 0)}",
        f"Duplicates deleted this period: {diagnostic_stats.get('duplicates_deleted', 0)}",
        f"Subscriptions: {subs} active",
        "",
        "[Errors]",
        *(error_lines or ["- none"]),
        "",
        "[Error Details]",
        *(recent_error_lines or ["- none"]),
        "",
        "[Recent Logs]",
        *(log_lines or ["No recent logs."]),
    ]
    return "\n".join(str(line) for line in lines)


async def send_diagnostic_report_now(client=app, chat_id=None, reset_on_success=False):
    chat_id = chat_id or OWNER_ID
    # Integrity checks can block inside the filesystem/VFS layer far beyond
    # SQLite's busy timeout. Never run them on the asyncio event-loop thread.
    report_text = await run_blocking("control", generate_daily_diagnostic_report)
    report_path = RUNTIME_DIR / f"royells_diagnostic_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
    await run_blocking(
        "persistence",
        report_path.write_text,
        report_text,
        encoding="utf-8",
    )
    try:
        await telegram_gateway_await('client.send_document', lambda: client.send_document(
            chat_id,
            document=str(report_path),
            caption=f"Royells Daily Diagnostic Report\nTime: {format_display_datetime(seconds=True)}",
        ))
        if reset_on_success:
            diagnostic_reset_after_success()
        return True
    finally:
        cleanup(report_path)


async def diagnostic_report_loop():
    if not DIAGNOSTIC_REPORT_ENABLED or not OWNER_ID:
        log_event("Daily diagnostic report disabled.")
        await asyncio.Event().wait()
    await asyncio.sleep(300)
    while True:
        try:
            await send_diagnostic_report_now(app, OWNER_ID, reset_on_success=True)
            log_event("Daily diagnostic report sent to owner.")
        except Exception as e:
            log_event(f"Daily diagnostic report failed: {e}")
        await asyncio.sleep(DIAGNOSTIC_REPORT_INTERVAL_SECONDS)


async def send_backup_document(client, chat_id, archive_path, caption):
    path = Path(archive_path)
    if not path.exists() or path.stat().st_size <= 0:
        raise RuntimeError(f"backup archive missing or empty: {path}")
    try:
        await telegram_gateway_await('client.send_document', lambda: client.send_document(chat_id, document=str(path), caption=caption))
        return True
    except Exception as first_error:
        # Some cloud runtimes fail path streaming inside Pyrogram; retry with an explicit file handle.
        log_event(f"Backup path send failed, retrying file handle: {str(first_error)[:180]}")
        with path.open("rb") as file_obj:
            await telegram_gateway_await('client.send_document', lambda: client.send_document(chat_id, document=file_obj, file_name=path.name, caption=caption))
        return True


def trim_events(state_name, limit=1000):
    events = STATE[state_name].get("events")
    if isinstance(events, list) and len(events) > limit:
        STATE[state_name]["events"] = events[-limit:]


def log_event(text):
    print(text, flush=True)
    console_logs.append(f"[{format_display_datetime(seconds=True)}] {text}")
    with contextlib.suppress(Exception):
        diagnostic_increment_error(str(text), context="log_event")
    maybe_record_incident_from_log(text)


def log_event_rate_limited(key, text, interval_seconds=None):
    """Keep useful latency diagnostics without flooding stdout under backlog."""
    now_mono = time.monotonic()
    interval = max(
        1.0,
        float(interval_seconds or SLOW_LOG_RATE_LIMIT_SECONDS),
    )
    suppressed = 0
    with SLOW_LOG_LOCK:
        entry = SLOW_LOG_STATE.setdefault(
            str(key),
            {"last": 0.0, "suppressed": 0},
        )
        if now_mono - float(entry.get("last") or 0.0) < interval:
            entry["suppressed"] = int(entry.get("suppressed") or 0) + 1
            return False
        suppressed = int(entry.get("suppressed") or 0)
        entry["last"] = now_mono
        entry["suppressed"] = 0
    suffix = f" (suppressed {suppressed} similar events)" if suppressed else ""
    log_event(f"{text}{suffix}")
    return True


def flood_wait_delay(seconds):
    try:
        base_seconds = max(1.0, float(seconds))
    except Exception:
        base_seconds = 1.0
    jitter = random.uniform(0.0, max(0.0, FLOOD_WAIT_JITTER_SECONDS))
    scaled = base_seconds * FLOOD_WAIT_BACKOFF_MULTIPLIER + jitter
    # Telegram's requested wait is a protocol floor.  The local cap limits only
    # our additional safety multiplier; it must never shorten a long server wait.
    return max(
        base_seconds,
        min(float(FLOOD_WAIT_BACKOFF_CAP_SECONDS), scaled),
    )


def is_flood_wait_error(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    return isinstance(exc, FloodWait) or "flood_wait" in text or "floodwait" in text or "420 flood" in text


def telegram_client_role(label="", client_role=None):
    role = str(client_role or "").strip().lower()
    if role in {"bot", "userbot", "generic"}:
        return role
    text = str(label or "").lower()
    if "userbot" in text or "user bot" in text:
        return "userbot"
    if (
        re.search(r"\bbot\b", text)
        or text.startswith(("app.", "client.", "message.", "query.", "target."))
        or " via bot" in text
    ):
        return "bot"
    return "generic"


def telegram_call_uses_download_lane(label):
    """Return whether a Telegram RPC is a long-running media download."""

    return "download media" in str(label or "").strip().lower()


def should_wait_for_internal_flood_retry(attempt, retries, client_role):
    """Retry inside the gateway only when another attempt actually remains."""

    return (
        str(client_role or "").strip().lower() != "bot"
        and int(attempt or 0) < max(1, int(retries or 1))
    )


def note_global_flood_wait(exc, client_role="userbot"):
    """Record a FloodWait once per exception/role and return its remaining gate."""
    global TELEGRAM_FLOOD_UNTIL
    role = telegram_client_role(client_role=client_role)
    now_mono = time.monotonic()
    recorded_deadlines = getattr(exc, "_royells_flood_deadlines", None)
    if isinstance(recorded_deadlines, dict) and role in recorded_deadlines:
        deadline = float(recorded_deadlines.get(role) or 0.0)
        TELEGRAM_FLOOD_UNTIL_BY_ROLE[role] = max(
            float(TELEGRAM_FLOOD_UNTIL_BY_ROLE.get(role) or 0.0),
            deadline,
        )
        if role == "userbot":
            TELEGRAM_FLOOD_UNTIL = TELEGRAM_FLOOD_UNTIL_BY_ROLE[role]
        return max(0.0, deadline - now_mono)

    seconds = int(getattr(exc, "value", 0) or 0)
    if seconds <= 0:
        match = re.search(r"wait of (\d+) seconds", str(exc), re.I)
        seconds = int(match.group(1)) if match else 60
    delay = flood_wait_delay(seconds)
    metric_increment("flood_wait_events")
    deadline = now_mono + delay
    TELEGRAM_FLOOD_UNTIL_BY_ROLE[role] = max(
        float(TELEGRAM_FLOOD_UNTIL_BY_ROLE.get(role) or 0.0),
        deadline,
    )
    # Keep the old scalar for checkpoint compatibility and legacy diagnostics.
    if role == "userbot":
        TELEGRAM_FLOOD_UNTIL = TELEGRAM_FLOOD_UNTIL_BY_ROLE[role]
    with contextlib.suppress(Exception):
        deadlines = dict(recorded_deadlines or {})
        deadlines[role] = deadline
        setattr(exc, "_royells_flood_deadlines", deadlines)
        setattr(exc, "_royells_flood_recorded", True)
        setattr(exc, "_royells_flood_deadline", deadline)
        setattr(exc, "_royells_client_role", role)
    mark_runtime_checkpoint_dirty("telegram flood wait")
    return delay


def telegram_flood_gate_remaining_seconds(client_role=None):
    """Return the active FloodWait gate remaining for one role or all roles."""
    roles = (
        [telegram_client_role(client_role=client_role)]
        if client_role
        else list(TELEGRAM_FLOOD_UNTIL_BY_ROLE)
    )
    now = time.monotonic()
    return max(
        0.0,
        max((float(TELEGRAM_FLOOD_UNTIL_BY_ROLE.get(role) or 0.0) - now for role in roles), default=0.0),
    )


async def wait_global_flood_gate(label="telegram", client_role=None):
    role = telegram_client_role(label, client_role)
    while True:
        remaining = float(TELEGRAM_FLOOD_UNTIL_BY_ROLE.get(role) or 0.0) - time.monotonic()
        if remaining <= 0:
            return
        await asyncio.sleep(min(remaining, 30.0))


def begin_telegram_inflight(label, kind="api"):
    token = uuid.uuid4().hex
    with TELEGRAM_INFLIGHT_LOCK:
        TELEGRAM_INFLIGHT[token] = {
            "token": token,
            "label": str(label)[:200],
            "kind": str(kind)[:40],
            "started_at": time.time(),
            "started_iso": now_iso(),
        }
    mark_runtime_checkpoint_dirty(f"telegram inflight {kind}")
    return token


def end_telegram_inflight(token, status="done", error=""):
    if not token:
        return
    with TELEGRAM_INFLIGHT_LOCK:
        entry = TELEGRAM_INFLIGHT.pop(str(token), None)
    if entry:
        mark_runtime_checkpoint_dirty(f"telegram inflight {status}")


def is_global_transport_error(exc):
    if is_session_auth_error(exc) or is_flood_wait_error(exc):
        return False
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(marker in text for marker in (
        "broken pipe", "errno 32", "connection lost", "connection reset",
        "connection aborted", "server disconnected", "client has not been started", "transport closed"
    ))


def is_download_temp_file_missing_error(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    return (
        "no such file or directory" in text
        and (".temp" in text or "/tmp/" in text or "\\tmp\\" in text)
    )


def is_upload_source_file_missing_error(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(
        marker in text
        for marker in (
            "file missing or 0 bytes before upload",
            "incomplete download before upload",
            "upload source file missing",
            "does not represent an existing local file",
            "no such file or directory",
        )
    )


def is_temporary_network_error(exc):
    if isinstance(exc, HybridDownloadError):
        return bool(exc.retryable)
    if is_session_auth_error(exc):
        return False
    if is_download_temp_file_missing_error(exc):
        return True
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(
        marker in text
        for marker in [
            "broken pipe",
            "errno 32",
            "connection aborted",
            "connection lost",
            "connection reset",
            "timeout",
            "timed out",
            "network",
            "temporarily",
            "socket",
            "server disconnected",
            "transport",
            "client has not been started",
        ]
    )


def is_reconnectable_telegram_error(exc):
    if is_session_auth_error(exc):
        return False
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(
        marker in text
        for marker in [
            "errno 110",
            "connection timed out",
            "timed out",
            "timeout",
            "broken pipe",
            "errno 32",
            "connection lost",
            "connection reset",
            "connection aborted",
            "server disconnected",
            "transport",
            "client has not been started",
        ]
    )


def should_reconnect_telegram_error(exc):
    """Reconnect only for real transport/client loss, not normal slow API timeouts."""
    if is_session_auth_error(exc):
        return False
    text = f"{exc.__class__.__name__} {exc}".lower()
    if any(marker in text for marker in ["flood_wait", "floodwait", "peer id invalid", "peer_id_invalid"]):
        return False
    if "guard scan timed out" in text or "auto sync timed out" in text:
        return False
    if "timed out" in text or "timeout" in text:
        return False
    return any(
        marker in text
        for marker in [
            "client has not been started",
            "connection lost",
            "connection reset",
            "connection aborted",
            "broken pipe",
            "errno 32",
            "server disconnected",
        ]
    )


def is_invalid_media_upload_error(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(
        marker in text
        for marker in [
            "media_empty",
            "media empty",
            "invalid media",
            "media invalid",
            "file must be non-empty",
            "wrong file identifier",
        ]
    )


def is_media_empty_upload_error(exc):
    """Return whether Telegram rejected the current local upload artifact as empty.

    ``MEDIA_EMPTY`` is a target-side upload verdict, not proof that the source
    message is absent or permanently invalid.  It must therefore cause a fresh
    source download before any album member is classified or skipped.
    """

    text = f"{exc.__class__.__name__} {exc}".lower()
    return "media_empty" in text or "media empty" in text


def is_file_part_missing_error(exc):
    """Identify Telegram's invalid upload-session response without matching generic file errors."""
    text = f"{exc.__class__.__name__} {exc}".upper()
    return bool(re.search(r"\bFILE_PART_\d+_MISSING\b", text)) or "FILE_PART_X_MISSING" in text


class UploadSessionRecoveryError(RuntimeError):
    """The complete media upload was rebuilt once but Telegram rejected it again."""

    def __init__(self, message, files=None):
        super().__init__(message)
        self.files = [str(path) for path in (files or []) if path]
        self.retryable = True


class MediaArtifactRefreshRequired(RuntimeError):
    """The target rejected local bytes; rehydrate from the source before retrying.

    This deliberately does not inherit from ``UploadSessionRecoveryError``:
    FILE_PART_X_MISSING is a Telegram upload-session corruption while MEDIA_EMPTY
    can also be caused by a stale, partially materialized, or otherwise
    unacceptable local artifact.  Both recover through a new source download,
    but diagnostics and retry reasons must remain truthful.
    """

    def __init__(self, reason, files=None):
        super().__init__(reason)
        self.files = [str(path) for path in (files or []) if path]
        self.retryable = True


def build_fresh_download_retry_job(job, reason_code):
    """Return a bounded, file-free retry descriptor or ``None`` when exhausted."""

    retry_count = max(0, int((job or {}).get("_fresh_download_recovery_count") or 0))
    if retry_count >= FRESH_DOWNLOAD_RECOVERY_LIMIT:
        return None
    retry_job = dict(job or {})
    retry_job["files"] = []
    retry_job["_partial_download_files"] = []
    retry_job["partial_download_files"] = []
    retry_job["_partial_download_message_metas"] = []
    retry_job["partial_download_messages"] = []
    retry_job.pop("_upload_file_fingerprints", None)
    retry_job["attempt"] = 1
    retry_job["_fresh_download_recovery_count"] = retry_count + 1
    retry_job["_fresh_download_reason"] = str(reason_code or "fresh_download")[:120]
    retry_job["_fresh_download_requested_at"] = now_iso()
    return retry_job


def manual_fresh_download_deferred_delay_seconds(deferred_count):
    """Return the capped delay for a manual-link recovery after normal retries.

    Manual ``telegram_link`` jobs cannot rely on a future source scan to find the
    original post again.  The final delay is intentionally reused after the
    escalation sequence so a transient Telegram-side upload problem remains a
    durable, low-frequency retry instead of being silently dropped.
    """

    delays = MANUAL_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS
    count = max(1, int(deferred_count or 1))
    return int(delays[min(len(delays) - 1, count - 1)])


def build_manual_fresh_download_deferred_retry_job(job, reason_code):
    """Build a file-free, persisted retry for an exhausted manual-link recovery.

    This fallback is deliberately limited to a user-requested Telegram link.
    Source-managed jobs retain their existing scanner/permanent-retry policy.
    The recorded counter is capped at the final cadence, but retries continue at
    that bounded cadence until the media can be recovered or the user cancels it.
    """

    if str((job or {}).get("source") or "") != "telegram_link":
        return None
    retry_job = dict(job or {})
    deferred_count = min(
        len(MANUAL_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS),
        max(0, int(retry_job.get("_manual_fresh_download_deferred_count") or 0)) + 1,
    )
    delay_seconds = manual_fresh_download_deferred_delay_seconds(deferred_count)
    retry_job["files"] = []
    retry_job["_partial_download_files"] = []
    retry_job["partial_download_files"] = []
    retry_job["_partial_download_message_metas"] = []
    retry_job["partial_download_messages"] = []
    retry_job.pop("_upload_file_fingerprints", None)
    retry_job["attempt"] = 1
    retry_job["_manual_fresh_download_deferred_count"] = deferred_count
    retry_job["_manual_fresh_download_deferred_reason"] = str(
        reason_code or "fresh_download"
    )[:120]
    retry_job["_manual_fresh_download_deferred_requested_at"] = now_iso()
    retry_job["_manual_fresh_download_deferred_due_at"] = (
        time.time() + delay_seconds
    )
    return retry_job


def manual_fresh_download_deferred_remaining_seconds(job):
    """Return a safe remaining delay when a persisted manual retry is restored."""

    if str((job or {}).get("source") or "") != "telegram_link":
        return 0
    try:
        due_at = float((job or {}).get("_manual_fresh_download_deferred_due_at") or 0)
    except (TypeError, ValueError):
        return 0
    if due_at <= 0:
        return 0
    # A malformed/clock-skewed state record must never stall a manual request
    # indefinitely.  The largest supported cadence is the recovery ceiling.
    return max(
        0,
        min(
            MANUAL_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS[-1],
            int(max(0.0, due_at - time.time())),
        ),
    )


def source_fresh_download_deferred_delay_seconds(deferred_count):
    """Return the capped, indefinitely renewable delay for a source-owned job."""

    delays = SOURCE_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS
    count = max(1, int(deferred_count or 1))
    return int(delays[min(len(delays) - 1, count - 1)])


def build_source_fresh_download_deferred_retry_job(job, reason_code):
    """Build a durable retry for an exhausted non-manual fresh-download recovery.

    A channel scanner is an optimisation, not ownership of a source post: cursors
    can advance and retention windows can expire.  Keep the original message
    descriptor, discard only stale local artifacts, and cap the recorded cadence
    counter so this recovery remains both finite in state and renewable in time.
    """

    if str((job or {}).get("source") or "") == "telegram_link":
        return None
    retry_job = dict(job or {})
    deferred_count = min(
        len(SOURCE_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS),
        max(0, int(retry_job.get("_source_fresh_download_deferred_count") or 0)) + 1,
    )
    delay_seconds = source_fresh_download_deferred_delay_seconds(deferred_count)
    retry_job["files"] = []
    retry_job["_partial_download_files"] = []
    retry_job["partial_download_files"] = []
    retry_job["_partial_download_message_metas"] = []
    retry_job["partial_download_messages"] = []
    retry_job.pop("_upload_file_fingerprints", None)
    retry_job["attempt"] = 1
    retry_job["_source_fresh_download_deferred_count"] = deferred_count
    retry_job["_source_fresh_download_deferred_reason"] = str(
        reason_code or "fresh_download"
    )[:120]
    retry_job["_source_fresh_download_deferred_requested_at"] = now_iso()
    retry_job["_source_fresh_download_deferred_due_at"] = time.time() + delay_seconds
    return retry_job


def source_fresh_download_deferred_remaining_seconds(job):
    """Return the restart-safe remaining delay for a source-owned retry.

    A corrupt or clock-skewed deadline is capped at one renewal interval so a
    persisted descriptor can never be stranded indefinitely.
    """

    if str((job or {}).get("source") or "") == "telegram_link":
        return 0
    try:
        due_at = float(
            (job or {}).get("_source_fresh_download_deferred_due_at") or 0
        )
    except (TypeError, ValueError):
        return 0
    if due_at <= 0:
        return 0
    return max(
        0,
        min(
            SOURCE_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS[-1],
            int(max(0.0, due_at - time.time())),
        ),
    )


def source_item_unavailable_message_key(message):
    """Return the restart-stable key for one source item, or an empty string.

    The key intentionally uses the source chat/message pair rather than the
    local file name or a process-local object id.  It therefore survives a
    checkpoint restore and lets a source scan recognise that this exact post is
    already owned by a durable unavailable-media retry.
    """

    if isinstance(message, dict):
        chat_id = message.get("chat_id")
        message_id = message.get("message_id")
        media_uid = message.get("media_uid")
    else:
        chat = getattr(message, "chat", None)
        chat_id = getattr(chat, "id", None)
        message_id = getattr(message, "id", None)
        media_uid = get_media_uid(message)
    if chat_id not in (None, "") and message_id not in (None, ""):
        return f"{chat_id}:{message_id}"
    if media_uid:
        return f"uid:{str(media_uid)[:256]}"
    return ""


def source_item_unavailable_retry_delay_seconds(retry_count):
    """Return the capped 10 -> 30 -> 90 minute retry cadence for one item."""

    delays = SOURCE_ITEM_UNAVAILABLE_RETRY_DELAYS_SECONDS
    count = max(1, int(retry_count or 1))
    return int(delays[min(len(delays) - 1, count - 1)])


def normalize_source_item_unavailable_retries(entries, allowed_keys=None):
    """Return bounded JSON-safe unavailable-item state from untrusted recovery data."""

    if not isinstance(entries, dict):
        return {}
    allowed = {str(key) for key in (allowed_keys or ()) if key}
    normalized = {}
    for raw_key, raw_value in entries.items():
        if len(normalized) >= SOURCE_ITEM_UNAVAILABLE_RETRY_STATE_LIMIT:
            break
        key = str(raw_key or "")[:320]
        if not key or (allowed and key not in allowed) or not isinstance(raw_value, dict):
            continue
        try:
            retry_count = int(raw_value.get("count") or 0)
        except (TypeError, ValueError):
            retry_count = 0
        try:
            due_at = float(raw_value.get("due_at") or 0)
        except (TypeError, ValueError):
            due_at = 0.0
        normalized[key] = {
            "count": max(
                0,
                min(len(SOURCE_ITEM_UNAVAILABLE_RETRY_DELAYS_SECONDS), retry_count),
            ),
            "due_at": max(0.0, due_at),
            "reason": str(raw_value.get("reason") or "")[:160],
            "updated_at": str(raw_value.get("updated_at") or "")[:64],
        }
    return normalized


def source_item_unavailable_retries_for_job(job):
    """Read only retry entries that still belong to the job's source messages."""

    messages = (job or {}).get("messages") or []
    allowed_keys = [source_item_unavailable_message_key(message) for message in messages]
    return normalize_source_item_unavailable_retries(
        (job or {}).get("_source_item_unavailable_retries"),
        allowed_keys,
    )


def source_item_unavailable_remaining_seconds(job, message):
    """Return the remaining cooldown for one owned source item.

    A corrupt future timestamp is capped at the final cadence, so a malformed
    persisted descriptor cannot suppress a source post forever.
    """

    key = source_item_unavailable_message_key(message)
    entry = source_item_unavailable_retries_for_job(job).get(key, {})
    try:
        due_at = float(entry.get("due_at") or 0)
    except (TypeError, ValueError):
        due_at = 0.0
    if due_at <= 0:
        return 0
    return max(
        0,
        min(
            SOURCE_ITEM_UNAVAILABLE_RETRY_DELAYS_SECONDS[-1],
            int(max(0.0, due_at - time.time())),
        ),
    )


def source_item_unavailable_next_remaining_seconds(job):
    """Return the earliest item cooldown for a job, preserving album ownership."""

    entries = source_item_unavailable_retries_for_job(job)
    if not entries:
        return 0
    remaining = []
    for entry in entries.values():
        try:
            due_at = float(entry.get("due_at") or 0)
        except (TypeError, ValueError):
            due_at = 0.0
        if due_at > 0:
            remaining.append(max(0.0, due_at - time.time()))
    if not remaining:
        return 0
    return max(
        0,
        min(
            SOURCE_ITEM_UNAVAILABLE_RETRY_DELAYS_SECONDS[-1],
            int(min(remaining)),
        ),
    )


def clear_source_item_unavailable_retry(job, message):
    """Clear one item's cooldown after a complete, validated source download."""

    key = source_item_unavailable_message_key(message)
    if not key:
        return False
    entries = source_item_unavailable_retries_for_job(job)
    if key not in entries:
        return False
    entries.pop(key, None)
    job["_source_item_unavailable_retries"] = entries
    return True


def build_source_item_unavailable_retry_job(job, failed_messages, reason_code):
    """Persist an item-level empty/missing retry without discarding healthy album parts.

    The full source descriptor and all partial-download metadata remain attached
    to the returned job.  This prevents a source cursor or a restart from
    rediscovering/re-enqueuing the failed item before its bounded retry is due,
    while a recovered album member can resume from its validated checkpoint.
    """

    retry_job = dict(job or {})
    messages = retry_job.get("messages") or []
    allowed_keys = [source_item_unavailable_message_key(message) for message in messages]
    entries = normalize_source_item_unavailable_retries(
        retry_job.get("_source_item_unavailable_retries"),
        allowed_keys,
    )
    failed_keys = [
        key
        for key in (source_item_unavailable_message_key(message) for message in (failed_messages or []))
        if key
    ]
    if not failed_keys:
        return None, 0
    now_epoch = time.time()
    for key in dict.fromkeys(failed_keys):
        previous = entries.get(key, {})
        try:
            previous_count = int(previous.get("count") or 0)
        except (TypeError, ValueError):
            previous_count = 0
        retry_count = min(
            len(SOURCE_ITEM_UNAVAILABLE_RETRY_DELAYS_SECONDS),
            max(0, previous_count) + 1,
        )
        delay_seconds = source_item_unavailable_retry_delay_seconds(retry_count)
        entries[key] = {
            "count": retry_count,
            "due_at": now_epoch + delay_seconds,
            "reason": str(reason_code or "source_item_unavailable")[:160],
            "updated_at": now_iso(),
        }
    retry_job["files"] = []
    retry_job.pop("_upload_file_fingerprints", None)
    retry_job["attempt"] = 1
    retry_job["_source_item_unavailable_retries"] = entries
    return retry_job, max(1, source_item_unavailable_next_remaining_seconds(retry_job))


def plan_fresh_download_retry(job, reason_code, normal_delay_seconds):
    """Choose normal recovery, then a durable owner-specific renewal cadence."""

    retry_job = build_fresh_download_retry_job(job, reason_code)
    if retry_job is not None:
        return retry_job, max(0, int(normal_delay_seconds or 0)), False
    retry_job = build_manual_fresh_download_deferred_retry_job(job, reason_code)
    if retry_job is not None:
        return (
            retry_job,
            manual_fresh_download_deferred_delay_seconds(
                retry_job.get("_manual_fresh_download_deferred_count")
            ),
            True,
        )
    retry_job = build_source_fresh_download_deferred_retry_job(job, reason_code)
    if retry_job is None:
        return None, 0, False
    return (
        retry_job,
        source_fresh_download_deferred_delay_seconds(
            retry_job.get("_source_fresh_download_deferred_count")
        ),
        True,
    )


def retain_fresh_download_retry_for_recovery(retry_job, reason):
    """Persist a fresh-download retry if ephemeral scheduler admission fails.

    ``retry_later`` is intentionally a non-terminal state.  It retains the
    exact source message metadata for checkpoint/queue recovery and leaves the
    existing processing reservation intact, so neither FILE_PART_X_MISSING nor
    MEDIA_EMPTY can turn a previously admitted channel post into a missed item.
    """

    if not isinstance(retry_job, dict) or not retry_job.get("job_id"):
        return False
    record_download_job(retry_job, "retry_later", reason, files=[])
    record_total_job(retry_job, "queued_download", reason)
    record_sync_item(retry_job, "retry_later", reason)
    log_event(
        "Fresh-download retry scheduler unavailable; durable descriptor "
        f"retained for recovery: {retry_job.get('job_id', '')}."
    )
    return True


def _hash_upload_file_sync(path):
    digest = hashlib.sha256()
    with open(path, "rb") as file_obj:
        while True:
            chunk = file_obj.read(UPLOAD_FILE_HASH_CHUNK_BYTES)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def validate_upload_files_sync(files, expected=None):
    """Validate every source path and return stable size/checksum metadata."""
    expected = expected if isinstance(expected, dict) else {}
    fingerprints = {}
    for raw_path in files or []:
        path = str(raw_path or "")
        if not path:
            raise FileNotFoundError("upload source path is empty")
        file_path = Path(path)
        if not file_path.is_file():
            raise FileNotFoundError(f"upload source file missing: {path}")
        size = file_path.stat().st_size
        if size <= 0:
            raise ValueError(f"upload source file is zero bytes: {path}")
        checksum = _hash_upload_file_sync(file_path)
        prior = expected.get(path)
        if isinstance(prior, dict):
            if int(prior.get("size") or 0) != size or str(prior.get("sha256") or "") != checksum:
                raise ValueError(f"upload source checksum changed: {path}")
        fingerprints[path] = {"size": int(size), "sha256": checksum}
    return fingerprints


async def ensure_upload_file_fingerprints(job, files, force_verify=False):
    expected = job.get("_upload_file_fingerprints")
    normalized_files = [str(path) for path in (files or []) if path]
    if isinstance(expected, dict) and not force_verify:
        current_paths = set(normalized_files)
        if current_paths and current_paths == set(expected):
            valid_sizes = True
            for path in normalized_files:
                try:
                    size = Path(path).stat().st_size
                except OSError:
                    valid_sizes = False
                    break
                if size <= 0 or size != int(expected[path].get("size") or 0):
                    valid_sizes = False
                    break
            if valid_sizes:
                return expected
    fingerprints = await run_blocking(
        "media",
        validate_upload_files_sync,
        normalized_files,
        expected if isinstance(expected, dict) else {},
    )
    job["_upload_file_fingerprints"] = fingerprints
    return fingerprints


def _discard_upload_sidecars(files):
    """Delete only known upload-session sidecars, never the source media itself."""
    removed = 0
    markers = (".upload", ".uploading", ".part", ".session")
    for raw_path in files or []:
        path = Path(str(raw_path))
        candidates = [Path(f"{path}{marker}") for marker in markers]
        if path.parent == RUNTIME_DIR:
            candidates.extend(
                child
                for child in RUNTIME_DIR.glob(f"{path.name}.*")
                if any(marker in child.name.lower() for marker in markers)
            )
        for candidate in candidates:
            if candidate == path:
                continue
            try:
                if candidate.is_file():
                    candidate.unlink()
                    removed += 1
            except OSError:
                pass
    cache_dir = RUNTIME_DIR / "upload_cache"
    if cache_dir.is_dir():
        for child in list(cache_dir.iterdir()):
            try:
                if child.is_file():
                    child.unlink()
                    removed += 1
                elif child.is_dir():
                    shutil.rmtree(child)
                    removed += 1
            except OSError:
                continue
    return removed


async def reset_upload_session_state(job, files, reason):
    """Invalidate every reusable upload artifact before a fresh source download.

    A ``FILE_PART_X_MISSING`` response means Telegram's remote upload session is
    unusable.  It is possible for a watchdog, restart cleanup, or failed local
    transfer to remove/change the spool file at the same time.  That secondary
    condition must not mask the session error or turn the job into an upload
    retry against a vanished file: the caller always proceeds with a file-free
    download retry.
    """
    metric_increment("upload_session_resets")
    metric_increment("upload_cache_invalidations")
    job["_upload_session_generation"] = int(job.get("_upload_session_generation") or 0) + 1
    job.pop("_uploaded_media", None)
    job.pop("_input_media", None)
    job.pop("_upload_cache", None)
    job.pop("_upload_session", None)
    job.pop("_upload_state", None)
    job.pop("_upload_handles", None)
    # A prior fingerprint belongs to the rejected byte stream.  Retaining it
    # could make a later fresh file look like a checksum mutation rather than a
    # valid new upload source.
    job.pop("_upload_file_fingerprints", None)
    job.pop("_upload_recovery_local_artifact_error", None)
    await run_blocking("media", _discard_upload_sidecars, list(files or []))
    verification_error = None
    try:
        await ensure_upload_file_fingerprints(job, files, force_verify=True)
    except (OSError, ValueError) as exc:
        # Do not retry an upload whose local source disappeared or changed.  The
        # outer FILE_PART handler intentionally clears ``files`` and rebuilds
        # the job from Telegram source metadata.
        verification_error = exc
        job.pop("_upload_file_fingerprints", None)
        job["_upload_recovery_local_artifact_error"] = format_exception_for_log(exc)[:240]
        metric_increment("upload_recovery_local_artifact_unavailable")
    metric_increment("upload_session_recreated")
    recovery_detail = (
        f" local-artifact={str(verification_error)[:120]}"
        if verification_error is not None
        else ""
    )
    log_event(
        f"Upload session invalidated; fresh download retry required: "
        f"generation={job['_upload_session_generation']} reason={str(reason)[:160]}"
        f"{recovery_detail}"
    )


async def recover_upload_session_state(job, files, reason):
    if V21_ENGINE is not None:
        return await V21_ENGINE.upload_recovery.recover(
            job=job,
            files=files,
            reason=reason,
            reset_callback=reset_upload_session_state,
        )
    return await reset_upload_session_state(job, files, reason)


def format_exception_for_log(exc):
    text = str(exc).strip()
    return f"{exc.__class__.__name__}: {text}" if text else exc.__class__.__name__


def is_permanent_dead_media_error(exc):
    # A routing adapter can label a final transport attempt as "permanent" after
    # its own retry budget expires.  That is not evidence that a Telegram media UID
    # is permanently bad: the 2026-08-10 runtime log shows timed-out playable albums
    # being poisoned by exactly that inference.  Only explicit source-side absence
    # may enter the durable dead-media list.
    cause = getattr(exc, "cause", None)
    text = f"{exc.__class__.__name__} {exc} {cause or ''}".lower()
    # Error wrappers occasionally retain more than one upstream message.  A
    # recoverable target/local-artifact signal must always win over an incidental
    # source-looking phrase so MEDIA_EMPTY, FILE_PART, validation, or preparation
    # failures cannot poison a playable source UID.
    if any(
        marker in text
        for marker in (
            "media_empty",
            "media empty",
            "invalid media",
            "media invalid",
            "file_part_",
            "source media preparation",
            "fresh download",
            "0-byte",
            "zero-byte",
            "incomplete download",
        )
    ):
        return False
    # Only deterministic source-side absence is terminal. Local empty/truncated
    # files, preparation errors, MEDIA_EMPTY, and generic "invalid media" replies
    # are recoverable through a fresh file reference/download and must never poison
    # the permanent UID skip list.
    return any(
        marker in text
        for marker in [
            "message_id_invalid",
            "message id invalid",
            "source message deleted",
            "source media no longer available",
            "source media unavailable",
        ]
    )


def should_skip_dead_media_now(exc, attempt):
    return is_permanent_dead_media_error(exc) and int(attempt or 1) >= DEAD_MEDIA_SKIP_AFTER_ATTEMPTS


def is_session_auth_error(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    return any(
        marker in text
        for marker in [
            "authkeyunregistered",
            "auth key unregistered",
            "authkeyduplicated",
            "auth_key_duplicated",
            "same authorization key",
            "session revoked",
            "session expired",
            "session password needed",
            "unauthorized",
            "user deactivated",
            "user is deactivated",
        ]
    )


def mark_session_auth_invalid(reason):
    global SESSION_AUTH_INVALID, SESSION_AUTH_INVALID_REASON
    SESSION_AUTH_INVALID = True
    SESSION_AUTH_INVALID_REASON = str(reason)[:500]
    last_source_guard.update({"status": "paused session auth", "time": now_iso(), "queued": 0})
    last_auto_sync.update({"status": "paused session auth", "time": now_iso(), "queued": 0})
    log_event(f"Telegram user session paused: {SESSION_AUTH_INVALID_REASON}")


def clear_session_auth_invalid():
    global SESSION_AUTH_INVALID, SESSION_AUTH_INVALID_REASON
    if SESSION_AUTH_INVALID:
        log_event("Telegram user session validation recovered.")
    SESSION_AUTH_INVALID = False
    SESSION_AUTH_INVALID_REASON = ""


def context_requires_userbot(context):
    text = str(context or "").lower()
    bot_only_markers = [" via bot", "validate bot", "send via bot", "bot target", "bot worker", "bot source"]
    return not any(marker in text for marker in bot_only_markers)


def schedule_userbot_reconnect(reason):
    if not AUTOMATIC_USERBOT_RECONNECT_ENABLED:
        log_event_rate_limited(
            "telegram_transport_recovery_disabled",
            f"Telegram transport recovery disabled: {str(reason)[:160]}",
            interval_seconds=300,
        )
        return
    try:
        loop = asyncio.get_running_loop()
        log_event_rate_limited(
            "telegram_transport_recovery_scheduled",
            f"Telegram transport recovery scheduled: {str(reason)[:160]}",
            interval_seconds=120,
        )
        loop.create_task(recover_userbot_connection(reason))
    except RuntimeError:
        pass


async def recover_userbot_connection(reason):
    global last_telegram_reconnect, TELEGRAM_TRANSPORT_GENERATION
    if SESSION_AUTH_INVALID:
        log_event("Telegram reconnect skipped: user session is invalid/duplicated and needs a new session string.")
        return
    now = time.time()
    if now - last_telegram_reconnect < TELEGRAM_RECONNECT_COOLDOWN_SECONDS:
        return
    async with telegram_reconnect_lock:
        now = time.time()
        if now - last_telegram_reconnect < TELEGRAM_RECONNECT_COOLDOWN_SECONDS:
            log_event_rate_limited(
                "telegram_transport_recovery_cooldown",
                "Telegram transport recovery request deferred by cooldown.",
                interval_seconds=120,
            )
            return
        last_telegram_reconnect = now
        previous_generation = TELEGRAM_TRANSPORT_GENERATION
        log_event(
            f"Telegram transport recovery generation {previous_generation}: "
            f"{str(reason)[:160]}"
        )
        try:
            with contextlib.suppress(Exception):
                await asyncio.wait_for(userbot.stop(), timeout=30)
            await asyncio.sleep(1)
            await asyncio.wait_for(userbot.start(), timeout=90)
            TELEGRAM_TRANSPORT_GENERATION = previous_generation + 1
            with contextlib.suppress(Exception):
                await refresh_userbot_dialog_cache(force=True)
            log_event(
                f"Telegram transport generation {TELEGRAM_TRANSPORT_GENERATION} ready; "
                "pending jobs may resume without process restart."
            )
        except Exception as e:
            log_event(f"Telegram transport recovery failed: {e}")
            last_telegram_reconnect = time.time() - max(0, TELEGRAM_RECONNECT_COOLDOWN_SECONDS - 30)

async def wait_for_telegram_client(context="telegram"):
    if SESSION_AUTH_INVALID and context_requires_userbot(context):
        raise RuntimeError(
            "Telegram user session invalid/duplicated. Generate a new ROYELLS_USER_SESSION_STRING "
            f"and stop every other process using the old session. Reason: {SESSION_AUTH_INVALID_REASON}"
        )
    waited = 0
    while telegram_reconnect_lock.locked() and waited < 60:
        await asyncio.sleep(1)
        waited += 1
    if waited:
        log_event(f"{context} waited {waited}s for Telegram reconnect.")


async def wait_while_session_invalid(component):
    logged = False
    while SESSION_AUTH_INVALID:
        if not logged:
            log_event(
                f"{component} paused: Telegram user session is duplicated/invalid. "
                "Generate a new ROYELLS_USER_SESSION_STRING and stop all old Spaces using it."
            )
            logged = True
        await asyncio.sleep(max(30, SESSION_AUTH_PAUSE_SECONDS))


def unique_existing_paths(paths):
    seen = set()
    result = []
    for raw in paths:
        path = Path(raw)
        key = str(path.resolve()) if path.exists() else str(path)
        if key in seen:
            continue
        seen.add(key)
        result.append(path)
    return result


def pyrogram_session_name_for_client(client, label):
    name = str(getattr(client, "name", "") or "").strip()
    if name:
        return name
    return USER_SESSION if str(label).lower() == "userbot" else SESSION_NAME


def remove_pyrogram_session_bundle(session_name, reason=""):
    removed = 0
    if not session_name:
        return removed
    for root in unique_existing_paths((SESSION_DIR, RUNTIME_DIR, DATA_DIR)):
        try:
            root.mkdir(parents=True, exist_ok=True)
            for path in root.glob(f"{session_name}.session*"):
                if path.is_file():
                    path.unlink(missing_ok=True)
                    removed += 1
        except Exception as exc:
            log_event(
                f"Pyrogram session cleanup skipped for {root}: "
                f"{str(exc)[:140]} reason={reason[:80]}"
            )
    return removed


def probe_pyrogram_session_storage(reason="startup"):
    SESSION_DIR.mkdir(parents=True, exist_ok=True)
    probe = SESSION_DIR / f".pyrogram_session_probe_{BOOT_ID}_{threading.get_ident()}.session"
    conn = None
    try:
        conn = sqlite3.connect(str(probe), timeout=30.0)
        conn.execute("CREATE TABLE IF NOT EXISTS probe (id INTEGER PRIMARY KEY, reason TEXT)")
        conn.execute("INSERT INTO probe (reason) VALUES (?)", (str(reason)[:120],))
        conn.commit()
        return True
    finally:
        if conn is not None:
            with contextlib.suppress(Exception):
                conn.close()
        with contextlib.suppress(Exception):
            probe.unlink(missing_ok=True)
        remove_sqlite_sidecars(probe)


async def start_telegram_client_safely(client, label, max_attempts=3):
    """Start a Pyrogram client without converting FloodWait into a restart loop."""
    last_error = None
    for attempt in range(1, max(1, max_attempts) + 1):
        try:
            probe_pyrogram_session_storage(f"{label} startup attempt {attempt}")
            await client.start()
            log_event(f"{label} Telegram client started.")
            return True
        except FloodWait as e:
            last_error = e
            wait_for = int(getattr(e, "value", 0) or 0)
            if wait_for <= 0:
                match = re.search(r"wait of (\d+) seconds", str(e), re.I)
                wait_for = int(match.group(1)) if match else 60
            wait_for = max(5, min(wait_for + 5, 7200))
            log_event(f"{label} startup FloodWait: sleeping {wait_for}s before retry {attempt}/{max_attempts}.")
            await asyncio.sleep(wait_for)
        except ConnectionError as e:
            last_error = e
            if "already connected" in str(e).lower():
                log_event(f"{label} already connected during startup; continuing.")
                return True
            raise
        except Exception as e:
            last_error = e
            if is_sqlite_open_error(e):
                session_name = pyrogram_session_name_for_client(client, label)
                can_reset_session = (
                    str(label).lower() == "bot"
                    or bool(USER_SESSION_STRING)
                    or env_bool("ROYELLS_ALLOW_PYROGRAM_SESSION_FILE_RESET", False)
                )
                removed = 0
                if can_reset_session:
                    removed = remove_pyrogram_session_bundle(
                        session_name,
                        reason=f"{label} startup sqlite open repair",
                    )
                else:
                    raise RuntimeError(
                        f"{label} Pyrogram session database cannot open and no "
                        "ROYELLS_USER_SESSION_STRING is configured for safe rebuild."
                    ) from e
                log_event(
                    f"{label} Pyrogram session storage open failed on attempt "
                    f"{attempt}/{max_attempts}: {str(e)[:180]}; "
                    f"removed {removed} session file(s), retrying."
                )
                with contextlib.suppress(Exception):
                    await asyncio.wait_for(client.stop(), timeout=10)
                await asyncio.sleep(min(15, 2 * attempt))
                continue
            if is_session_auth_error(e):
                mark_session_auth_invalid(e)
                with contextlib.suppress(Exception):
                    await notify_session_problem(e)
            raise
    raise RuntimeError(f"{label} could not start after startup retries. Last error: {last_error!r}")


async def notify_session_problem(reason):
    global last_session_warning
    now = time.time()
    if now - last_session_warning < 1800:
        return
    last_session_warning = now
    text = (
        "Royells session warning.\n"
        "Telegram user session may be expired/revoked.\n"
        "Need a new ROYELLS_USER_SESSION_STRING.\n\n"
        f"Reason: {str(reason)[:500]}"
    )
    with contextlib.suppress(Exception):
        await telegram_gateway_await('app.send_message', lambda: app.send_message(OWNER_ID, text))
    log_event(text.replace("\n", " | "))


async def session_validator_loop():
    await asyncio.sleep(90)
    while True:
        try:
            await tg_call(
                "session validate bot",
                app.get_me,
                retries=1,
                _client_role="bot",
            )
            await tg_call(
                "session validate userbot",
                userbot.get_me,
                retries=1,
                _client_role="userbot",
            )
            clear_session_auth_invalid()
        except Exception as e:
            if is_session_auth_error(e):
                mark_session_auth_invalid(e)
                await notify_session_problem(e)
            elif should_reconnect_telegram_error(e):
                schedule_userbot_reconnect(f"session validator: {e}")
            else:
                log_event(f"Session validator warning: {str(e)[:160]}")
        await asyncio.sleep(1800)


async def telegram_gateway_await(label, factory, timeout_seconds=None, retries=None, client_role=None):
    """Central gateway for direct Pyrogram requests with isolated control capacity."""
    retries = max(1, int(retries or TELEGRAM_CALL_RETRIES))
    client_role = telegram_client_role(label, client_role)
    if timeout_seconds is None:
        lowered = str(label).lower()
        if "download_media" in lowered:
            timeout_seconds = DOWNLOAD_MEDIA_TIMEOUT_SECONDS
        elif any(token in lowered for token in ("send_document", "send_video", "send_media_group")):
            timeout_seconds = UPLOAD_SEND_TIMEOUT_SECONDS
        else:
            timeout_seconds = TELEGRAM_CALL_TIMEOUT_SECONDS
    last_error = None
    for attempt in range(1, retries + 1):
        started = time.monotonic()
        inflight_token = ""
        try:
            inflight_token = begin_telegram_inflight(label, "control")
            try:
                await wait_global_flood_gate(label, client_role)
                async with telegram_control_semaphore:
                    result = await asyncio.wait_for(factory(), timeout=max(5, int(timeout_seconds)))
            finally:
                end_telegram_inflight(inflight_token)
            duration = time.monotonic() - started
            if duration >= float(os.getenv("ROYELLS_SLOW_API_SECONDS", "5")):
                metric_increment("slow_api_operations")
                log_event_rate_limited(
                    f"slow_gateway:{label}",
                    f"Slow Telegram gateway: {label} duration={duration:.2f}s attempt={attempt}",
                )
            return result
        except asyncio.CancelledError:
            raise
        except FloodWait as exc:
            last_error = exc
            delay = note_global_flood_wait(exc, client_role)
            log_event_rate_limited(
                f"gateway_flood:{telegram_client_role(label, client_role)}:{label}",
                f"Telegram gateway FloodWait: {label} role={client_role} "
                f"delay={delay}s attempt={attempt}",
                interval_seconds=max(60, min(900, delay)),
            )
            if not should_wait_for_internal_flood_retry(attempt, retries, client_role):
                raise
            await wait_global_flood_gate(label, client_role)
        except asyncio.TimeoutError as exc:
            last_error = TimeoutError(f"{label} timed out after {timeout_seconds}s")
            if attempt >= retries:
                raise last_error from exc
            await asyncio.sleep(min(10, 2 * attempt))
        except Exception as exc:
            last_error = exc
            if is_session_auth_error(exc):
                mark_session_auth_invalid(exc)
                raise
            if should_reconnect_telegram_error(exc):
                schedule_userbot_reconnect(f"gateway {label}: {exc}")
            if not is_temporary_network_error(exc) or attempt >= retries:
                raise
            await asyncio.sleep(min(10, 2 * attempt))
    raise last_error or RuntimeError(f"Telegram gateway failed: {label}")


async def tg_call(label, func, *args, retries=None, **kwargs):
    retries = retries or TELEGRAM_CALL_RETRIES
    call_timeout = kwargs.pop("_timeout_seconds", TELEGRAM_CALL_TIMEOUT_SECONDS)
    requested_role = kwargs.pop("_client_role", None)
    inferred_role = telegram_client_role(label, requested_role)
    client_role = "userbot" if inferred_role == "generic" else inferred_role
    last_error = None
    for attempt in range(1, retries + 1):
        inflight_token = ""
        try:
            inflight_token = begin_telegram_inflight(label, "api")
            if client_role == "userbot":
                await wait_for_telegram_client(label)
            await wait_global_flood_gate(label, client_role)
            try:
                call_semaphore = (
                    telegram_download_semaphore
                    if telegram_call_uses_download_lane(label)
                    else telegram_api_semaphore
                )
                async with call_semaphore:
                    call = func(*args, **kwargs)
                    started = time.monotonic()
                    if call_timeout and call_timeout > 0:
                        result = await asyncio.wait_for(call, timeout=max(5, call_timeout))
                    else:
                        result = await call
                    duration = time.monotonic() - started
                    if duration >= float(os.getenv("ROYELLS_SLOW_API_SECONDS", "5")):
                        metric_increment("slow_api_operations")
                        log_event_rate_limited(
                            f"slow_api:{label}",
                            f"Slow Telegram API: {label} duration={duration:.2f}s attempt={attempt}",
                        )
                    return result
            finally:
                end_telegram_inflight(inflight_token)
        except asyncio.TimeoutError as e:
            last_error = TimeoutError(f"{label} timed out after {call_timeout}s")
            if attempt >= retries:
                raise last_error
            delay = min(30, 2 * attempt)
            log_event(f"{label} timed out, retry {attempt}/{retries} in {delay}s")
            await asyncio.sleep(delay)
        except FloodWait as e:
            last_error = e
            with contextlib.suppress(Exception):
                setattr(e, "_royells_client_role", client_role)
            delay = note_global_flood_wait(e, client_role)
            if not should_wait_for_internal_flood_retry(attempt, retries, client_role):
                raise
            await wait_global_flood_gate(label, client_role)
        except Exception as e:
            last_error = e
            if is_session_auth_error(e):
                if client_role == "userbot":
                    mark_session_auth_invalid(e)
                    with contextlib.suppress(Exception):
                        asyncio.create_task(notify_session_problem(e))
                raise
            if client_role == "userbot" and should_reconnect_telegram_error(e):
                schedule_userbot_reconnect(f"{label}: {e}")
            if not is_temporary_network_error(e) or attempt >= retries:
                raise
            delay = min(30, 2 * attempt)
            log_event(f"{label} temporary network issue, retry {attempt}/{retries} in {delay}s")
            await asyncio.sleep(delay)
    raise last_error


async def fetch_scan_media_group(label, msg, retries=None):
    """Fetch one album for source scans with cache and pacing to avoid Telegram FloodWait storms."""
    global LAST_SCAN_ALBUM_PREFETCH_AT
    chat = getattr(msg, "chat", None)
    chat_id = getattr(chat, "id", None)
    message_id = getattr(msg, "id", None)
    media_group_id = getattr(msg, "media_group_id", None)
    if chat_id is None or message_id is None or not media_group_id:
        return []
    cache_key = f"{chat_id}:{media_group_id}"
    now = time.monotonic()
    cached = MEDIA_GROUP_FETCH_CACHE.get(cache_key)
    if cached and now - float(cached.get("time") or 0.0) <= SCAN_ALBUM_PREFETCH_CACHE_SECONDS:
        return list(cached.get("messages") or [])

    async with MEDIA_GROUP_FETCH_LOCK:
        now = time.monotonic()
        cached = MEDIA_GROUP_FETCH_CACHE.get(cache_key)
        if cached and now - float(cached.get("time") or 0.0) <= SCAN_ALBUM_PREFETCH_CACHE_SECONDS:
            return list(cached.get("messages") or [])
        wait_for = SCAN_ALBUM_PREFETCH_MIN_INTERVAL_SECONDS - (now - LAST_SCAN_ALBUM_PREFETCH_AT)
        if wait_for > 0:
            await asyncio.sleep(wait_for)
        try:
            album = await tg_call(
                label,
                userbot.get_media_group,
                chat_id,
                message_id,
                retries=retries,
                _client_role="userbot",
                _timeout_seconds=SCAN_ALBUM_PREFETCH_TIMEOUT_SECONDS,
            )
        except Exception as exc:
            error_text = f"{type(exc).__name__} {exc}".lower()
            deterministic_missing = any(
                marker in error_text
                for marker in (
                    "message_id_invalid",
                    "message id invalid",
                    "media group not found",
                    "not part of a media group",
                )
            )
            if not deterministic_missing:
                raise
            album = []
        finally:
            # Failed attempts are paced too; otherwise a hot missing group spins and
            # bypasses the global minimum interval.
            LAST_SCAN_ALBUM_PREFETCH_AT = time.monotonic()
        deduplicated = {}
        for message in list(album or []):
            message_chat_id = getattr(getattr(message, "chat", None), "id", None)
            message_group_id = getattr(message, "media_group_id", None)
            item_id = int(getattr(message, "id", 0) or 0)
            if (
                message_chat_id != chat_id
                or str(message_group_id or "") != str(media_group_id)
                or item_id <= 0
            ):
                continue
            deduplicated[item_id] = message
        messages = [deduplicated[item_id] for item_id in sorted(deduplicated)]
        MEDIA_GROUP_FETCH_CACHE[cache_key] = {
            "time": LAST_SCAN_ALBUM_PREFETCH_AT,
            "messages": messages,
        }
        if len(MEDIA_GROUP_FETCH_CACHE) > SCAN_ALBUM_PREFETCH_CACHE_MAX:
            stale_count = len(MEDIA_GROUP_FETCH_CACHE) - SCAN_ALBUM_PREFETCH_CACHE_MAX
            for old_key, _old in sorted(
                MEDIA_GROUP_FETCH_CACHE.items(),
                key=lambda item: float(item[1].get("time") or 0.0),
            )[:stale_count]:
                MEDIA_GROUP_FETCH_CACHE.pop(old_key, None)
        return list(messages)


def uptime():
    return str(datetime.now() - BOT_START).split(".")[0]


def runtime_admin_ids():
    ids = {int(OWNER_ID)} if OWNER_ID else set()
    ids.update(int(item) for item in ENV_ADMIN_IDS if item)
    try:
        with state_mutex:
            cfg = STATE.get("runtime_config", {})
            for item in cfg.get("admins", []) or []:
                if str(item).isdigit():
                    ids.add(int(item))
    except Exception:
        pass
    return {item for item in ids if item > 0}


def is_admin_user_id(uid):
    try:
        return int(uid or 0) in runtime_admin_ids()
    except Exception:
        return False


def is_owner(uid):
    return is_admin_user_id(uid)


ADMIN_FILTER = filters.create(
    lambda _filter, _client, update: is_admin_user_id(
        getattr(getattr(update, "from_user", None), "id", 0)
    )
)


async def safe_edit(msg, text, reply_markup=None, parse_mode=None):
    try:
        await telegram_gateway_await(
            "control edit_message_text",
            lambda: msg.edit_text(
                text,
                disable_web_page_preview=True,
                reply_markup=reply_markup,
                parse_mode=parse_mode,
            ),
            timeout_seconds=TELEGRAM_CONTROL_TIMEOUT_SECONDS,
            retries=TELEGRAM_CONTROL_RETRIES,
        )
        await asyncio.sleep(0)
    except MessageNotModified:
        pass
    except Exception as exc:
        log_event_rate_limited(
            "control_edit_failed",
            f"Dashboard/control edit skipped after bounded retries: {str(exc)[:160]}",
        )
        return False
    return True


def is_manual_telegram_link_job(job):
    return str((job or {}).get("source") or "") == "telegram_link"


async def update_manual_link_status(job, text, reply_markup=None):
    if not is_manual_telegram_link_job(job):
        return
    status_msg = job.get("status_msg")
    if status_msg:
        await safe_edit(status_msg, text, reply_markup=reply_markup)
        return
    chat_id = job.get("status_chat_id")
    message_id = job.get("status_message_id")
    if chat_id and message_id:
        with contextlib.suppress(Exception):
            await telegram_gateway_await('app.edit_message_text', lambda: app.edit_message_text(
                int(chat_id),
                int(message_id),
                text,
                disable_web_page_preview=True,
                reply_markup=reply_markup,
            ))


def cleanup(*paths):
    if V21_ENGINE is not None:
        V21_ENGINE.cleanup_engine.cleanup_paths(
            [p for p in paths if p],
            force=False,
            reason="legacy cleanup request",
        )
        return
    for p in paths:
        try:
            if p and os.path.exists(p):
                os.remove(p)
        except Exception:
            pass


def track_download_file(path, owner=""):
    if not path:
        return
    with contextlib.suppress(Exception):
        resolved = str(Path(path).resolve())
        active_download_files.add(resolved)
        if V21_ENGINE is not None:
            V21_ENGINE.cleanup_engine.track(
                resolved,
                owner=owner or "legacy-download",
                state="active",
            )
    mark_runtime_checkpoint_dirty("download file tracked")


def untrack_download_files(paths):
    for path in paths or []:
        with contextlib.suppress(Exception):
            active_download_files.discard(str(Path(path).resolve()))
    if V21_ENGINE is not None:
        V21_ENGINE.cleanup_engine.untrack([path for path in paths or [] if path])
    mark_runtime_checkpoint_dirty("download file untracked")


def defer_download_cleanup(paths, reason="download attempt cleanup"):
    """Delay removal of Pyrogram .temp files so cancelled downloads can unwind."""
    deadline = time.time() + DOWNLOAD_ATTEMPT_CLEANUP_GRACE_SECONDS
    changed = False
    deferred_paths = []
    for path in paths or []:
        if not path:
            continue
        with contextlib.suppress(Exception):
            resolved = str(Path(path).resolve())
            active_download_files.add(resolved)
            deferred_download_cleanup[resolved] = deadline
            deferred_paths.append(resolved)
            changed = True
    if V21_ENGINE is not None and deferred_paths:
        V21_ENGINE.cleanup_engine.defer(deferred_paths, reason=reason)
    if changed:
        mark_runtime_checkpoint_dirty(str(reason)[:80])


def reap_deferred_download_cleanup(force=False):
    now = time.time()
    deleted = 0
    freed = 0
    if V21_ENGINE is not None:
        deleted, freed = V21_ENGINE.cleanup_engine.reap_deferred(force=force)
    for path, deadline in list(deferred_download_cleanup.items()):
        if not force and now < float(deadline or 0):
            continue
        if not force:
            if path in protected_download_file_paths():
                deferred_download_cleanup[path] = now + max(
                    30,
                    DOWNLOAD_ATTEMPT_CLEANUP_GRACE_SECONDS,
                )
                continue
        try:
            size = os.path.getsize(path) if os.path.exists(path) else 0
            if os.path.exists(path):
                os.remove(path)
                deleted += 1
                freed += size
            active_download_files.discard(path)
            deferred_download_cleanup.pop(path, None)
        except Exception:
            deferred_download_cleanup[path] = now + max(30, DOWNLOAD_ATTEMPT_CLEANUP_GRACE_SECONDS // 2)
    if deleted:
        mark_runtime_checkpoint_dirty("deferred download cleanup reaped")
    return deleted, freed


def directory_size_bytes(path):
    total = 0
    try:
        for item in Path(path).rglob("*"):
            if item.is_file():
                total += item.stat().st_size
    except Exception:
        return total
    return total


def job_download_file_paths(job):
    paths = set()
    if not isinstance(job, dict):
        return paths
    for key in ("files", "_partial_download_files", "partial_download_files"):
        for path in job.get(key, []) or []:
            if not path:
                continue
            with contextlib.suppress(Exception):
                paths.add(str(Path(path).resolve()))
    return paths


def protected_download_file_paths():
    """Files still owned by queued/running media jobs must not be storage-cleaned."""
    paths = set(active_download_files)
    with active_worker_jobs_lock:
        for item in active_worker_jobs.values():
            paths.update(job_download_file_paths((item or {}).get("job") or {}))
    for queue_obj in (channel_download_queue, upload_queue):
        with contextlib.suppress(Exception):
            for job in queue_obj.queued_jobs():
                paths.update(job_download_file_paths(job))
    with contextlib.suppress(Exception):
        for entry in list(retry_admission_queue._queue):
            if len(entry) >= 6 and isinstance(entry[5], dict):
                paths.update(job_download_file_paths(entry[5]))
    terminal_statuses = {
        "uploaded",
        "uploaded_partial",
        "failed",
        "failed_invalid_media",
        "skipped_duplicate",
        "skipped_dead_media",
        "worker_fallback_queued",
    }
    with contextlib.suppress(Exception):
        with state_mutex:
            records = [
                deepcopy(STATE.get("upload_queue", {}).get("items", {})),
                deepcopy(STATE.get("download_queue", {}).get("items", {})),
            ]
        for items in records:
            for record in items.values():
                if not isinstance(record, dict):
                    continue
                if str(record.get("status") or "").lower() in terminal_statuses:
                    continue
                paths.update(job_download_file_paths(record))
    return paths


def cleanup_download_dir_if_needed(force=False):
    try:
        root = DOWNLOAD_DIR.resolve()
        if not root.exists():
            return 0, 0
        deferred_deleted, deferred_freed = reap_deferred_download_cleanup(force=force)
        limit_bytes = max(1, DOWNLOAD_STORAGE_LIMIT_MB) * 1024 * 1024
        min_free_bytes = max(1, MIN_FREE_STORAGE_MB) * 1024 * 1024
        usage = sane_disk_snapshot(DOWNLOAD_DIR)
        current_size = directory_size_bytes(root)
        free_ok = (
            not usage.get("trusted")
            or int(usage.get("free") or 0) >= min_free_bytes
        )
        if not force and current_size <= limit_bytes and free_ok:
            return deferred_deleted, deferred_freed

        files = []
        protected_paths = protected_download_file_paths()
        for item in root.rglob("*"):
            if not item.is_file():
                continue
            resolved = item.resolve()
            if root not in resolved.parents:
                continue
            if str(resolved) in protected_paths:
                continue
            try:
                files.append((resolved.stat().st_mtime, resolved.stat().st_size, resolved))
            except Exception:
                continue
        files.sort()

        deleted = deferred_deleted
        freed = deferred_freed
        for _, size, item in files:
            try:
                item.unlink(missing_ok=True)
                deleted += 1
                freed += size
                current_size = max(0, current_size - size)
                usage = sane_disk_snapshot(DOWNLOAD_DIR)
                free_ok = (
                    not usage.get("trusted")
                    or int(usage.get("free") or 0) >= min_free_bytes
                )
                if not force and current_size <= limit_bytes and free_ok:
                    break
            except Exception:
                continue
        return deleted, freed
    except Exception:
        return 0, 0


def prune_runtime_caches():
    removed_paths, _freed = reap_deferred_download_cleanup(force=False)
    for path in list(active_download_files):
        if os.path.exists(path):
            continue
        active_download_files.discard(path)
        deferred_download_cleanup.pop(path, None)
        removed_paths += 1
    return {
        "missing_download_paths": removed_paths,
        "processing_cache": processing_cache.prune(),
        "posted_compat_cache": posted_hash_index.prune(),
    }


def current_memory_mb():
    status_path = Path("/proc/self/status")
    try:
        for line in status_path.read_text(encoding="utf-8", errors="ignore").splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) / 1024
    except Exception:
        pass
    return 0


def request_automatic_process_restart(reason):
    """Automatic full-process restart is permanently disabled to protect queue ownership."""
    reason_text = str(reason or "automatic recovery")[:500]
    log_event(f"Automatic process restart permanently suppressed: {reason_text}")
    return False


async def event_loop_heartbeat_loop():
    global EVENT_LOOP_HEARTBEAT_TS
    interval = max(1, HARD_WATCHDOG_HEARTBEAT_SECONDS)
    expected = time.monotonic()
    while True:
        now_mono = time.monotonic()
        lag = max(0.0, now_mono - expected)
        metric_set("event_loop_lag_seconds", round(lag, 3))
        metric_set_peak("event_loop_lag_peak_seconds_by_kind", "main", lag)
        with RUNTIME_METRICS_LOCK:
            RUNTIME_METRICS["event_loop_lag_peak_seconds"] = max(float(RUNTIME_METRICS.get("event_loop_lag_peak_seconds") or 0), lag)
        if lag >= float(os.getenv("ROYELLS_EVENT_LOOP_LAG_LOG_SECONDS", "1.0")):
            log_event_rate_limited(
                "event_loop_latency",
                f"Event loop latency warning: {lag:.3f}s",
            )
        EVENT_LOOP_HEARTBEAT_TS = time.time()
        expected = now_mono + interval
        await asyncio.sleep(interval)


def start_hard_watchdog(label="main"):
    """Start a daemon watchdog with diagnostic-only behavior by default."""
    global HARD_WATCHDOG_STARTED, EVENT_LOOP_HEARTBEAT_TS
    if HARD_WATCHDOG_STARTED or not HARD_WATCHDOG_ENABLED:
        return False
    HARD_WATCHDOG_STARTED = True
    EVENT_LOOP_HEARTBEAT_TS = time.time()
    started_at = time.time()

    def watchdog_runner():
        memory_over_count = 0
        stall_reported = False
        while True:
            time.sleep(max(5, HARD_WATCHDOG_HEARTBEAT_SECONDS))
            now = time.time()
            stalled_for = now - EVENT_LOOP_HEARTBEAT_TS
            if now - started_at > HARD_WATCHDOG_STARTUP_GRACE_SECONDS and stalled_for > HARD_WATCHDOG_STALL_SECONDS:
                if not stall_reported:
                    stall_reported = True
                    print(f"Hard watchdog alert: {label} event loop stalled for {int(stalled_for)}s.", flush=True)
                    print("=== BLOCKED MAIN EVENT LOOP STACK ===\n" + _format_main_loop_stack(), flush=True)
                    print("=== LAST ASYNC TASK SNAPSHOT ===\n" + json.dumps(ASYNC_TASK_SNAPSHOT, ensure_ascii=False, indent=2)[:30000], flush=True)
                    print("=== QUEUE/SEMAPHORE OWNERSHIP ===\n" + json.dumps({
                        "queues": {"download": channel_download_queue.qsize(), "upload": upload_queue.qsize(), "link": link_process_queue.qsize(), "button": button_queue.qsize(), "job_state_db": job_state_db_queue.qsize(), "critical_db": critical_db_write_queue.qsize()},
                        "workers": list(active_worker_jobs.values()),
                        "semaphores": {"telegram_api_locked": telegram_api_semaphore.locked(), "telegram_download_locked": telegram_download_semaphore.locked(), "telegram_media_locked": telegram_media_semaphore.locked(), "source_link_locked": source_link_check_semaphore.locked()},
                        "executors": executor_diagnostics(),
                        "retry_queue": retry_admission_queue.qsize(),
                        "persistence": persistence_io_health_snapshot(),
                    }, default=str, ensure_ascii=False, indent=2)[:30000], flush=True)
                    if HARD_WATCHDOG_FORCE_RESTART:
                        request_automatic_process_restart(
                            f"{label} event loop stalled for {int(stalled_for)}s"
                        )
            else:
                stall_reported = False
            mem = current_memory_mb()
            if MEMORY_RESTART_LIMIT_MB > 0 and mem > MEMORY_RESTART_LIMIT_MB:
                memory_over_count += 1
                if memory_over_count >= 3:
                    print(
                        f"Hard watchdog memory alert: {label} memory {mem:.0f} MB exceeded limit {MEMORY_RESTART_LIMIT_MB} MB.",
                        flush=True,
                    )
                    if HARD_WATCHDOG_FORCE_RESTART:
                        request_automatic_process_restart(
                            f"{label} memory {mem:.0f} MB exceeded {MEMORY_RESTART_LIMIT_MB} MB"
                        )
                    memory_over_count = 0
            else:
                memory_over_count = 0

    threading.Thread(target=watchdog_runner, name=f"royells-hard-watchdog-{label}", daemon=True).start()
    log_event(
        f"Hard watchdog active for {label}: mode={'restart' if HARD_WATCHDOG_FORCE_RESTART else 'diagnostic-only'}, "
        f"stall>{HARD_WATCHDOG_STALL_SECONDS}s, memory>{MEMORY_RESTART_LIMIT_MB or 'off'} MB."
    )
    return True


def _format_main_loop_stack():
    frame = sys._current_frames().get(MAIN_LOOP_THREAD_ID) if MAIN_LOOP_THREAD_ID else None
    return "".join(traceback.format_stack(frame)) if frame else "main loop frame unavailable"


def install_asyncio_diagnostics(loop):
    global MAIN_LOOP_THREAD_ID
    MAIN_LOOP_THREAD_ID = threading.get_ident()
    if not ASYNC_DIAGNOSTICS_ENABLED:
        loop.set_debug(False)
        return
    loop.set_debug(True)
    loop.slow_callback_duration = float(os.getenv("ROYELLS_SLOW_CALLBACK_SECONDS", "1.0"))
    previous_factory = loop.get_task_factory()
    def factory(loop, coro, context=None):
        if previous_factory:
            try:
                task = previous_factory(loop, coro, context=context)
            except TypeError:
                task = previous_factory(loop, coro)
        else:
            task = asyncio.Task(coro, loop=loop, context=context) if context is not None else asyncio.Task(coro, loop=loop)
        ASYNC_TASK_META[task] = {"created": time.monotonic(), "reported": set(), "name": getattr(coro, "__qualname__", repr(coro))}
        task.add_done_callback(lambda done: ASYNC_TASK_META.pop(done, None))
        return task
    loop.set_task_factory(factory)


async def asyncio_diagnostics_loop():
    global ASYNC_TASK_SNAPSHOT
    while True:
        now = time.monotonic()
        rows = []
        for task in asyncio.all_tasks():
            if task is asyncio.current_task():
                continue
            meta = ASYNC_TASK_META.setdefault(task, {"created": now, "reported": set(), "name": task.get_name()})
            age = now - meta["created"]
            stack = task.get_stack(limit=8)
            location = " -> ".join(f"{f.f_code.co_name}:{f.f_lineno}" for f in stack[-4:]) or "waiting/native"
            rows.append({"name": task.get_name(), "coroutine": meta["name"], "age": round(age, 1), "state": getattr(task, "_state", "unknown"), "stack": location})
            for threshold in ASYNC_DIAGNOSTIC_THRESHOLDS:
                if age >= threshold and threshold not in meta["reported"]:
                    meta["reported"].add(threshold)
                    log_event(f"Async task >{threshold}s: {meta['name']} state={getattr(task, '_state', '?')} stack={location}")
        ASYNC_TASK_SNAPSHOT = rows
        await asyncio.sleep(5)


async def runtime_resource_guard_loop():
    while True:
        try:
            deleted, freed = await run_blocking("media", cleanup_download_dir_if_needed)
            cache_prune = prune_runtime_caches()
            history_prune = prune_runtime_state_history()
            if deleted:
                log_event(f"Storage guard cleaned {deleted} download file(s), freed {freed // (1024 * 1024)} MB.")
            if (
                any(cache_prune.values())
                or any(history_prune.get("removed", {}).values())
            ):
                log_event_rate_limited(
                    "runtime_retention",
                    "Runtime retention complete: "
                    f"caches={cache_prune}, history={history_prune.get('removed', {})}.",
                    interval_seconds=300,
                )
            diagnostic_update_queue_peak()
            gc.collect()
            mem = current_memory_mb()
            if mem:
                log_event(f"Runtime guard: memory {mem:.0f} MB, download queue {channel_download_queue.qsize()}, upload queue {upload_queue.qsize()}.")
        except Exception as e:
            log_event(f"Runtime guard error: {e}")
        await asyncio.sleep(max(60, min(STORAGE_MONITOR_INTERVAL_SECONDS, MEMORY_GC_INTERVAL_SECONDS)))


async def v21_event_bus_loop():
    if V21_ENGINE is None:
        await asyncio.Event().wait()
    while True:
        try:
            drained = V21_ENGINE.bus.drain(max_per_topic=500)
            if drained:
                metric_increment("v21_events_drained", drained)
            snapshot = V21_ENGINE.bus.snapshot()
            backlog = sum(int(value or 0) for value in snapshot.get("topics", {}).values())
            metric_set("v21_event_backlog", backlog)
        except Exception as exc:
            log_event_rate_limited(
                "v21_event_bus",
                f"v21 event bus loop error: {str(exc)[:160]}",
                interval_seconds=60,
            )
        await asyncio.sleep(1)


async def outbound_keepalive_loop():
    if not KEEPALIVE_PING_URLS:
        log_event("Outbound keepalive disabled: no ping URL configured.")
        await asyncio.Event().wait()
    await asyncio.sleep(60)
    while True:
        for url in KEEPALIVE_PING_URLS:
            now = time.monotonic()
            backoff_until = float(KEEPALIVE_URL_BACKOFF_UNTIL.get(url) or 0.0)
            if backoff_until > now:
                log_event_rate_limited(
                    f"keepalive_backoff:{url}",
                    f"Keepalive ping skipped for {url}: backoff {int(backoff_until - now)}s remaining.",
                    interval_seconds=900,
                )
                continue
            try:
                response = await run_blocking("control", requests.get, url, timeout=15)
                status_code = int(getattr(response, "status_code", 0) or 0)
                if status_code == 429:
                    retry_after = 0
                    with contextlib.suppress(Exception):
                        retry_after = int(
                            (getattr(response, "headers", {}) or {}).get(
                                "Retry-After", 0
                            )
                        )
                    backoff = max(
                        KEEPALIVE_RATE_LIMIT_BACKOFF_SECONDS,
                        retry_after,
                    )
                    KEEPALIVE_URL_BACKOFF_UNTIL[url] = time.monotonic() + backoff
                    log_event(
                        f"Keepalive ping {url}: 429; backing off {backoff}s."
                    )
                elif status_code >= 500:
                    KEEPALIVE_URL_BACKOFF_UNTIL[url] = time.monotonic() + KEEPALIVE_ERROR_BACKOFF_SECONDS
                    log_event(
                        f"Keepalive ping {url}: {status_code}; backing off {KEEPALIVE_ERROR_BACKOFF_SECONDS}s."
                    )
                elif 200 <= status_code < 400:
                    KEEPALIVE_URL_BACKOFF_UNTIL.pop(url, None)
                    log_event_rate_limited(
                        f"keepalive_ok:{url}",
                        f"Keepalive ping {url}: {status_code}",
                        interval_seconds=max(KEEPALIVE_PING_INTERVAL_SECONDS, 900),
                    )
                else:
                    # A permanent/configuration 4xx is not a successful keepalive.
                    # Back off for a long window instead of hammering a bad URL.
                    backoff = max(
                        KEEPALIVE_RATE_LIMIT_BACKOFF_SECONDS,
                        KEEPALIVE_ERROR_BACKOFF_SECONDS,
                    )
                    KEEPALIVE_URL_BACKOFF_UNTIL[url] = time.monotonic() + backoff
                    log_event_rate_limited(
                        f"keepalive_client_error:{url}",
                        f"Keepalive ping {url}: {status_code}; URL/configuration "
                        f"backoff {backoff}s.",
                        interval_seconds=backoff,
                    )
            except Exception as e:
                KEEPALIVE_URL_BACKOFF_UNTIL[url] = time.monotonic() + KEEPALIVE_ERROR_BACKOFF_SECONDS
                log_event(f"Keepalive ping failed for {url}: {str(e)[:120]}")
            await asyncio.sleep(2)
        await asyncio.sleep(max(60, KEEPALIVE_PING_INTERVAL_SECONDS))


async def delete_incoming_message(message):
    with contextlib.suppress(Exception):
        await telegram_gateway_await('message.delete', lambda: message.delete())


def schedule_user_side_delete(message, delay=None):
    """Delete a user's private message later without touching support-channel copies."""
    delay = SUPPORT_USER_MESSAGE_DELETE_DELAY_SECONDS if delay is None else delay
    try:
        delay = int(delay)
    except Exception:
        delay = SUPPORT_USER_MESSAGE_DELETE_DELAY_SECONDS
    if delay <= 0 or not message:
        return False

    async def _delete_later():
        try:
            await asyncio.sleep(delay)
            await telegram_gateway_await(
                "message.delete delayed",
                lambda: message.delete(),
                timeout_seconds=TELEGRAM_CONTROL_TIMEOUT_SECONDS,
                retries=1,
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log_event_rate_limited(
                "support_user_delayed_delete",
                f"Delayed private message delete skipped: {str(exc)[:120]}",
                interval_seconds=300,
            )

    asyncio.create_task(_delete_later())
    return True


URL_RE = re.compile(
    r"(https?://[^\s<>()]+|(?:t\.me|telegram\.me|telegram\.dog)/[^\s<>()]+)",
    flags=re.I,
)


def extract_first_url(text):
    """Return the first clean URL from pasted text so captions do not break link processors."""
    raw = str(text or "").strip()
    match = URL_RE.search(raw)
    if not match:
        return raw if raw.startswith("http") else ""
    url = match.group(1).strip().strip(".,;)]}>\"'")
    if re.match(r"^(t\.me|telegram\.me|telegram\.dog)/", url, flags=re.I):
        url = "https://" + url
    return url


def detect_link_platform(url):
    text = (extract_first_url(url) or url or "").lower()
    if "t.me/" in text or "telegram.me/" in text or "telegram.dog/" in text:
        return "telegram"
    return "unsupported"


def canonical_link_url(url, platform="telegram"):
    clean = extract_first_url(url) or str(url or "").strip()
    clean = clean.strip()
    if not clean:
        return ""
    return clean.split("?", 1)[0].rstrip("/") or clean


def parse_telegram_message_link(url):
    """Parse public, /s/, and /c/ Telegram post links into (chat_ref, msg_id)."""
    clean = canonical_link_url(url, "telegram")
    if re.match(r"^(t\.me|telegram\.me|telegram\.dog)/", clean, flags=re.I):
        clean = "https://" + clean
    match = re.search(
        r"(?:https?://)?(?:t\.me|telegram\.me|telegram\.dog)/(?:s/)?(?:(?:c/(\d+))|([A-Za-z0-9_]{4,}))/?/(\d+)(?:/)?$",
        clean,
        flags=re.I,
    )
    if not match:
        return None, None
    private_id, username, message_id = match.groups()
    if private_id:
        return int(f"-100{private_id}"), int(message_id)
    return f"@{username.lower()}", int(message_id)


def should_offload_link(platform):
    if not WORKER_QUEUE_GROUP_ID and not WORKER_HTTP_URLS:
        return False
    if platform == "telegram":
        if not OFFLOAD_TELEGRAM_LINKS:
            return False
        ready, reason = worker_queue_transport_ready()
        if not ready:
            log_event(f"Worker queue unavailable; Telegram link will use local queue: {reason}")
        return ready
    return False


def build_worker_queue_payload(url, platform, requester_id, status_msg=None, **extra):
    task_id = stable_uid("worker_task", requester_id, url, time.time(), uuid.uuid4().hex[:8])
    payload = {
        "royells_queue": 1,
        "kind": "task",
        "task_id": task_id,
        "platform": platform,
        "url": url,
        "requester_id": int(requester_id),
        "status_chat_id": int(status_msg.chat.id) if status_msg else 0,
        "status_message_id": int(status_msg.id) if status_msg else 0,
        "target_chat_id": int(TARGET_CHAT_ID),
        "created_at": now_iso(),
    }
    if SOURCE_LINK_REPORT_CHAT_ID:
        payload["source_link_report_chat_id"] = int(SOURCE_LINK_REPORT_CHAT_ID)
    for key, value in extra.items():
        if value not in (None, ""):
            payload[key] = value
    if WORKER_QUEUE_SECRET:
        payload["secret"] = WORKER_QUEUE_SECRET
    return payload


def build_worker_queue_ping_payload():
    payload = {
        "royells_queue": 1,
        "kind": "ping",
        "task_id": stable_uid("worker_ping", now_iso(), uuid.uuid4().hex[:8]),
        "created_at": now_iso(),
        "target_chat_id": int(TARGET_CHAT_ID),
    }
    if WORKER_QUEUE_SECRET:
        payload["secret"] = WORKER_QUEUE_SECRET
    return payload


def parse_worker_queue_payload(text):
    raw_text = (text or "").strip()
    if raw_text.startswith("/royells_queue") or raw_text.startswith("/royells_task"):
        parts = raw_text.split(maxsplit=1)
        raw_text = parts[1] if len(parts) > 1 else ""
    if raw_text.startswith("```") and raw_text.endswith("```"):
        raw_text = raw_text.strip("`").strip()
    if not raw_text.startswith("{"):
        start = raw_text.find("{")
        end = raw_text.rfind("}")
        if start >= 0 and end > start:
            raw_text = raw_text[start : end + 1]
    try:
        data = json.loads(raw_text or "")
    except Exception:
        return None
    if not isinstance(data, dict) or data.get("royells_queue") != 1:
        return None
    if WORKER_QUEUE_SECRET and data.get("secret") != WORKER_QUEUE_SECRET:
        return None
    return data


def record_worker_queue_task(payload, status="queued", detail=""):
    task_id = str(payload.get("task_id") or "")
    if not task_id:
        return
    with state_mutex:
        items = STATE["worker_queue"].setdefault("items", {})
        old = items.get(task_id, {})
        items[task_id] = {
            **old,
            "task_id": task_id,
            "platform": payload.get("platform", "unknown"),
            "url": payload.get("url", ""),
            "requester_id": payload.get("requester_id"),
            "status_chat_id": payload.get("status_chat_id"),
            "status_message_id": payload.get("status_message_id"),
            "queue_message_id": payload.get("queue_message_id") or old.get("queue_message_id"),
            "worker_id": payload.get("worker_id") or old.get("worker_id", ""),
            "status": status,
            "detail": str(detail or old.get("detail", ""))[:500],
            "created_at": old.get("created_at", payload.get("created_at") or now_iso()),
            "updated_at": now_iso(),
        }
        events = STATE["worker_queue"].setdefault("events", [])
        events.append({"time": now_iso(), "task_id": task_id, "status": status, "detail": str(detail)[:180]})
        if len(events) > 1000:
            STATE["worker_queue"]["events"] = events[-1000:]
        if len(items) > 800:
            ordered = sorted(items.values(), key=lambda item: item.get("updated_at", ""))
            keep = {item["task_id"] for item in ordered[-600:] if item.get("task_id")}
            STATE["worker_queue"]["items"] = {tid: item for tid, item in items.items() if tid in keep}
        save_state("worker_queue")


def update_worker_queue_result(payload):
    status = str(payload.get("status") or "unknown")
    detail = payload.get("message", "")
    record_worker_queue_task(payload, status=status, detail=detail)


def record_worker_queue_heartbeat(payload):
    """Persist the latest worker heartbeat so the dashboard exposes transport health."""
    with state_mutex:
        STATE["worker_queue"]["last_worker_seen"] = now_iso()
        STATE["worker_queue"]["last_worker_id"] = payload.get("worker_id", "")
        STATE["worker_queue"]["last_worker_status"] = payload.get("status", payload.get("kind", "heartbeat"))
        STATE["worker_queue"]["last_worker_message"] = str(payload.get("message", ""))[:300]
        save_state("worker_queue")


def record_worker_queue_transport(status, detail="", message_id=None):
    """Persist master-to-group transport health for dashboard diagnostics."""
    with state_mutex:
        STATE["worker_queue"]["last_transport_status"] = str(status)[:40]
        STATE["worker_queue"]["last_transport_detail"] = str(detail)[:300]
        STATE["worker_queue"]["last_transport_message_id"] = message_id
        STATE["worker_queue"]["last_transport_time"] = now_iso()
        save_state("worker_queue")


def worker_queue_stats():
    with state_mutex:
        items = list(STATE.get("worker_queue", {}).setdefault("items", {}).values())
        last_worker_seen = STATE.get("worker_queue", {}).get("last_worker_seen", "")
        last_worker_id = STATE.get("worker_queue", {}).get("last_worker_id", "")
        last_worker_status = STATE.get("worker_queue", {}).get("last_worker_status", "")
        last_transport_status = STATE.get("worker_queue", {}).get("last_transport_status", "")
        last_transport_detail = STATE.get("worker_queue", {}).get("last_transport_detail", "")
        last_transport_time = STATE.get("worker_queue", {}).get("last_transport_time", "")
    pending_statuses = {"queued", "sent", "processing", "claimed"}
    done_statuses = {"uploaded", "duplicate", "skipped", "done"}
    failed_statuses = {"failed", "error"}
    pending = sum(1 for item in items if item.get("status") in pending_statuses)
    done = sum(1 for item in items if item.get("status") in done_statuses)
    failed = sum(1 for item in items if item.get("status") in failed_statuses)
    last = max(items, key=lambda item: item.get("updated_at", ""), default={})
    worker_seen_age = seconds_since_iso(last_worker_seen) if last_worker_seen else 10**9
    worker_stale_after = max(300, WORKER_QUEUE_HEARTBEAT_SECONDS * 3)
    worker_alive = bool(last_worker_seen and worker_seen_age <= worker_stale_after)
    return {
        "total": len(items),
        "pending": pending,
        "done": done,
        "failed": failed,
        "last_status": last.get("status", "none"),
        "last_time": last.get("updated_at", ""),
        "last_platform": last.get("platform", ""),
        "last_worker_seen": last_worker_seen,
        "last_worker_id": last_worker_id,
        "last_worker_status": last_worker_status,
        "worker_alive": worker_alive,
        "worker_seen_age": worker_seen_age,
        "worker_stale_after": worker_stale_after,
        "last_transport_status": last_transport_status,
        "last_transport_detail": last_transport_detail,
        "last_transport_time": last_transport_time,
    }


def worker_queue_transport_ready():
    """Return whether master should offload new link work to external workers."""
    if WORKER_HTTP_URLS:
        return True, "http configured"
    if not WORKER_QUEUE_GROUP_ID:
        return False, "queue group missing"
    if not WORKER_QUEUE_REQUIRE_HEARTBEAT:
        return True, "heartbeat check disabled"
    qstats = worker_queue_stats()
    if qstats.get("worker_alive"):
        return True, "worker heartbeat fresh"
    return False, "worker heartbeat missing/stale"


async def send_worker_queue_message(queue_text):
    """Send queue transport through the private group with userbot first and bot-history fallback."""
    primary_sent = None
    bot_sent = None
    errors = []
    if not WORKER_QUEUE_GROUP_ID:
        record_worker_queue_transport("skipped", "worker queue group not configured")
        raise RuntimeError("Worker queue group is not configured.")
    if WORKER_QUEUE_SEND_VIA_USERBOT:
        try:
            primary_sent = await tg_call(
                "worker queue send via userbot",
                userbot.send_message,
                WORKER_QUEUE_GROUP_ID,
                queue_text,
                disable_web_page_preview=True,
                retries=2,
            )
        except Exception as e:
            errors.append(f"userbot: {str(e)[:160]}")
    if primary_sent:
        record_worker_queue_transport("ok", "task sent through userbot", getattr(primary_sent, "id", None))
        return primary_sent
    if WORKER_QUEUE_SEND_VIA_BOT:
        try:
            bot_sent = await telegram_gateway_await('app.send_message', lambda: app.send_message(
                WORKER_QUEUE_GROUP_ID,
                queue_text[:4000],
                disable_web_page_preview=True,
            ))
        except Exception as e:
            errors.append(f"bot: {str(e)[:160]}")
    if bot_sent:
        record_worker_queue_transport(
            "bot_history",
            "task sent by main bot; worker backlog scanner will claim it",
            getattr(bot_sent, "id", None),
        )
        return bot_sent
    record_worker_queue_transport("failed", " | ".join(errors or ["userbot sender disabled or unavailable"]))
    raise RuntimeError(
        "Worker queue transport failed. Add main bot, queue bot, and logged-in userbot to the queue group, "
        "or set ROYELLS_WORKER_HTTP_URLS to the worker Space URL. "
        + " | ".join(errors or ["all group senders disabled or unavailable"])
    )


async def send_worker_http_payload(payload):
    """Push a worker task directly to worker Space HTTP /queue, protected by the shared queue secret."""
    if not WORKER_HTTP_URLS:
        raise RuntimeError("Worker HTTP URL is not configured.")
    errors = []
    headers = {"Content-Type": "application/json"}
    if WORKER_QUEUE_SECRET:
        headers["X-Royells-Secret"] = WORKER_QUEUE_SECRET
    for base_url in WORKER_HTTP_URLS:
        endpoint = base_url.rstrip("/") + "/queue"
        try:
            response = await run_blocking(
                "control", requests.post,
                endpoint,
                json=payload,
                headers=headers,
                timeout=WORKER_HTTP_TIMEOUT_SECONDS,
            )
            body = response.text[:300]
            if response.ok:
                parsed = {}
                with contextlib.suppress(Exception):
                    parsed = response.json()
                worker_id = parsed.get("worker_id") if isinstance(parsed, dict) else ""
                detail = f"task sent to {base_url}"
                if worker_id:
                    detail += f" | {worker_id}"
                    record_worker_queue_heartbeat(
                        {
                            "worker_id": worker_id,
                            "status": "http_accept",
                            "message": f"HTTP accepted task through {base_url}",
                        }
                    )
                record_worker_queue_transport("http_ok", detail)
                return {"url": base_url, "status_code": response.status_code, "body": body, "json": parsed}
            errors.append(f"{base_url}: {response.status_code} {body}")
        except Exception as e:
            errors.append(f"{base_url}: {str(e)[:180]}")
    detail = " | ".join(errors)[:500]
    record_worker_queue_transport("http_failed", detail)
    raise RuntimeError(f"Worker HTTP transport failed. {detail}")


async def send_worker_queue_payload(payload):
    """Send a worker payload through the most reliable configured transport."""
    payload_json = json.dumps(payload, ensure_ascii=True, sort_keys=True)
    command = f"/royells_queue@{WORKER_BOT_USERNAME}" if WORKER_BOT_USERNAME else "/royells_queue"
    errors = []

    if WORKER_HTTP_URLS:
        try:
            result = await send_worker_http_payload(payload)
            return "http", result
        except Exception as e:
            errors.append(f"http: {str(e)[:180]}")

    if WORKER_QUEUE_GROUP_ID:
        try:
            sent = await send_worker_queue_message(f"{command} {payload_json}")
            return "group", sent
        except Exception as e:
            errors.append(f"group: {str(e)[:180]}")

    raise RuntimeError(" | ".join(errors) or "No worker queue transport is configured.")


async def send_worker_queue_ping():
    payload = build_worker_queue_ping_payload()
    transport, result = await send_worker_queue_payload(payload)
    log_event(f"Worker queue ping sent through {transport}: {getattr(result, 'id', '') if transport == 'group' else result.get('status_code')}")


async def worker_queue_ping_loop():
    if QUEUE_WORKER_MODE or (not WORKER_QUEUE_GROUP_ID and not WORKER_HTTP_URLS):
        while True:
            await asyncio.sleep(3600)
    await asyncio.sleep(20)
    while True:
        try:
            await send_worker_queue_ping()
        except Exception as e:
            log_event(f"Worker queue ping failed: {str(e)[:160]}")
        await asyncio.sleep(max(120, WORKER_QUEUE_PING_SECONDS))


async def enqueue_worker_task(client, url, platform, requester_id, status_msg):
    payload = build_worker_queue_payload(url, platform, requester_id, status_msg)
    transport, sent = await send_worker_queue_payload(payload)
    if transport == "group":
        payload["queue_message_id"] = getattr(sent, "id", None)
    else:
        payload["queue_message_id"] = ""
    record_worker_queue_task(payload, status="sent")
    log_event(f"Worker queue task sent through {transport}: {payload['task_id']} | {platform} | user {requester_id}")
    return payload


async def queue_private_link(client, message, text, notice):
    clean_url = extract_first_url(text)
    if not clean_url:
        schedule_user_side_delete(message)
        return await telegram_gateway_await('client.send_message', lambda: client.send_message(message.chat.id, "No valid link found in the message."))
    platform = detect_link_platform(clean_url)
    if platform == "unsupported":
        schedule_user_side_delete(message)
        return await telegram_gateway_await('client.send_message', lambda: client.send_message(message.chat.id, "Unsupported link. Send a Telegram post/channel link."))
    offload = False
    queue_pos = link_process_queue.qsize() + 1
    queue_name = "local queue"
    status_msg = await telegram_gateway_await('client.send_message', lambda: client.send_message(
        message.chat.id,
        f"{notice}\nRoute: {queue_name}\nQueue position: {queue_pos}\nOriginal message auto-removes after 1 hour.",
        disable_web_page_preview=True,
    ))
    schedule_user_side_delete(message)
    if offload:
        try:
            await enqueue_worker_task(client, clean_url, platform, message.from_user.id, status_msg)
            await safe_edit(status_msg, f"{platform.title()} link sent to queue.")
            return status_msg
        except Exception as e:
            log_event(f"External queue failed, falling back to local processing: {e}")
            await safe_edit(status_msg, f"Queue failed. Using local queue.\nReason: {str(e)[:160]}")
    link_job = stamp_queue_job(
        {
            "job_id": stable_uid(
                "link",
                clean_url,
                int(getattr(message.from_user, "id", 0) or 0),
                int(getattr(status_msg, "id", 0) or 0),
            ),
            "url": clean_url,
            "platform": platform,
            "status_msg": status_msg,
            "status_chat_id": int(getattr(getattr(status_msg, "chat", None), "id", 0) or 0),
            "status_message_id": int(getattr(status_msg, "id", 0) or 0),
            "retries": 0,
            "requester_id": int(getattr(message.from_user, "id", 0) or 0),
        },
        "link",
    )
    await link_process_queue.put(link_job)
    return status_msg


TELEGRAM_LINK_RE = re.compile(
    r"(?:https?://)?(?:t\.me|telegram\.me|telegram\.dog)/(?:(?:s/[A-Za-z0-9_]{4,})|(?:c/\d+)|(?:[A-Za-z0-9_]{4,})|(?:\+[\w-]+)|(?:joinchat/[\w-]+))(?:/\d+)?",
    flags=re.I,
)


def normalize_telegram_link_for_report(url):
    text = str(url or "").strip().strip(".,;)]}>\"'")
    if not text:
        return ""
    if re.match(r"^(t\.me|telegram\.me|telegram\.dog)/", text, flags=re.I):
        text = "https://" + text
    if not re.search(r"https?://(?:t\.me|telegram\.me|telegram\.dog)/", text, flags=re.I):
        return ""
    return text.split("?", 1)[0].rstrip("/")


def extract_telegram_links_from_message(msg):
    links = []
    for text in [getattr(msg, "text", None), getattr(msg, "caption", None)]:
        if not text:
            continue
        links.extend(normalize_telegram_link_for_report(m.group(0)) for m in TELEGRAM_LINK_RE.finditer(str(text)))
    for entity in list(getattr(msg, "entities", None) or []) + list(getattr(msg, "caption_entities", None) or []):
        url = getattr(entity, "url", None)
        if url:
            links.append(normalize_telegram_link_for_report(url))
    reply_markup = getattr(msg, "reply_markup", None)
    for row in getattr(reply_markup, "inline_keyboard", None) or []:
        for button in row or []:
            url = getattr(button, "url", None)
            if url:
                links.append(normalize_telegram_link_for_report(url))
    clean = []
    seen = set()
    for link in links:
        if link and link not in seen:
            clean.append(link)
            seen.add(link)
    return clean


def mark_source_link_discovered(link, source_msg, origin):
    uid = stable_uid("src_link", normalize_telegram_link_for_report(link))
    with state_mutex:
        discovered = STATE["sync_source_manager"].setdefault("discovered_links", {})
        if uid in discovered:
            return False
        discovered[uid] = {
            "uid": uid,
            "link": link,
            "origin": origin,
            "source_chat_id": getattr(getattr(source_msg, "chat", None), "id", ""),
            "source_message_id": getattr(source_msg, "id", ""),
            "created_at": now_iso(),
        }
        if len(discovered) > 5000:
            ordered = sorted(discovered.values(), key=lambda item: item.get("created_at", ""))
            keep = {item["uid"] for item in ordered[-4000:] if item.get("uid")}
            STATE["sync_source_manager"]["discovered_links"] = {
                key: item for key, item in discovered.items() if key in keep
            }
        save_state("sync_source_manager")
    return True


def source_link_is_invite(clean_link):
    lowered = str(clean_link or "").lower()
    return "t.me/+" in lowered or "telegram.me/+" in lowered or "telegram.dog/+" in lowered or "/joinchat/" in lowered


def source_link_is_private_message_link(clean_link):
    return bool(re.search(r"(?:t\.me|telegram\.me|telegram\.dog)/c/\d+(?:/\d+)?", str(clean_link or ""), flags=re.I))


def source_link_status_template(valid="unknown", live="unknown", joinable="unknown", method="not checked", note=""):
    return {
        "valid": valid,
        "live": live,
        "joinable": joinable,
        "method": method,
        "note": str(note or "")[:180],
        "checked_at": format_display_datetime(seconds=True),
    }


def source_link_status_cache_key(clean_link, ref):
    return stable_uid("src_link_live", normalize_telegram_link_for_report(clean_link), str(ref or ""))


def get_cached_source_link_status(cache_key):
    item = source_link_check_cache.get(cache_key)
    if not item:
        return None
    if item.get("expires_at", 0) < time.time():
        source_link_check_cache.pop(cache_key, None)
        return None
    result = dict(item.get("result") or {})
    if result:
        result["method"] = f"{result.get('method', 'checked')} cached"
    return result or None


def remember_source_link_status(cache_key, result):
    source_link_check_cache[cache_key] = {
        "expires_at": time.time() + SOURCE_LINK_CHECK_CACHE_SECONDS,
        "result": dict(result or {}),
    }
    if len(source_link_check_cache) > 2000:
        now = time.time()
        expired = [key for key, item in source_link_check_cache.items() if item.get("expires_at", 0) < now]
        for key in expired[:1000]:
            source_link_check_cache.pop(key, None)
        if len(source_link_check_cache) > 2000:
            for key in list(source_link_check_cache.keys())[:500]:
                source_link_check_cache.pop(key, None)


async def source_link_probe_call(label, func, *args, timeout=25):
    await wait_for_telegram_client(label)
    async with telegram_api_semaphore:
        return await asyncio.wait_for(func(*args), timeout=max(5, timeout))


def source_link_status_from_chat(chat, clean_link, method, note=""):
    username = getattr(chat, "username", "") or ""
    if username:
        joinable = "yes"
        note = note or "public username resolved"
    elif source_link_is_private_message_link(clean_link):
        joinable = "accessible"
        note = note or "private /c link is accessible to this userbot"
    elif source_link_is_invite(clean_link):
        joinable = "yes" if "join probe" in method else "accessible"
        note = note or "invite link resolved for this userbot"
    else:
        joinable = "accessible"
        note = note or "chat resolved for this userbot"
    return source_link_status_template("yes", "yes", joinable, method, note)


def source_link_status_from_error(exc, method):
    text = f"{exc.__class__.__name__} {exc}".lower()
    already_joined = [
        "user_already_participant",
        "already a participant",
        "already participant",
    ]
    dead_or_invalid = [
        "invite_hash_expired",
        "invite hash expired",
        "invite_hash_invalid",
        "invite hash invalid",
        "username_not_occupied",
        "username not occupied",
        "peer_id_invalid",
        "peer id invalid",
        "channel_invalid",
        "chat_invalid",
        "not found",
        "no chat found",
    ]
    not_joinable = [
        "channel_private",
        "chat_admin_required",
        "user_banned_in_channel",
        "forbidden",
        "not enough rights",
        "invite request sent",
        "join request",
    ]
    temporary = [
        "flood_wait",
        "floodwait",
        "timed out",
        "timeout",
        "connection",
        "ssl",
        "transport",
    ]
    if any(marker in text for marker in already_joined):
        return source_link_status_template("yes", "yes", "yes", method, "userbot is already joined")
    if any(marker in text for marker in dead_or_invalid):
        return source_link_status_template("no", "no", "no", method, str(exc))
    if any(marker in text for marker in not_joinable):
        return source_link_status_template("unknown", "unknown", "no", method, str(exc))
    if any(marker in text for marker in temporary):
        return source_link_status_template("unknown", "unknown", "unknown", method, str(exc))
    return source_link_status_template("unknown", "unknown", "unknown", method, str(exc))


async def check_source_link_live_status(clean_link, ref, resolved_chat=None):
    if not SOURCE_LINK_LIVE_CHECK_ENABLED:
        return source_link_status_template(method="disabled", note="ROYELLS_SOURCE_LINK_LIVE_CHECK=0")
    cache_key = source_link_status_cache_key(clean_link, ref)
    cached = get_cached_source_link_status(cache_key)
    if cached:
        return cached
    async with source_link_check_semaphore:
        cached = get_cached_source_link_status(cache_key)
        if cached:
            return cached
        if resolved_chat is not None:
            result = source_link_status_from_chat(resolved_chat, clean_link, "existing resolve")
            remember_source_link_status(cache_key, result)
            return result
        if ref in (None, ""):
            result = source_link_status_template("no", "no", "no", "parse", "link reference could not be parsed")
            remember_source_link_status(cache_key, result)
            return result
        if source_link_is_invite(clean_link):
            if SOURCE_LINK_JOIN_PROBE_ENABLED:
                try:
                    chat = await source_link_probe_call("source link invite join probe", userbot.join_chat, clean_link, timeout=30)
                    result = source_link_status_from_chat(chat, clean_link, "invite join probe", "joined by probe")
                    if SOURCE_LINK_JOIN_PROBE_LEAVE_AFTER:
                        chat_id = getattr(chat, "id", None)
                        if chat_id:
                            with contextlib.suppress(Exception):
                                await source_link_probe_call("source link invite leave after probe", userbot.leave_chat, chat_id, timeout=15)
                                result["note"] = "joined successfully and left after probe"
                    remember_source_link_status(cache_key, result)
                    return result
                except Exception as e:
                    result = source_link_status_from_error(e, "invite join probe")
                    remember_source_link_status(cache_key, result)
                    return result
            try:
                chat = await source_link_probe_call("source link invite resolve", userbot.get_chat, clean_link, timeout=20)
                result = source_link_status_from_chat(chat, clean_link, "invite resolve", "invite accessible; join probe disabled")
            except Exception as e:
                result = source_link_status_from_error(e, "invite resolve")
                if result.get("valid") == "unknown" and result.get("joinable") == "unknown":
                    result = source_link_status_template(
                        "unknown",
                        "unknown",
                        "unknown",
                        "invite probe disabled",
                        "set ROYELLS_SOURCE_LINK_JOIN_PROBE=1 to test private invite joinability",
                    )
            remember_source_link_status(cache_key, result)
            return result
        try:
            lookup = normalize_channel_id(ref) if not (isinstance(ref, str) and ref.startswith("http")) else ref
            chat = await source_link_probe_call("source link public resolve", userbot.get_chat, lookup, timeout=25)
            result = source_link_status_from_chat(chat, clean_link, "public resolve")
        except Exception as e:
            result = source_link_status_from_error(e, "public resolve")
        remember_source_link_status(cache_key, result)
        return result


async def build_source_link_report(link, source_msg, origin):
    clean_link = normalize_telegram_link_for_report(link)
    ref, _ = extract_source_channel_reference(clean_link)
    resolved_chat = None
    title = "Unknown"
    username = ""
    channel_id = ""
    chat_type = "private/invite"
    members = ""
    description = ""
    if ref not in (None, ""):
        try:
            chat = await tg_call("source link report get_chat", userbot.get_chat, ref, retries=1)
            resolved_chat = chat
            title = getattr(chat, "title", "") or getattr(chat, "first_name", "") or title
            username = getattr(chat, "username", "") or ""
            channel_id = str(getattr(chat, "id", "") or "")
            chat_type = "public" if username else "private"
            description = (getattr(chat, "description", "") or "").strip()
            with contextlib.suppress(Exception):
                count = await tg_call("source link member count", userbot.get_chat_members_count, getattr(chat, "id", ref), retries=1)
                if count:
                    members = str(count)
        except Exception as e:
            channel_id = str(ref)
            description = f"Resolve note: {str(e)[:120]}"

    live_status = await check_source_link_live_status(clean_link, ref, resolved_chat=resolved_chat)
    source_chat = getattr(source_msg, "chat", None)
    source_title = getattr(source_chat, "title", "") or str(getattr(source_chat, "id", ""))
    source_link = source_message_link(source_msg)
    user_or_id = f"@{username}" if username else (channel_id or str(ref or "unknown"))
    lines = [
        "SOURCE LINK FOUND",
        "-----------------",
        f"Channel Name : {title[:80]}",
        f"Username/ID  : {user_or_id}",
        f"Type         : {chat_type}",
        f"Channel Link : {clean_link}",
        f"Valid/Live   : {live_status.get('valid', 'unknown')} / {live_status.get('live', 'unknown')}",
        f"Joinable     : {live_status.get('joinable', 'unknown')}",
        f"Check Method : {live_status.get('method', 'unknown')}",
        f"Found Time   : {format_display_datetime(seconds=True)}",
        f"Origin       : {origin}",
        f"Source       : {source_title}",
    ]
    if live_status.get("note"):
        lines.append(f"Check Note   : {live_status.get('note')}")
    if source_link:
        lines.append(f"Source Msg   : {source_link}")
    if members:
        lines.append(f"Members      : {members}")
    if description:
        lines.append("")
        lines.append(description[:500])
    return "\n".join(lines)[:3900]


async def send_source_link_report_task(link, source_msg, origin, already_marked=False):
    if not SOURCE_LINK_DISCOVERY_ENABLED or not SOURCE_LINK_REPORT_CHAT_ID:
        return False
    if not already_marked and not mark_source_link_discovered(link, source_msg, origin):
        return False
    report_text = await build_source_link_report(link, source_msg, origin)
    errors = []
    for label, client in (("userbot", userbot), ("bot", app)):
        try:
            await tg_call(
                f"source link report via {label}",
                client.send_message,
                SOURCE_LINK_REPORT_CHAT_ID,
                report_text,
                disable_web_page_preview=False,
                retries=2,
            )
            log_event(f"Source link report sent via {label}: {link}")
            return True
        except Exception as e:
            errors.append(f"{label}: {str(e)[:120]}")
            if label == "userbot" and should_reconnect_telegram_error(e):
                schedule_userbot_reconnect(f"source link report: {e}")
    log_event(f"Source link report failed for {link}: {' | '.join(errors)[:240]}")
    return False


def schedule_source_link_discovery(msg, origin):
    if not SOURCE_LINK_DISCOVERY_ENABLED or not SOURCE_LINK_REPORT_CHAT_ID:
        return
    links = extract_telegram_links_from_message(msg)
    for link in links:
        if mark_source_link_discovered(link, msg, f"{origin}:scheduled"):
            asyncio.create_task(send_source_link_report_task(link, msg, origin, already_marked=True))


def source_message_link(msg):
    if not msg or not getattr(msg, "chat", None):
        return ""
    username = getattr(msg.chat, "username", "") or ""
    if username:
        return f"https://t.me/{username}/{msg.id}"
    chat_id = str(getattr(msg.chat, "id", "") or "")
    if chat_id.startswith("-100") and chat_id[4:].isdigit():
        return f"https://t.me/c/{chat_id[4:]}/{msg.id}"
    return ""


