def record_sync_item(job, status, error=None):
    run_id = job.get("sync_run_id")
    if not run_id:
        return
    job_id = job["job_id"]
    with state_mutex:
        STATE["sync_source_manager"].setdefault("items", {})[job_id] = {
            "job_id": job_id,
            "run_id": run_id,
            "status": status,
            "ch_name": job.get("ch_name", ""),
            "type": job.get("type", ""),
            "message_count": len(job.get("messages", [])),
            "messages": (
                []
                if status in QUEUE_TERMINAL_STATUSES
                else [message_meta(m) for m in job.get("messages", [])]
            ),
            "last_error": str(error)[:500] if error else "",
            "updated_at": now_iso(),
        }
        run = STATE["sync_source_manager"].setdefault("runs", {}).setdefault(
            run_id,
            {"run_id": run_id, "started_at": now_iso(), "queued": 0, "uploaded": 0, "skipped": 0, "failed": 0},
        )
        if status == "queued":
            run["queued"] = run.get("queued", 0) + 1
        elif status == "uploaded":
            run["uploaded"] = run.get("uploaded", 0) + 1
        elif status == "skipped_duplicate":
            run["skipped"] = run.get("skipped", 0) + 1
        elif str(status).startswith("failed"):
            run["failed"] = run.get("failed", 0) + 1
        run["updated_at"] = now_iso()
        save_state("sync_source_manager")


def record_clean_duplicate(uid, source_msg, target_msg=None, post_uid=None, channel_name=""):
    if not uid:
        return
    target_id = getattr(target_msg, "id", None) if target_msg else None
    with state_mutex:
        duplicate_state = STATE.setdefault("clean_duplicate", default_state("clean_duplicate"))
        items = duplicate_state.setdefault("items", {})
        old = items.get(uid, {})
        target_ids = set(old.get("target_message_ids", []))
        if target_id:
            target_ids.add(target_id)
            STATE["clean_duplicate"].setdefault("target_messages", {})[str(target_id)] = uid
        items[uid] = {
            **old,
            "uid": uid,
            "post_uid": post_uid or old.get("post_uid", ""),
            "source_chat_id": getattr(source_msg.chat, "id", old.get("source_chat_id", "")),
            "source_message_id": getattr(source_msg, "id", old.get("source_message_id", "")),
            "source_channel": channel_name or old.get("source_channel", ""),
            "target_chat_id": TARGET_CHAT_ID,
            "target_message_ids": sorted(target_ids),
            "status": "active",
            "created_at": old.get("created_at", now_iso()),
            "updated_at": now_iso(),
        }
        STATE["clean_duplicate"].setdefault("events", []).append(
            {"time": now_iso(), "action": "add", "uid": uid, "target_message_id": target_id}
        )
        trim_events("clean_duplicate")
        save_state("clean_duplicate")


def remove_clean_duplicate_by_target_ids(message_ids):
    removed = []
    ids = {str(i) for i in message_ids}
    with state_mutex:
        target_messages = STATE["clean_duplicate"].setdefault("target_messages", {})
        items = STATE["clean_duplicate"].setdefault("items", {})
        for mid in ids:
            uid = target_messages.pop(mid, None)
            if not uid:
                continue
            item = items.get(uid)
            if not item:
                continue
            target_ids = [x for x in item.get("target_message_ids", []) if str(x) != mid]
            if target_ids:
                item["target_message_ids"] = target_ids
                item["updated_at"] = now_iso()
            else:
                items.pop(uid, None)
                remove_uid_from_target(uid)
                removed.append(uid)
        if removed:
            STATE["clean_duplicate"].setdefault("events", []).append(
                {"time": now_iso(), "action": "target_delete_detected", "removed": removed}
            )
            trim_events("clean_duplicate")
            save_state("clean_duplicate")
    return removed


def stamp_queue_job(job, queue_name):
    job["_queue_name"] = queue_name
    job["_queued_monotonic"] = time.monotonic()
    job["queued_at"] = now_iso()
    mark_runtime_checkpoint_dirty(f"{queue_name} queue stamped")
    return job


def observe_queue_wait(job, queue_name):
    queued_at = float((job or {}).get("_queued_monotonic") or time.monotonic())
    waited = max(0.0, time.monotonic() - queued_at)
    metric_set_peak("queue_wait_peak_seconds", queue_name, waited)
    threshold = float(os.getenv("ROYELLS_SLOW_QUEUE_WAIT_SECONDS", "5"))
    if waited >= threshold:
        log_event_rate_limited(
            f"slow_queue:{queue_name}",
            f"Slow {queue_name} queue wait: {waited:.2f}s "
            f"job={(job or {}).get('job_id', (job or {}).get('url', 'unknown'))}",
        )
    return waited


def source_message_key_from_meta(meta):
    if not isinstance(meta, dict):
        return ""
    chat_id = meta.get("chat_id")
    message_id = meta.get("message_id")
    if chat_id in (None, "") or message_id in (None, ""):
        return ""
    return f"{chat_id}:{message_id}"


def source_message_key(msg):
    chat = getattr(msg, "chat", None)
    chat_id = getattr(chat, "id", None)
    message_id = getattr(msg, "id", None)
    if chat_id in (None, "") or message_id in (None, ""):
        return ""
    return f"{chat_id}:{message_id}"


def partial_download_file_for_message(job, msg):
    metas = job.get("_partial_download_message_metas") or []
    files = job.get("_partial_download_files") or []
    wanted = source_message_key(msg)
    if not wanted:
        return ""
    for meta, path in zip(metas, files):
        if source_message_key_from_meta(meta) != wanted:
            continue
        if media_path_is_complete_enough(msg, path):
            return str(path)
    return ""


def remember_partial_download(job, msg, path):
    if not media_path_is_complete_enough(msg, path):
        return False
    key = source_message_key(msg)
    if not key:
        return False
    metas = job.setdefault("_partial_download_message_metas", [])
    files = job.setdefault("_partial_download_files", [])
    existing = {
        source_message_key_from_meta(meta)
        for meta in metas
        if isinstance(meta, dict)
    }
    if key not in existing:
        metas.append(message_meta(msg))
        files.append(str(path))
        mark_runtime_checkpoint_dirty("partial download remembered")
        return True
    return False


def retain_media_job_for_admission_backpressure(job, messages, ch_name, reason):
    """Persist an admitted source job before releasing an overloaded producer.

    A source cursor can advance after ``enqueue_media_job`` returns.  Returning
    ``False`` merely because the upload lane remained pressured for five minutes
    therefore used to make a valid source item depend on a future lookback scan.
    Store the descriptor as recoverable first, keep its processing reservation,
    and then request retry admission.  If the ephemeral retry scheduler is ever
    unavailable, queue healing/restart recovery can still fetch the persisted
    message metadata; no source item is silently discarded.
    """

    reason_text = str(reason or "media admission backpressure")[:300]
    record_download_job(job, "retry_later", reason_text, files=[])
    record_total_job(job, "retry_later", reason_text)
    record_sync_item(job, "retry_later", reason_text)
    scheduled = schedule_queue_retry(
        "download",
        job,
        MEDIA_ADMISSION_BACKPRESSURE_RETRY_SECONDS,
        reason_text,
    )
    source_brain_record_messages(
        messages,
        "queued",
        amount=len(messages or []),
        title=ch_name,
    )
    if scheduled:
        log_event_rate_limited(
            f"media_admission_backpressure_retained:{job.get('job_id', '')}",
            "Media admission backpressure retained a durable download job; "
            f"automatic retry in {MEDIA_ADMISSION_BACKPRESSURE_RETRY_SECONDS}s.",
            interval_seconds=30,
        )
    else:
        # ``retry_later`` is a recoverable persisted status.  Deliberately do
        # not remove processing keys or overwrite it with a terminal state.
        log_event(
            "Media admission retry scheduler unavailable; durable download "
            f"descriptor remains queued for recovery: {job.get('job_id', '')}."
        )
    return True


async def enqueue_media_job(
    job_type,
    messages,
    ch_name,
    attempt=1,
    is_fallback=False,
    source="auto",
    sync_run_id=None,
    status_msg=None,
    force_upload=False,
    manual_link_url="",
    status_chat_id=0,
    status_message_id=0,
    reservation_owner=None,
    recovery_job_id=None,
    partial_download_files=None,
    partial_download_message_metas=None,
    permanent_retry_count=0,
    fresh_download_recovery_count=0,
    source_fresh_download_deferred_count=0,
    source_fresh_download_deferred_due_at=0,
    source_fresh_download_deferred_reason="",
    source_item_unavailable_retries=None,
    manual_fresh_download_deferred_count=0,
    manual_fresh_download_deferred_due_at=0,
    manual_fresh_download_deferred_reason="",
):
    global last_successful_queue_time
    valid = [m for m in messages if is_valid_media(m)]
    if not valid:
        return False

    force_upload = bool(force_upload)
    new_messages = (
        valid
        if force_upload
        else await filter_new_messages_async(valid, reservation_owner=reservation_owner)
    )
    if not new_messages:
        dummy = {"job_id": make_job_id(valid, job_type), "messages": valid, "type": job_type, "ch_name": ch_name, "source": source}
        record_total_job(dummy, "skipped_duplicate")
        record_sync_item(dummy, "skipped_duplicate")
        source_brain_record_messages(valid, "duplicate", amount=len(valid), title=ch_name)
        for m in valid:
            remove_processing_keys(m.chat.id, m)
        return False

    if job_type == "album" and len(new_messages) < 2:
        job_type = "single"
        log_event(
            f"Partial album from {ch_name}: Telegram album is impossible with one remaining "
            "non-duplicate item; using terminal single-item fallback."
        )

    job_id = str(recovery_job_id or make_job_id(new_messages, job_type))
    v21_context = None
    if V21_ENGINE is not None:
        v21_context, admitted_messages, rejected_messages = V21_ENGINE.admit_legacy_job(
            job_id=job_id,
            job_type=job_type,
            messages=new_messages,
            channel_name=ch_name,
            source=source,
            attempt=attempt,
            force_upload=force_upload,
            metadata={
                "sync_run_id": sync_run_id or "",
                "manual_link_url": manual_link_url or "",
                "recovery": bool(recovery_job_id),
            },
        )
        if rejected_messages:
            log_event_rate_limited(
                f"v21_admission_rejected:{ch_name}",
                f"v21 admission discarded {len(rejected_messages)} unsupported item(s) from {ch_name}.",
                interval_seconds=120,
            )
        new_messages = admitted_messages
        if not new_messages:
            return False
    job = {
        "job_id": job_id,
        "post_uid": job_id,
        "type": job_type,
        "messages": new_messages,
        "ch_name": ch_name,
        "attempt": attempt,
        "is_fallback": is_fallback,
        "source": source,
        "sync_run_id": sync_run_id,
        "force_upload": force_upload,
        "manual_link_url": manual_link_url,
        "_permanent_retry_count": max(0, int(permanent_retry_count or 0)),
        "_fresh_download_recovery_count": max(
            0, int(fresh_download_recovery_count or 0)
        ),
        "_source_fresh_download_deferred_count": max(
            0,
            min(
                len(SOURCE_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS),
                int(source_fresh_download_deferred_count or 0),
            ),
        ),
        "_source_fresh_download_deferred_due_at": float(
            source_fresh_download_deferred_due_at or 0
        ),
        "_source_fresh_download_deferred_reason": str(
            source_fresh_download_deferred_reason or ""
        )[:120],
        "_source_item_unavailable_retries": {
            str(key)[:320]: dict(entry)
            for key, entry in (source_item_unavailable_retries or {}).items()
            if key and isinstance(entry, dict)
        }
        if isinstance(source_item_unavailable_retries, dict)
        else {},
        "_manual_fresh_download_deferred_count": max(
            0,
            min(
                len(MANUAL_FRESH_DOWNLOAD_DEFERRED_RETRY_DELAYS_SECONDS),
                int(manual_fresh_download_deferred_count or 0),
            ),
        ),
        "_manual_fresh_download_deferred_due_at": float(
            manual_fresh_download_deferred_due_at or 0
        ),
        "_manual_fresh_download_deferred_reason": str(
            manual_fresh_download_deferred_reason or ""
        )[:120],
    }
    if v21_context is not None:
        V21_ENGINE.annotate_job(job, v21_context, "download")
    if partial_download_files:
        job["_partial_download_files"] = [
            str(path)
            for path in partial_download_files
            if path and os.path.exists(path) and os.path.getsize(path) > 0
        ]
    if partial_download_message_metas:
        job["_partial_download_message_metas"] = [
            dict(item)
            for item in partial_download_message_metas
            if isinstance(item, dict)
        ]
    if status_msg:
        job["status_msg"] = status_msg
        job["status_chat_id"] = int(status_msg.chat.id)
        job["status_message_id"] = int(status_msg.id)
    elif status_chat_id and status_message_id:
        job["status_chat_id"] = int(status_chat_id)
        job["status_message_id"] = int(status_message_id)
    manual_deferred_seconds = manual_fresh_download_deferred_remaining_seconds(job)
    source_deferred_seconds = source_fresh_download_deferred_remaining_seconds(job)
    unavailable_item_deferred_seconds = source_item_unavailable_next_remaining_seconds(job)
    deferred_seconds = max(
        manual_deferred_seconds,
        source_deferred_seconds,
        unavailable_item_deferred_seconds,
    )
    if deferred_seconds > 0:
        reason = (
            "manual Telegram link fresh-download recovery remains scheduled "
            f"for {deferred_seconds}s"
            if manual_deferred_seconds > 0
            else "source media fresh-download recovery remains scheduled "
            f"for {deferred_seconds}s"
            if source_deferred_seconds > 0
            else "source item unavailable recovery remains scheduled "
            f"for {deferred_seconds}s"
        )
        record_download_job(job, "retry_later", reason, files=[])
        record_total_job(job, "retry_later", reason)
        record_sync_item(job, "retry_later", reason)
        scheduled = schedule_queue_retry("download", job, deferred_seconds, reason)
        if not scheduled:
            # The JSON descriptor is authoritative.  Keep both it and the
            # existing processing reservation for queue healing/restart rather
            # than making an already-seen source post depend on a future scan.
            log_event(
                "Fresh-download retry scheduler unavailable; durable source "
                f"descriptor remains queued for recovery: {job.get('job_id', '')}."
            )
        return True
    if should_pressure_offload_source_job(source, is_fallback=is_fallback):
        offloaded = await offload_source_media_job_to_worker(
            job,
            f"main local queue pressure D{channel_download_queue.qsize()} U{upload_queue.qsize()}",
        )
        if offloaded:
            record_download_job(job, "worker_pressure_offload")
            record_total_job(job, "worker_pressure_offload")
            record_sync_item(job, "queued")
            source_brain_record_messages(new_messages, "queued", amount=len(new_messages), title=ch_name)
            for m in new_messages:
                remove_processing_keys(m.chat.id, m)
            last_successful_queue_time = time.time()
            return True

    async with media_admission_lock:
        capacity_ready = await wait_for_local_media_capacity(source)
        if not capacity_ready:
            retained = retain_media_job_for_admission_backpressure(
                job,
                new_messages,
                ch_name,
                "media admission timed out under local backpressure",
            )
            if retained:
                last_successful_queue_time = time.time()
                return True
            # Kept as a defensive unreachable fallback: the helper only returns
            # after persisting a recoverable descriptor, but never remove keys
            # until that invariant has held.
            return False
        job["_admission_reserved"] = True

    allow_fast_copy = SOURCE_FAST_COPY_ENABLED and not CONTENT_FILTER_ENABLED
    if (
        TRY_COPY_MESSAGE
        and allow_fast_copy
        and job_type == "single"
        and len(new_messages) == 1
        and not is_fallback
        and not reservation_owner
    ):
        if await try_copy_message_fast_path(job, new_messages[0], ch_name):
            last_successful_queue_time = time.time()
            return True
    if (
        TRY_COPY_MEDIA_GROUP
        and allow_fast_copy
        and job_type == "album"
        and len(new_messages) > 1
        and not is_fallback
        and not reservation_owner
    ):
        if await try_copy_media_group_fast_path(job, new_messages, ch_name):
            last_successful_queue_time = time.time()
            return True
    if (
        TRY_COPY_ALBUM_ITEMS
        and not PRESERVE_ALBUMS
        and allow_fast_copy
        and job_type == "album"
        and len(new_messages) > 1
        and not is_fallback
        and not reservation_owner
    ):
        if await try_copy_album_items_fast_path(job, new_messages, ch_name):
            last_successful_queue_time = time.time()
            return True

    record_download_job(job, "queued")
    record_total_job(job, "queued_download")
    record_sync_item(job, "queued")
    stamp_queue_job(job, "download")
    try:
        channel_download_queue.put_nowait(job)
    except asyncio.QueueFull:
        scheduled = schedule_queue_retry(
            "download",
            job,
            2,
            "active download window full",
        )
        if not scheduled:
            # Do not release an admitted source post if the ephemeral retry
            # scheduler is unavailable.  ``retry_later`` is checkpointed with
            # its message descriptors and queue healing will re-admit it.
            record_download_job(job, "retry_later", "active download window full")
            record_total_job(job, "retry_later", "active download window full")
            record_sync_item(job, "retry_later", "active download window full")
            log_event(
                "Download retry scheduler unavailable; durable source descriptor "
                f"remains queued for recovery: {job.get('job_id', '')}."
            )
            source_brain_record_messages(
                new_messages,
                "queued",
                amount=len(new_messages),
                title=ch_name,
            )
            last_successful_queue_time = time.time()
            return True
        log_event_rate_limited(
            "download_active_window_full",
            "Download active window is full; job retained for automatic refill.",
            interval_seconds=60,
        )
    source_brain_record_messages(new_messages, "queued", amount=len(new_messages), title=ch_name)
    last_successful_queue_time = time.time()
    return True


async def try_copy_message_fast_path(job, msg, ch_name):
    global auto_count
    if copy_restricted_cached(msg.chat.id):
        log_copy_restricted_download_fallback(msg.chat.id, ch_name, "single-media")
        return False

    async def finalize_copy(sent, label, intent_id=None):
        global auto_count
        if getattr(sent, "caption", None):
            await delete_target_messages(sent.id)
            if intent_id:
                await update_delivery_intent(
                    intent_id,
                    status="failed",
                    error="copyMessage preserved caption; using captionless upload fallback",
                )
            log_event_rate_limited(
                f"copy_message_caption_fallback:{msg.chat.id}:{msg.id}",
                f"copyMessage preserved a caption for {ch_name}; using captionless upload fallback.",
                interval_seconds=300,
            )
            return False
        await mark_posted_queued(msg.chat.id, msg, ch_name, sent, job["job_id"])
        await complete_delivery_intents_for_job(job["job_id"])
        record_total_job(job, "uploaded")
        record_sync_item(job, "uploaded")
        source_brain_record_messages([msg], "copy_uploaded", amount=1, title=ch_name)
        auto_count += 1
        diagnostic_stats["uploads"] = int(diagnostic_stats.get("uploads") or 0) + 1
        with state_mutex:
            STATE["total_auto_upload"]["total_uploaded"] = STATE["total_auto_upload"].get("total_uploaded", 0) + 1
            save_state("total_auto_upload")
        log_event(f"copyMessage uploaded 1 media from {ch_name} via {label}.")
        return True

    last_error = None
    for label, client in copy_message_clients():
        for protect_content in (True, False):
            intent_id = await begin_delivery_intent(
                job,
                [msg],
                f"copy_message_{label}_{'protected' if protect_content else 'plain'}",
            )
            try:
                sent = await tg_call(
                    f"copyMessage {label}",
                    client.copy_message,
                    chat_id=TARGET_CHAT_ID,
                    from_chat_id=msg.chat.id,
                    message_id=msg.id,
                    caption="",
                    protect_content=protect_content,
                    _client_role=label,
                )
                await update_delivery_intent(intent_id, status="accepted", target_messages=[sent])
                return await finalize_copy(sent, label, intent_id)
            except Exception as e:
                last_error = e
                ambiguous = isinstance(e, TimeoutError) or is_temporary_network_error(e)
                await update_delivery_intent(
                    intent_id,
                    status="ambiguous" if ambiguous else "failed",
                    error=e,
                )
                if ambiguous:
                    confirmed = await confirm_recent_target_media_item(msg)
                    if confirmed:
                        return await finalize_copy(confirmed, f"{label} confirmed", intent_id)
                    record_download_job(job, "retry", e)
                    record_total_job(job, "queued_download", e)
                    stamp_queue_job(job, "download")
                    scheduled = schedule_queue_retry(
                        "download",
                        job,
                        DELIVERY_AMBIGUITY_GRACE_SECONDS,
                        "ambiguous copyMessage delivery",
                    )
                    if scheduled:
                        log_event(
                            f"copyMessage delivery ambiguous for {ch_name}; "
                            "durable delayed confirmation/retry scheduled."
                        )
                    else:
                        log_event(
                            f"copyMessage retry queue was full for {ch_name}; "
                            "durable download queue state retained for queue-healer recovery."
                        )
                    return True
                if remember_copy_restricted(msg.chat.id, e):
                    log_copy_restricted_download_fallback(
                        msg.chat.id,
                        ch_name,
                        "single-media",
                        confirmed=True,
                    )
                    return False
                if should_reconnect_telegram_error(e):
                    schedule_userbot_reconnect(f"copyMessage {label}: {e}")
    if last_error:
        log_event(f"copyMessage fallback to download for {ch_name}: {str(last_error)[:140]}")
    return False


async def try_copy_media_group_fast_path(job, messages, ch_name):
    """Preserve unrestricted albums without local download/re-upload."""
    global auto_count
    if not messages or copy_restricted_cached(messages[0].chat.id):
        if messages:
            log_copy_restricted_download_fallback(
                messages[0].chat.id,
                ch_name,
                "album",
            )
        return False
    source_chat_id = messages[0].chat.id
    source_message_id = messages[0].id
    intent_id = await begin_delivery_intent(
        job,
        messages,
        "copy_media_group_userbot",
    )

    async def finalize_copy(sent_messages, label):
        global auto_count
        sent_messages = list(sent_messages or [])
        if len(sent_messages) < len(messages):
            raise RuntimeError(
                f"copy_media_group returned {len(sent_messages)}/{len(messages)} items"
            )
        if len(sent_messages) > len(messages):
            extra_messages = sent_messages[len(messages):]
            await delete_target_messages(
                [sent.id for sent in extra_messages if getattr(sent, "id", None)]
            )
            log_event_rate_limited(
                f"copy_media_group_extra:{source_chat_id}:{source_message_id}",
                f"copy_media_group returned {len(sent_messages)}/{len(messages)} "
                "items; extra target messages were removed and requested album was accepted.",
                interval_seconds=300,
            )
            sent_messages = sent_messages[: len(messages)]
        if any(getattr(sent, "caption", None) for sent in sent_messages):
            await delete_target_messages(
                [sent.id for sent in sent_messages if getattr(sent, "id", None)]
            )
            await update_delivery_intent(
                intent_id,
                status="failed",
                error="copy_media_group preserved a caption; using captionless upload fallback",
            )
            log_event_rate_limited(
                f"copy_media_group_caption_fallback:{source_chat_id}:{source_message_id}",
                f"copy_media_group preserved a caption for {ch_name}; using captionless upload fallback.",
                interval_seconds=300,
            )
            return False
        await update_delivery_intent(
            intent_id,
            status="accepted",
            target_messages=sent_messages,
        )
        await mark_posted_many_queued(
            [
                (message.chat.id, message, ch_name, sent_messages[index], job["job_id"])
                for index, message in enumerate(messages)
            ]
        )
        await complete_delivery_intent(intent_id)
        record_total_job(job, "uploaded")
        record_sync_item(job, "uploaded")
        source_brain_record_messages(
            messages,
            "copy_uploaded",
            amount=len(messages),
            title=ch_name,
        )
        auto_count += len(messages)
        diagnostic_stats["uploads"] = (
            int(diagnostic_stats.get("uploads") or 0) + len(messages)
        )
        with state_mutex:
            STATE["total_auto_upload"]["total_uploaded"] = (
                STATE["total_auto_upload"].get("total_uploaded", 0) + len(messages)
            )
            save_state("total_auto_upload")
        log_event(
            f"copy_media_group uploaded album ({len(messages)}) from "
            f"{ch_name} via {label}."
        )
        return True

    try:
        sent = await telegram_media_call(
            "copy_media_group via userbot",
            lambda: userbot.copy_media_group(
                TARGET_CHAT_ID,
                source_chat_id,
                source_message_id,
                captions=[""] * len(messages),
            ),
            UPLOAD_SEND_TIMEOUT_SECONDS,
            client_role="userbot",
        )
    except Exception as exc:
        ambiguous = isinstance(exc, TimeoutError) or is_temporary_network_error(exc)
        await update_delivery_intent(
            intent_id,
            status="ambiguous" if ambiguous else "failed",
            error=exc,
        )
        if ambiguous:
            confirmed = await confirm_recent_target_album(
                [(message, "") for message in messages]
            )
            if confirmed:
                ordered = [target for _source, target in confirmed]
                return await finalize_copy(ordered, "userbot confirmed")
            scheduled = schedule_queue_retry(
                "download",
                job,
                DELIVERY_AMBIGUITY_GRACE_SECONDS,
                "ambiguous copy_media_group delivery",
            )
            if scheduled:
                record_download_job(job, "retry", exc)
                record_total_job(job, "queued_download", exc)
                return True
        if remember_copy_restricted(source_chat_id, exc):
            log_copy_restricted_download_fallback(
                source_chat_id,
                ch_name,
                "album",
                confirmed=True,
            )
        else:
            log_event_rate_limited(
                f"copy_media_group_fallback:{source_chat_id}",
                f"copy_media_group fallback to grouped download for {ch_name}: "
                f"{str(exc)[:160]}",
                interval_seconds=300,
            )
        return False
    return await finalize_copy(sent, "userbot")


async def try_copy_album_items_fast_path(job, messages, ch_name):
    global auto_count
    if not messages:
        return False
    if copy_restricted_cached(messages[0].chat.id):
        log_copy_restricted_download_fallback(messages[0].chat.id, ch_name, "album")
        return False

    last_error = None
    for label, client in copy_message_clients():
        for protect_content in (True, False):
            copied = []
            try:
                for msg in messages:
                    sent = await tg_call(
                        f"copy album {label}",
                        client.copy_message,
                        chat_id=TARGET_CHAT_ID,
                        from_chat_id=msg.chat.id,
                        message_id=msg.id,
                        caption="",
                        protect_content=protect_content,
                        _client_role=label,
                    )
                    if getattr(sent, "caption", None):
                        await delete_target_messages(sent.id)
                        if copied:
                            with contextlib.suppress(Exception):
                                await delete_target_messages([copied_sent.id for _, copied_sent in copied if copied_sent])
                        log_event_rate_limited(
                            f"copy_album_items_caption_fallback:{msg.chat.id}:{msg.id}",
                            f"copyMessage preserved an album item caption for {ch_name}; using grouped upload fallback.",
                            interval_seconds=300,
                        )
                        return False
                    copied.append((msg, sent))
                    await asyncio.sleep(max(0.05, COPY_MESSAGE_ITEM_DELAY))

                await mark_posted_many_queued([
                    (msg.chat.id, msg, ch_name, sent, job["job_id"])
                    for msg, sent in copied
                ])
                record_total_job(job, "uploaded")
                record_sync_item(job, "uploaded")
                source_brain_record_messages([msg for msg, _sent in copied], "copy_uploaded", amount=len(copied), title=ch_name)
                auto_count += len(copied)
                with state_mutex:
                    STATE["total_auto_upload"]["total_uploaded"] = STATE["total_auto_upload"].get("total_uploaded", 0) + len(copied)
                    save_state("total_auto_upload")
                log_event(f"copyMessage uploaded album items ({len(copied)}) from {ch_name} via {label}.")
                return True
            except Exception as e:
                last_error = e
                restricted = remember_copy_restricted(messages[0].chat.id, e)
                if copied:
                    with contextlib.suppress(Exception):
                        await delete_target_messages([sent.id for _, sent in copied if sent])
                if restricted:
                    log_copy_restricted_download_fallback(
                        messages[0].chat.id,
                        ch_name,
                        "album",
                        confirmed=True,
                    )
                    return False
                if should_reconnect_telegram_error(e):
                    schedule_userbot_reconnect(f"copy album {label}: {e}")

    if last_error:
        log_event(f"copyMessage album fallback to grouped upload for {ch_name}: {str(last_error)[:140]}")
    return False


def copy_message_clients():
    clients = []
    if COPY_MESSAGE_WITH_USERBOT:
        clients.append(("userbot", userbot))
    if COPY_MESSAGE_WITH_BOT:
        clients.append(("bot", app))
    return clients


def fix_video_ext(path):
    if not path:
        return path
    base, ext = os.path.splitext(path)
    if ext.lower() in [".m4v", ".mkv", ".mov", ".3gp", ".avi", ".webm"]:
        new = base + ".mp4"
        try:
            os.rename(path, new)
            return new
        except Exception:
            pass
    return path


def get_video_meta(path):
    """Return optional local probe hints for the dependency-free production image.

    The Docker image intentionally has no FFmpeg/ffprobe. Validator v2 therefore treats
    these zero values as unavailable hints and uses Telegram source metadata plus byte
    integrity/container checks; zero dimensions are never a corruption verdict.
    """

    return {"width": 0, "height": 0, "duration": 0, "codec": "", "pix_fmt": "", "audio_codec": ""}


def video_is_telegram_friendly(path):
    meta = get_video_meta(path)
    ext_ok = Path(path).suffix.lower() == ".mp4"
    video_ok = meta["codec"] in ("h264", "avc1") and meta["pix_fmt"] in ("yuv420p", "yuvj420p", "")
    audio_ok = meta["audio_codec"] in ("aac", "mp4a", "")
    dims_ok = (meta["width"] % 2 == 0 if meta["width"] else True) and (meta["height"] % 2 == 0 if meta["height"] else True)
    return ext_ok and video_ok and audio_ok and dims_ok


async def async_get_video_meta(path):
    try:
        return await asyncio.wait_for(
            run_blocking("media", get_video_meta, path),
            timeout=max(5, VIDEO_META_PROBE_TIMEOUT_SECONDS * 3),
        )
    except Exception as e:
        log_event(f"Video metadata probe skipped for {Path(path).name}: {str(e)[:120]}")
        return {"width": 0, "height": 0, "duration": 0, "codec": "", "pix_fmt": "", "audio_codec": ""}


async def async_video_is_telegram_friendly(path):
    meta = await async_get_video_meta(path)
    ext_ok = Path(path).suffix.lower() == ".mp4"
    video_ok = meta["codec"] in ("h264", "avc1") and meta["pix_fmt"] in ("yuv420p", "yuvj420p", "")
    audio_ok = meta["audio_codec"] in ("aac", "mp4a", "")
    dims_ok = (meta["width"] % 2 == 0 if meta["width"] else True) and (meta["height"] % 2 == 0 if meta["height"] else True)
    return ext_ok and video_ok and audio_ok and dims_ok


async def run_subprocess_safely(cmd, timeout_seconds, label):
    process = None
    try:
        process = await asyncio.wait_for(
            asyncio.create_subprocess_exec(
                *cmd,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                start_new_session=True,
            ),
            timeout=min(30, max(5, timeout_seconds)),
        )
        stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=max(5, timeout_seconds))
        return process.returncode, stdout, stderr
    except asyncio.CancelledError:
        if process and process.returncode is None:
            process.terminate()
            with contextlib.suppress(Exception):
                await asyncio.wait_for(process.wait(), timeout=5)
            if process.returncode is None:
                process.kill()
                with contextlib.suppress(Exception):
                    await process.wait()
        raise
    except asyncio.TimeoutError as exc:
        if process and process.returncode is None:
            process.terminate()
            with contextlib.suppress(Exception):
                await asyncio.wait_for(process.wait(), timeout=5)
            if process.returncode is None:
                process.kill()
                with contextlib.suppress(Exception):
                    await process.wait()
        raise TimeoutError(f"{label} timed out after {timeout_seconds}s") from exc
    except Exception:
        if process and process.returncode is None:
            process.kill()
            with contextlib.suppress(Exception):
                await process.wait()
        raise


async def fix_video_for_telegram(input_path, force=False):
    log_event_rate_limited(
        "source_video_conversion_disabled",
        "Source video conversion is disabled; uploading original Telegram media file.",
        interval_seconds=3600,
    )
    return input_path


async def prepare_source_upload_items(messages, files, worker_id, ch_name):
    prepared = []
    generated_files = set()
    for idx, (m, fp) in enumerate(zip(messages, files), 1):
        await asyncio.sleep(0)
        if not media_path_is_complete_enough(m, fp):
            raise RuntimeError(
                f"source media preparation requires fresh download: item={idx} "
                f"kind={get_media_kind(m)}"
            )

        try:
            if m.video:
                prepared.append((m, fp))
            elif m.photo:
                send_fp = await ensure_photo_for_telegram(fp)
                if send_fp != fp:
                    generated_files.add(send_fp)
                if (
                    not os.path.exists(send_fp)
                    or os.path.getsize(send_fp) <= 512
                    or not await run_blocking("media", validate_photo_file_sync, send_fp)
                ):
                    raise Exception("photo is not readable after Telegram preparation")
                prepared.append((m, send_fp))
            else:
                raise Exception("unsupported source media type")
        except Exception as e:
            # Never partially publish an album or permanently blacklist a source item
            # because local preparation failed. The upload worker retains the whole job
            # for a fresh-download retry.
            raise RuntimeError(
                f"source media preparation failed for item {idx} ({get_media_kind(m)}): "
                f"{str(e)[:180]}"
            ) from e
    return prepared, generated_files


async def build_source_media_group(prepared_items):
    media_group = []
    for m, fp in prepared_items:
        if m.photo:
            media_group.append(InputMediaPhoto(media=fp))
        elif m.video:
            media_group.append(
                InputMediaVideo(
                    media=fp,
                    supports_streaming=True,
                )
            )
    return media_group


def upload_timeout_for_files(files):
    total_size = 0
    for raw_path in files or []:
        with contextlib.suppress(OSError, TypeError, ValueError):
            total_size += os.path.getsize(str(raw_path))
    size_mb = total_size / (1024 * 1024)
    estimated = UPLOAD_TIMEOUT_BASE_SECONDS + int(size_mb * UPLOAD_TIMEOUT_SECONDS_PER_MB)
    hard_cap = max(30, int(TELEGRAM_MEDIA_CALL_HARD_TIMEOUT_SECONDS))
    configured_floor = max(30, min(int(UPLOAD_SEND_TIMEOUT_SECONDS), hard_cap))
    return max(configured_floor, min(hard_cap, estimated))


async def telegram_media_call(label, awaitable_or_factory, timeout_seconds, client_role=None):
    client_role = telegram_client_role(label, client_role)
    inflight_token = begin_telegram_inflight(label, "media")
    try:
        effective_timeout = max(30, min(int(timeout_seconds), TELEGRAM_MEDIA_CALL_HARD_TIMEOUT_SECONDS))
        await wait_global_flood_gate(label, client_role)
        async with telegram_media_semaphore:
            global EVENT_LOOP_HEARTBEAT_TS
            EVENT_LOOP_HEARTBEAT_TS = time.time()
            started = time.monotonic()
            awaitable = awaitable_or_factory() if callable(awaitable_or_factory) else awaitable_or_factory
            result = await asyncio.wait_for(awaitable, timeout=effective_timeout)
            duration = time.monotonic() - started
            metric_observe_latency("upload", duration)
            if duration >= float(os.getenv("ROYELLS_SLOW_MEDIA_SECONDS", "15")):
                metric_increment("slow_media_operations")
                log_event_rate_limited(
                    f"slow_media:{label}",
                    f"Slow Telegram media call: {label} duration={duration:.2f}s",
                )
            EVENT_LOOP_HEARTBEAT_TS = time.time()
            await asyncio.sleep(0)
            return result
    except asyncio.TimeoutError:
        raise TimeoutError(f"{label} timed out after {min(int(timeout_seconds), TELEGRAM_MEDIA_CALL_HARD_TIMEOUT_SECONDS)}s")
    except FloodWait as exc:
        with contextlib.suppress(Exception):
            setattr(exc, "_royells_client_role", client_role)
        note_global_flood_wait(exc, client_role)
        raise
    except Exception as exc:
        if is_session_auth_error(exc):
            mark_session_auth_invalid(exc)
        elif should_reconnect_telegram_error(exc):
            schedule_userbot_reconnect(f"media {label}: {exc}")
        raise
    finally:
        end_telegram_inflight(inflight_token)


def target_media_clients():
    clients = []
    if TARGET_MEDIA_WITH_USERBOT:
        clients.append(("userbot", userbot))
    if TARGET_MEDIA_WITH_BOT:
        clients.append(("bot", app))
    return clients or [("userbot", userbot)]


async def target_send_photo(label, photo, protect_content=True, job=None, messages=None, operation=None):
    last_error = None
    intent_id = ""
    if job is not None:
        intent_id = await begin_delivery_intent(
            job,
            messages or [],
            operation or label,
            files=[photo],
        )
    for client_label, client in target_media_clients():
        try:
            sent = await telegram_media_call(
                f"{label} via {client_label}",
                lambda: client.send_photo(TARGET_CHAT_ID, photo=photo, protect_content=protect_content),
                upload_timeout_for_files([photo]),
                client_role=client_label,
            )
            await update_delivery_intent(intent_id, status="accepted", target_messages=[sent])
            return sent
        except Exception as e:
            last_error = e
            await update_delivery_intent(
                intent_id,
                status="ambiguous" if isinstance(e, TimeoutError) or is_temporary_network_error(e) else "failed",
                error=e,
            )
            if isinstance(e, TimeoutError) or is_temporary_network_error(e):
                raise
            if not (is_peer_id_error(e) or is_temporary_network_error(e) or "forbidden" in str(e).lower()):
                raise
            log_event(f"{label} via {client_label} failed, trying next target sender: {str(e)[:140]}")
    raise last_error


