def get_build_info_text():
    manifest = dict(BUILD_MANIFEST or {})
    validation = dict(BUILD_MANIFEST_VALIDATION or {"status": "not_validated"})
    if not manifest:
        try:
            manifest_path = Path(__file__).resolve().parent / MANIFEST_FILENAME
            manifest, validation_result = validate_or_raise(
                root=Path(__file__).resolve().parent,
                manifest_path=manifest_path,
                context=build_manifest_context(),
                repair_missing=False,
            )
            validation = validation_result.to_dict()
        except Exception as exc:
            lines = [
                "BUILD INFO",
                "==========",
                "Manifest : failed",
                f"Reason   : {format_exception_for_log(exc)[:260]}",
            ]
            return format_dashboard_pre(lines, footer="")
    lines = build_info_lines(manifest, validation)
    warnings = validation.get("warnings") or []
    fatal = validation.get("fatal") or []
    if fatal:
        lines.append("")
        lines.extend(f"FATAL   : {str(item)[:72]}" for item in fatal[:4])
    if warnings:
        lines.append("")
        lines.extend(f"WARN    : {str(item)[:72]}" for item in warnings[:4])
    return format_dashboard_pre(lines, footer="")


