def runtime_worker_limits():
    return {"download": 1, "upload": 1, "link": 1, "button": 2}


def runtime_queue_limits():
    return {"soft": MAIN_LOCAL_QUEUE_SOFT_LIMIT, "hard": MAIN_LOCAL_QUEUE_HARD_LIMIT}


def clamp_runtime_worker_value(name, value):
    limits = runtime_worker_limits()
    return max(1, min(int(limits.get(name, 1)), int(value)))


def clamp_runtime_queue_value(name, value):
    limit = runtime_queue_limits().get(str(name), MAIN_LOCAL_QUEUE_HARD_LIMIT)
    try:
        requested = int(value)
    except (TypeError, ValueError):
        requested = int(limit)
    return max(1, min(int(limit), requested))


def runtime_worker_snapshot():
    workers = STATE.get("runtime_config", {}).get("workers", {}) if STATE else {}
    return {
        "download": int(workers.get("download", DOWNLOAD_WORKERS)),
        "upload": int(workers.get("upload", UPLOAD_WORKERS)),
        "link": int(workers.get("link", LINK_WORKERS)),
        "button": int(workers.get("button", BUTTON_WORKERS)),
    }


def runtime_queue_snapshot():
    queue_cfg = STATE.get("runtime_config", {}).get("queue", {}) if STATE else {}
    return {
        "soft": clamp_runtime_queue_value("soft", queue_cfg.get("soft", MAIN_LOCAL_QUEUE_SOFT_LIMIT)),
        "hard": clamp_runtime_queue_value("hard", queue_cfg.get("hard", MAIN_LOCAL_QUEUE_HARD_LIMIT)),
    }


def save_runtime_worker_setting(name, value):
    value = clamp_runtime_worker_value(name, value)
    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        workers = cfg.setdefault("workers", {})
        workers[name] = value
        cfg.setdefault("events", []).append({"time": now_iso(), "action": "set_worker", "name": name, "value": value})
        cfg["events"] = cfg["events"][-200:]
        save_state("runtime_config")
    return value


def save_runtime_queue_setting(name, value):
    value = clamp_runtime_queue_value(name, value)
    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        queue_cfg = cfg.setdefault("queue", {})
        queue_cfg[str(name)] = value
        queue_cfg.setdefault("soft", MAIN_LOCAL_QUEUE_SOFT_LIMIT)
        queue_cfg.setdefault("hard", MAIN_LOCAL_QUEUE_HARD_LIMIT)
        cfg.setdefault("events", []).append({"time": now_iso(), "action": "set_queue", "name": name, "value": value})
        cfg["events"] = cfg["events"][-200:]
        save_state("runtime_config")
    return value


def runtime_config_has_manual_tuning(cfg):
    events = cfg.get("events", []) if isinstance(cfg, dict) else []
    for event in events:
        if not isinstance(event, dict):
            continue
        if event.get("action") in {"set_worker", "set_queue", "queue_unlimited"}:
            return True
    return bool((cfg or {}).get("manual_tuning"))


def upgrade_runtime_speed_defaults_if_unmodified():
    if "runtime_config" not in STATE:
        return False
    force_profile = env_bool("ROYELLS_FORCE_RUNTIME_SPEED_PROFILE", True)
    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        if runtime_config_has_manual_tuning(cfg) and not force_profile:
            return False
        workers = cfg.setdefault("workers", {})
        queue_cfg = cfg.setdefault("queue", {})
        desired_workers = {
            "download": DOWNLOAD_WORKERS,
            "upload": UPLOAD_WORKERS,
            "link": LINK_WORKERS,
            "button": BUTTON_WORKERS,
        }
        changed = False
        for name, desired in desired_workers.items():
            old_value = int(workers.get(name, 0) or 0)
            desired = int(desired)
            if force_profile and old_value != desired:
                workers[name] = desired
                changed = True
            elif old_value < desired:
                workers[name] = desired
                changed = True
        if queue_cfg.get("soft") != MAIN_LOCAL_QUEUE_SOFT_LIMIT:
            queue_cfg["soft"] = MAIN_LOCAL_QUEUE_SOFT_LIMIT
            changed = True
        if queue_cfg.get("hard") != MAIN_LOCAL_QUEUE_HARD_LIMIT:
            queue_cfg["hard"] = MAIN_LOCAL_QUEUE_HARD_LIMIT
            changed = True
        if changed:
            cfg.setdefault("events", []).append(
                {
                    "time": now_iso(),
                    "action": "upgrade_speed_defaults",
                    "version": APP_VERSION,
                    "forced": force_profile,
                }
            )
            cfg["events"] = cfg["events"][-200:]
            save_state("runtime_config")
    return changed


def apply_runtime_config():
    global DOWNLOAD_WORKERS, UPLOAD_WORKERS, LINK_WORKERS, BUTTON_WORKERS, TARGET_CHAT_ID
    if "runtime_config" not in STATE:
        return
    upgraded_speed_defaults = upgrade_runtime_speed_defaults_if_unmodified()
    snap = runtime_worker_snapshot()
    cfg_snapshot = STATE.get("runtime_config", {}) if STATE else {}
    worker_fields = (
        ("download", "ROYELLS_DOWNLOAD_WORKERS", DOWNLOAD_WORKERS),
        ("upload", "ROYELLS_UPLOAD_WORKERS", UPLOAD_WORKERS),
        ("link", "ROYELLS_LINK_WORKERS", LINK_WORKERS),
        ("button", "ROYELLS_BUTTON_WORKERS", BUTTON_WORKERS),
    )
    applied_workers = {}
    env_pinned = []
    for name, env_name, current_value in worker_fields:
        value = clamp_runtime_worker_value(name, snap.get(name, current_value))
        applied_workers[name] = value

    DOWNLOAD_WORKERS = applied_workers["download"]
    UPLOAD_WORKERS = applied_workers["upload"]
    LINK_WORKERS = applied_workers["link"]
    BUTTON_WORKERS = applied_workers["button"]
    target_cfg = cfg_snapshot.get("target") if isinstance(cfg_snapshot, dict) else {}
    target_override = str((target_cfg or {}).get("chat_id") or "").strip()
    if target_override and target_override not in ("0", "None"):
        TARGET_CHAT_ID = int(normalize_channel_id(target_override))

    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        cfg["workers"] = dict(applied_workers)
        cfg["queue"] = {"soft": MAIN_LOCAL_QUEUE_SOFT_LIMIT, "hard": MAIN_LOCAL_QUEUE_HARD_LIMIT}
        cfg.setdefault("events", []).append(
            {
                "time": now_iso(),
                "action": "startup_apply",
                "env_pinned": env_pinned,
                "speed_defaults_upgraded": upgraded_speed_defaults,
            }
        )
        cfg["events"] = cfg["events"][-200:]
        save_state("runtime_config")
    log_event(
        "Runtime config applied: "
        f"download={DOWNLOAD_WORKERS}, upload={UPLOAD_WORKERS}, link={LINK_WORKERS}, button={BUTTON_WORKERS}, "
        f"media_queue_limits=download:{IN_MEMORY_QUEUE_MAX}/upload:{UPLOAD_READY_QUEUE_MAX}; "
        f"environment pinned={','.join(env_pinned) or 'none'}; "
        f"speed_defaults_upgraded={upgraded_speed_defaults}."
    )


def save_runtime_admin_ids(admin_ids):
    normalized = sorted({int(item) for item in admin_ids if int(item) > 0 and int(item) != int(OWNER_ID or 0)})
    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        cfg["admins"] = normalized
        cfg.setdefault("events", []).append({"time": now_iso(), "action": "set_admins", "count": len(normalized)})
        cfg["events"] = cfg["events"][-200:]
        save_state("runtime_config")
    return normalized


def add_runtime_admin_id(user_id):
    ids = runtime_admin_ids()
    ids.add(int(user_id))
    return save_runtime_admin_ids(ids)


def remove_runtime_admin_id(user_id):
    ids = runtime_admin_ids()
    ids.discard(int(user_id))
    return save_runtime_admin_ids(ids)


def save_runtime_target_chat(chat_id, title="", source_link="", username=""):
    global TARGET_CHAT_ID
    normalized = int(normalize_channel_id(chat_id))
    TARGET_CHAT_ID = normalized
    JOIN_LINK_CACHE.update({"link": "", "time": 0})
    with state_mutex:
        cfg = STATE.setdefault("runtime_config", default_state("runtime_config"))
        cfg["target"] = {
            "chat_id": str(normalized),
            "title": str(title or ""),
            "source_link": str(source_link or ""),
            "username": str(username or ""),
            "updated_at": now_iso(),
        }
        cfg.setdefault("events", []).append(
            {"time": now_iso(), "action": "set_target", "chat_id": str(normalized), "title": str(title or "")[:120]}
        )
        cfg["events"] = cfg["events"][-200:]
        save_state("runtime_config")
    log_event(f"Target channel updated at runtime: {normalized} ({title or 'no title'}).")
    return normalized


def get_runtime_target_config():
    with contextlib.suppress(Exception):
        with state_mutex:
            target = deepcopy(STATE.get("runtime_config", {}).get("target", {}))
        if target:
            return target
    return {"chat_id": str(TARGET_CHAT_ID or 0), "title": "", "source_link": "", "username": "", "updated_at": ""}


