async def fetch_messages_from_meta(metas):
    result = []
    for meta in metas:
        chat_id = meta.get("chat_id")
        msg_id = meta.get("message_id")
        if chat_id is None or msg_id is None:
            continue
        try:
            source_peer = await resolve_source_peer_for_access(chat_id, "recovery")
            msg = await tg_call(
                "recovery get_messages",
                userbot.get_messages,
                source_peer,
                int(msg_id),
                retries=2,
                _timeout_seconds=45,
            )
            if msg and not msg.empty and is_valid_media(msg):
                result.append(msg)
        except Exception as e:
            if is_peer_id_error(e):
                with contextlib.suppress(Exception):
                    source_peer = await resolve_source_peer_for_access(chat_id, "recovery_retry", force_refresh=True)
                    msg = await tg_call("recovery retry get_messages", userbot.get_messages, source_peer, int(msg_id), retries=1)
                    if msg and not msg.empty and is_valid_media(msg):
                        result.append(msg)
                        continue
            log_event_rate_limited(
                f"recovery_fetch:{chat_id}",
                f"Recovery fetch failed for {chat_id}/{msg_id}: {e}",
                interval_seconds=60,
            )
    return result


def recovery_record_media_uids(record):
    return [
        str(meta.get("media_uid") or "")
        for meta in record.get("messages", [])
        if isinstance(meta, dict) and meta.get("media_uid")
    ]


def recovery_record_is_complete(record):
    uids = recovery_record_media_uids(record)
    return bool(uids) and all(known_duplicate_uid(uid) for uid in uids)


def update_persisted_queue_status(state_name, job_id, status, error=""):
    with state_mutex:
        item = STATE[state_name].setdefault("items", {}).get(job_id)
        if not item:
            return False
        item["status"] = status
        item["last_error"] = str(error)[:500] if error else ""
        item["updated_at"] = now_iso()
        save_state(state_name)
    refresh_persisted_queue_reservation(job_id)
    return True


def queue_recovery_notification_event_key(job_ids):
    """Create a stable, privacy-safe identity for one recovered job set."""

    normalized = sorted(
        {
            str(job_id).strip()
            for job_id in (job_ids or [])
            if str(job_id).strip()
        }
    )
    material = "|".join(normalized) or "recovery-summary-without-job-id"
    return hashlib.sha256(material.encode("utf-8")).hexdigest()


def queue_recovery_notification_state_locked():
    """Return the normalized durable owner-status cursor; caller holds state_mutex."""

    runtime_config = STATE.get("runtime_config")
    if not isinstance(runtime_config, dict):
        runtime_config = {}
        STATE["runtime_config"] = runtime_config
    record = runtime_config.get("queue_recovery_notification")
    if not isinstance(record, dict):
        record = {}
        runtime_config["queue_recovery_notification"] = record

    record["schema_version"] = 1
    for name in (
        "message_chat_id",
        "message_id",
        "event_count",
        "coalesced_count",
    ):
        try:
            record[name] = max(0, int(record.get(name) or 0))
        except (TypeError, ValueError):
            record[name] = 0
    for name in (
        "message_created_at",
        "last_update_at",
        "last_visible_update_at",
        "pending_send_at",
    ):
        try:
            record[name] = max(0.0, float(record.get(name) or 0.0))
        except (TypeError, ValueError):
            record[name] = 0.0
    for name in (
        "last_event_key",
        "last_visible_event_key",
        "pending_send_token",
        "pending_send_event_key",
        "last_delivery_error",
    ):
        record[name] = str(record.get(name) or "")[:512]

    tracked = record.get("tracked_job_ids")
    if not isinstance(tracked, list):
        tracked = []
    record["tracked_job_ids"] = list(
        dict.fromkeys(
            str(job_id).strip()
            for job_id in tracked
            if str(job_id).strip()
        )
    )[-QUEUE_RECOVERY_NOTIFICATION_MAX_TRACKED_JOBS:]
    if not isinstance(record.get("last_summary"), dict):
        record["last_summary"] = {}
    return record


def format_queue_recovery_notification(summary, unique_jobs, coalesced_count):
    """Render one editable owner status without exposing queue internals in chat."""

    recovered = max(0, int(summary.get("recovered") or 0))
    deferred = max(0, int(summary.get("deferred") or 0))
    pending = max(0, int(summary.get("pending") or 0))
    duplicates = max(0, int(summary.get("duplicates") or 0))
    lines = [
        "Queue recovery status",
        f"Latest pass admitted: {recovered} job(s)",
        f"Deferred safely: {deferred} | Pending: {pending}",
        f"Unique recovered jobs in this incident: {max(0, int(unique_jobs or 0))}",
    ]
    if duplicates:
        lines.append(f"Already-complete duplicates skipped: {duplicates}")
    if coalesced_count:
        lines.append(
            f"Repeated recovery signals merged into this status: {coalesced_count}"
        )
    updated_at = str(summary.get("updated_at") or "")
    if updated_at:
        lines.append(f"Updated: {updated_at}")
    return "\n".join(lines)[:3500]


def prepare_queue_recovery_notification(
    recovered_job_ids,
    recovered,
    deferred,
    skipped_duplicates,
    pending,
    *,
    force_new_message=False,
    record_event=True,
    now_epoch=None,
):
    """Persist a notification plan before Telegram I/O.

    This function intentionally plans only the owner notification.  It never
    alters the recovered descriptor, reservations, retry schedule, or error
    handling, so notification deduplication cannot suppress real recovery work.
    """

    now_epoch = float(time.time() if now_epoch is None else now_epoch)
    job_ids = list(
        dict.fromkeys(
            str(job_id).strip()
            for job_id in (recovered_job_ids or [])
            if str(job_id).strip()
        )
    )
    event_key = queue_recovery_notification_event_key(job_ids)
    save_required = False

    with state_mutex:
        record = queue_recovery_notification_state_locked()
        message_created_at = float(record.get("message_created_at") or 0.0)
        if (
            record.get("message_id")
            and message_created_at
            and now_epoch - message_created_at
            > QUEUE_RECOVERY_NOTIFICATION_REUSE_SECONDS
        ):
            # A day-old status should not be silently repurposed for a new
            # incident, but immediate restarts continue editing the same one.
            record["message_chat_id"] = 0
            record["message_id"] = 0
            record["message_created_at"] = 0.0
            record["last_visible_update_at"] = 0.0
            record["last_visible_event_key"] = ""
            force_new_message = True
            save_required = True

        pending_at = float(record.get("pending_send_at") or 0.0)
        if (
            record.get("pending_send_token")
            and pending_at
            and now_epoch - pending_at > QUEUE_RECOVERY_NOTIFICATION_REUSE_SECONDS
        ):
            record["pending_send_token"] = ""
            record["pending_send_event_key"] = ""
            record["pending_send_at"] = 0.0
            save_required = True

        tracked_job_ids = list(record.get("tracked_job_ids") or [])
        tracked_set = set(tracked_job_ids)
        new_job_ids = [job_id for job_id in job_ids if job_id not in tracked_set]
        if new_job_ids:
            tracked_job_ids.extend(new_job_ids)
            record["tracked_job_ids"] = tracked_job_ids[
                -QUEUE_RECOVERY_NOTIFICATION_MAX_TRACKED_JOBS:
            ]
            save_required = True

        same_event = event_key == str(record.get("last_event_key") or "")
        if record_event:
            record["event_count"] = int(record.get("event_count") or 0) + 1
            if same_event:
                record["coalesced_count"] = int(record.get("coalesced_count") or 0) + 1
            save_required = True

        summary = {
            "recovered": max(0, int(recovered or 0)),
            "deferred": max(0, int(deferred or 0)),
            "duplicates": max(0, int(skipped_duplicates or 0)),
            "pending": max(0, int(pending or 0)),
            "updated_at": now_iso(),
        }
        record["last_event_key"] = event_key
        record["last_update_at"] = now_epoch
        record["last_summary"] = summary
        save_required = True

        text = format_queue_recovery_notification(
            summary,
            len(record.get("tracked_job_ids") or []),
            int(record.get("coalesced_count") or 0),
        )
        message_id = int(record.get("message_id") or 0)
        message_chat_id = int(record.get("message_chat_id") or 0)
        if message_id and message_chat_id and not force_new_message:
            visible_at = float(record.get("last_visible_update_at") or 0.0)
            should_edit = bool(new_job_ids) or summary["pending"] == 0
            if now_epoch - visible_at >= QUEUE_RECOVERY_NOTIFICATION_EDIT_MIN_INTERVAL_SECONDS:
                should_edit = True
            action = "edit" if should_edit else "dedupe"
            token = ""
        else:
            pending_token = str(record.get("pending_send_token") or "")
            pending_event_key = str(record.get("pending_send_event_key") or "")
            if pending_token and pending_event_key == event_key and not force_new_message:
                # We may have sent immediately before a crash.  Prefer one
                # possibly stale owner status over an unbounded duplicate flood.
                action = "dedupe_pending"
                token = ""
            else:
                token = hashlib.sha256(
                    f"{event_key}|{now_epoch:.6f}|{record.get('event_count', 0)}".encode(
                        "utf-8"
                    )
                ).hexdigest()
                record["pending_send_token"] = token
                record["pending_send_event_key"] = event_key
                record["pending_send_at"] = now_epoch
                action = "send"
                save_required = True

    if save_required:
        try:
            save_state("runtime_config")
        except Exception as exc:
            # Recovery itself is already durable; skip a non-durable chat send
            # rather than creating an externally visible duplicate after restart.
            log_event_rate_limited(
                "queue_recovery_notification_state_save_failed",
                "Queue recovery status persistence failed; owner notification was "
                f"not sent: {format_exception_for_log(exc)}",
                interval_seconds=60,
            )
            return {"action": "skip", "reason": "state_persistence_failed"}

    return {
        "action": action,
        "token": token,
        "event_key": event_key,
        "message_chat_id": message_chat_id,
        "message_id": message_id,
        "text": text,
        "recovered": summary["recovered"],
        "deferred": summary["deferred"],
        "pending": summary["pending"],
    }


def finalize_queue_recovery_notification(
    plan,
    outcome,
    message_id=0,
    error="",
    clear_pending=False,
):
    """Commit delivery knowledge after a planned send/edit without raising."""

    if not isinstance(plan, dict):
        return False
    now_epoch = time.time()
    with state_mutex:
        record = queue_recovery_notification_state_locked()
        action = str(plan.get("action") or "")
        if outcome == "sent" and action == "send":
            if str(record.get("pending_send_token") or "") != str(plan.get("token") or ""):
                return False
            try:
                confirmed_message_id = int(message_id or 0)
            except (TypeError, ValueError):
                confirmed_message_id = 0
            if confirmed_message_id <= 0:
                return False
            record["message_chat_id"] = int(OWNER_ID or 0)
            record["message_id"] = confirmed_message_id
            record["message_created_at"] = now_epoch
            record["last_visible_update_at"] = now_epoch
            record["last_visible_event_key"] = str(plan.get("event_key") or "")
            record["pending_send_token"] = ""
            record["pending_send_event_key"] = ""
            record["pending_send_at"] = 0.0
            record["last_delivery_error"] = ""
        elif outcome == "edited" and action == "edit":
            record["last_visible_update_at"] = now_epoch
            record["last_visible_event_key"] = str(plan.get("event_key") or "")
            record["last_delivery_error"] = ""
        elif outcome == "missing" and action == "edit":
            # This error is definitive: the old chat message is gone, so the
            # next plan can create exactly one replacement status.
            record["message_chat_id"] = 0
            record["message_id"] = 0
            record["message_created_at"] = 0.0
            record["last_visible_update_at"] = 0.0
            record["last_visible_event_key"] = ""
            record["last_delivery_error"] = str(error or "message missing")[:512]
        elif outcome == "failed":
            # Transport timeouts can happen after Telegram accepted a send.
            # Keep the pending token for ambiguous failures so a restart cannot
            # turn one uncertain message into a chat flood.  Only a known
            # permanent rejection clears it for a later retry.
            if (
                action == "send"
                and clear_pending
                and str(record.get("pending_send_token") or "")
                == str(plan.get("token") or "")
            ):
                record["pending_send_token"] = ""
                record["pending_send_event_key"] = ""
                record["pending_send_at"] = 0.0
            record["last_delivery_error"] = str(error or "notification delivery failed")[:512]
        else:
            return False
    try:
        save_state("runtime_config")
    except Exception:
        # The delivery was already attempted.  Never propagate a reporting
        # persistence failure into the queue-recovery path.
        return False
    return True


def queue_recovery_notification_edit_is_missing(error):
    text = f"{error.__class__.__name__} {error}".lower()
    return any(
        marker in text
        for marker in (
            "message_id_invalid",
            "message id invalid",
            "message to edit not found",
            "message not found",
            "message can't be edited",
            "message cannot be edited",
        )
    )


def queue_recovery_notification_edit_is_unchanged(error):
    text = f"{error.__class__.__name__} {error}".lower()
    return isinstance(error, MessageNotModified) or "message is not modified" in text


def queue_recovery_notification_send_failure_is_definitive(error):
    """Return true only when Telegram definitely rejected the send request."""

    text = f"{error.__class__.__name__} {error}".lower()
    return any(
        marker in text
        for marker in (
            "chat_id_invalid",
            "chat id invalid",
            "peer id invalid",
            "chat not found",
            "bot was blocked",
            "user is deactivated",
            "forbidden",
            "have no rights to send",
            "can't parse entities",
            "cannot parse entities",
            "message text is empty",
        )
    )


async def deliver_queue_recovery_notification_plan(plan):
    """Execute one persisted notification plan and return a compact outcome."""

    action = str((plan or {}).get("action") or "")
    if action == "send":
        try:
            sent = await telegram_gateway_await(
                "app.send_message queue recovery status",
                lambda: app.send_message(
                    OWNER_ID,
                    plan["text"],
                    disable_web_page_preview=True,
                ),
            )
        except Exception as exc:
            finalize_queue_recovery_notification(
                plan,
                "failed",
                error=exc,
                clear_pending=queue_recovery_notification_send_failure_is_definitive(
                    exc
                ),
            )
            log_event_rate_limited(
                "queue_recovery_notification_send_failed",
                "Queue recovery status notification failed safely: "
                f"{format_exception_for_log(exc)}",
                interval_seconds=60,
            )
            return "failed"
        finalize_queue_recovery_notification(plan, "sent", getattr(sent, "id", 0))
        return "sent"

    if action == "edit":
        try:
            await telegram_gateway_await(
                "app.edit_message_text queue recovery status",
                lambda: app.edit_message_text(
                    int(plan["message_chat_id"]),
                    int(plan["message_id"]),
                    plan["text"],
                    disable_web_page_preview=True,
                ),
            )
        except Exception as exc:
            if queue_recovery_notification_edit_is_unchanged(exc):
                finalize_queue_recovery_notification(plan, "edited")
                return "edited"
            if queue_recovery_notification_edit_is_missing(exc):
                finalize_queue_recovery_notification(plan, "missing", error=exc)
                return "missing"
            finalize_queue_recovery_notification(plan, "failed", error=exc)
            log_event_rate_limited(
                "queue_recovery_notification_edit_failed",
                "Queue recovery status edit failed safely; the existing owner "
                f"status was retained: {format_exception_for_log(exc)}",
                interval_seconds=60,
            )
            return "failed"
        finalize_queue_recovery_notification(plan, "edited")
        return "edited"

    return "skipped"


async def queue_recovery_notification_plan_is_durable(plan):
    """Confirm the send/edit cursor is on disk before externally visible I/O."""

    if str((plan or {}).get("action") or "") not in {"send", "edit"}:
        return False
    try:
        flushed = await run_blocking(
            "persistence",
            flush_state_saves,
            QUEUE_RECOVERY_NOTIFICATION_PERSIST_TIMEOUT_SECONDS,
        )
    except Exception as exc:
        flushed = False
        log_event_rate_limited(
            "queue_recovery_notification_flush_failed",
            "Queue recovery notification cursor could not be durably flushed; "
            f"chat send skipped: {format_exception_for_log(exc)}",
            interval_seconds=60,
        )
    if flushed:
        return True
    log_event_rate_limited(
        "queue_recovery_notification_flush_timeout",
        "Queue recovery notification cursor did not flush in time; chat send "
        "skipped to prevent a duplicate after restart.",
        interval_seconds=60,
    )
    return False


async def notify_queue_recovery_summary(
    recovered,
    deferred,
    skipped_duplicates,
    pending,
    recovered_job_ids=None,
):
    """Coalesce recovery summaries without affecting recovery correctness."""

    if (
        not QUEUE_RECOVERY_NOTIFICATION_ENABLED
        or not OWNER_ID
        or int(recovered or 0) <= 0
    ):
        return False
    async with queue_recovery_notification_lock:
        plan = prepare_queue_recovery_notification(
            recovered_job_ids,
            recovered,
            deferred,
            skipped_duplicates,
            pending,
        )
        action = str(plan.get("action") or "")
        if action in {"dedupe", "dedupe_pending"}:
            log_event_rate_limited(
                "queue_recovery_notification_coalesced",
                "Queue recovery owner notification coalesced into the existing "
                f"status; admitted={int(recovered or 0)} pending={int(pending or 0)}.",
                interval_seconds=QUEUE_RECOVERY_NOTIFICATION_EDIT_MIN_INTERVAL_SECONDS,
            )
            return False
        if not await queue_recovery_notification_plan_is_durable(plan):
            return False
        outcome = await deliver_queue_recovery_notification_plan(plan)
        if outcome != "missing":
            return outcome in {"sent", "edited"}

        # A deleted owner status is a known (not ambiguous) edit failure.  Make
        # one replacement immediately; generic network errors never do this.
        replacement = prepare_queue_recovery_notification(
            recovered_job_ids,
            recovered,
            deferred,
            skipped_duplicates,
            pending,
            force_new_message=True,
            record_event=False,
        )
        if not await queue_recovery_notification_plan_is_durable(replacement):
            return False
        return (
            await deliver_queue_recovery_notification_plan(replacement)
        ) == "sent"


async def recover_queue_state():
    if queue_recovery_lock.locked():
        log_event("Queue recovery already running; duplicate invocation skipped.")
        return {
            "busy": True,
            "recovered": 0,
            "deferred": len(persisted_recovery_pending_job_ids()),
            "duplicates": 0,
            "pending": len(persisted_recovery_pending_job_ids()),
        }
    async with queue_recovery_lock:
        await wait_while_session_invalid("queue recovery")
        recovered = 0
        recovered_job_ids = []
        deferred = 0
        skipped_duplicates = 0
        stuck_statuses = QUEUE_STUCK_STATUSES
        live_ids = live_pipeline_job_ids()

        with state_mutex:
            upload_records = deepcopy(STATE["upload_queue"].get("items", {}))
            download_records = deepcopy(STATE["download_queue"].get("items", {}))

        upload_stuck_ids = {
            str(job_id)
            for job_id, rec in upload_records.items()
            if rec.get("status") in stuck_statuses
        }

        for job_id, rec in upload_records.items():
            job_id = str(job_id)
            if rec.get("status") not in stuck_statuses:
                continue
            if job_id in live_ids:
                continue
            if recovery_record_is_complete(rec):
                update_persisted_queue_status("upload_queue", job_id, "skipped_duplicate")
                update_persisted_queue_status("download_queue", job_id, "skipped_duplicate")
                skipped_duplicates += 1
                continue
            if recovery_record_blocked_by_other_job(job_id, rec):
                deferred += 1
                continue
            if recovered >= QUEUE_RECOVERY_BATCH_LIMIT:
                deferred += 1
                continue

            files = rec.get("files", [])
            messages = await fetch_messages_from_meta(rec.get("messages", []))
            if not messages:
                update_persisted_queue_status(
                    "upload_queue",
                    job_id,
                    "failed",
                    "source message missing during recovery",
                )
                continue
            for message in messages:
                add_processing_keys(message.chat.id, message)

            admitted = False
            if files and len(files) == len(messages) and all(
                media_path_is_complete_enough(message, path)
                for message, path in zip(messages, files)
            ):
                for path in files:
                    track_download_file(path)
                job = {
                    "job_id": job_id,
                    "post_uid": rec.get("post_uid", job_id),
                    "type": rec.get("type", "single"),
                    "messages": messages,
                    "files": files,
                    "ch_name": rec.get("ch_name", ""),
                    "attempt": 1,
                    "is_fallback": rec.get("is_fallback", False),
                    "source": rec.get("source", "recovery"),
                    "sync_run_id": rec.get("sync_run_id"),
                    "force_upload": bool(rec.get("force_upload")),
                    "manual_link_url": rec.get("manual_link_url", ""),
                    "status_chat_id": rec.get("status_chat_id", 0),
                    "status_message_id": rec.get("status_message_id", 0),
                    "_permanent_retry_count": int(
                        rec.get("permanent_retry_count") or 0
                    ),
                    "_fresh_download_recovery_count": int(
                        rec.get("fresh_download_recovery_count") or 0
                    ),
                    "_source_fresh_download_deferred_count": int(
                        rec.get("source_fresh_download_deferred_count") or 0
                    ),
                    "_source_fresh_download_deferred_due_at": float(
                        rec.get("source_fresh_download_deferred_due_at") or 0
                    ),
                    "_source_fresh_download_deferred_reason": str(
                        rec.get("source_fresh_download_deferred_reason") or ""
                    )[:120],
                    "_manual_fresh_download_deferred_count": int(
                        rec.get("manual_fresh_download_deferred_count") or 0
                    ),
                    "_manual_fresh_download_deferred_due_at": float(
                        rec.get("manual_fresh_download_deferred_due_at") or 0
                    ),
                    "_manual_fresh_download_deferred_reason": str(
                        rec.get("manual_fresh_download_deferred_reason") or ""
                    )[:120],
                }
                record_upload_job(job, "queued_recovered")
                stamp_queue_job(job, "upload")
                try:
                    upload_queue.put_nowait(job)
                    admitted = True
                except asyncio.QueueFull:
                    admitted = schedule_queue_retry(
                        "upload",
                        job,
                        5,
                        "startup recovery upload window full",
                    )
            else:
                admitted = await enqueue_media_job(
                    rec.get("type", "single"),
                    messages,
                    rec.get("ch_name", ""),
                    attempt=1,
                    is_fallback=rec.get("is_fallback", False),
                    source=rec.get("source", "recovery"),
                    sync_run_id=rec.get("sync_run_id"),
                    force_upload=bool(rec.get("force_upload")),
                    manual_link_url=rec.get("manual_link_url", ""),
                    status_chat_id=rec.get("status_chat_id", 0),
                    status_message_id=rec.get("status_message_id", 0),
                    reservation_owner=job_id,
                    recovery_job_id=job_id,
                    permanent_retry_count=rec.get("permanent_retry_count", 0),
                    fresh_download_recovery_count=rec.get(
                        "fresh_download_recovery_count", 0
                    ),
                    source_fresh_download_deferred_count=rec.get(
                        "source_fresh_download_deferred_count", 0
                    ),
                    source_fresh_download_deferred_due_at=rec.get(
                        "source_fresh_download_deferred_due_at", 0
                    ),
                    source_fresh_download_deferred_reason=rec.get(
                        "source_fresh_download_deferred_reason", ""
                    ),
                    manual_fresh_download_deferred_count=rec.get(
                        "manual_fresh_download_deferred_count", 0
                    ),
                    manual_fresh_download_deferred_due_at=rec.get(
                        "manual_fresh_download_deferred_due_at", 0
                    ),
                    manual_fresh_download_deferred_reason=rec.get(
                        "manual_fresh_download_deferred_reason", ""
                    ),
                )
            if admitted:
                recovered += 1
                recovered_job_ids.append(job_id)
            else:
                if recovery_record_is_complete(rec):
                    update_persisted_queue_status("upload_queue", job_id, "skipped_duplicate")
                    update_persisted_queue_status("download_queue", job_id, "skipped_duplicate")
                    skipped_duplicates += 1
                else:
                    for message in messages:
                        remove_processing_keys(message.chat.id, message)
                    deferred += 1
            if QUEUE_RECOVERY_ITEM_DELAY_SECONDS:
                await asyncio.sleep(QUEUE_RECOVERY_ITEM_DELAY_SECONDS)

        for job_id, rec in download_records.items():
            job_id = str(job_id)
            if job_id in upload_stuck_ids or rec.get("status") not in stuck_statuses:
                continue
            if job_id in live_ids:
                continue
            if recovery_record_is_complete(rec):
                update_persisted_queue_status("download_queue", job_id, "skipped_duplicate")
                skipped_duplicates += 1
                continue
            if recovery_record_blocked_by_other_job(job_id, rec):
                deferred += 1
                continue
            if recovered >= QUEUE_RECOVERY_BATCH_LIMIT:
                deferred += 1
                continue

            messages = await fetch_messages_from_meta(rec.get("messages", []))
            if not messages:
                update_persisted_queue_status(
                    "download_queue",
                    job_id,
                    "failed",
                    "source message missing during recovery",
                )
                continue
            for message in messages:
                add_processing_keys(message.chat.id, message)
            admitted = await enqueue_media_job(
                rec.get("type", "single"),
                messages,
                rec.get("ch_name", ""),
                attempt=1,
                is_fallback=rec.get("is_fallback", False),
                source=rec.get("source", "recovery"),
                sync_run_id=rec.get("sync_run_id"),
                force_upload=bool(rec.get("force_upload")),
                manual_link_url=rec.get("manual_link_url", ""),
                status_chat_id=rec.get("status_chat_id", 0),
                status_message_id=rec.get("status_message_id", 0),
                reservation_owner=job_id,
                recovery_job_id=job_id,
                partial_download_files=rec.get("partial_download_files", []),
                partial_download_message_metas=rec.get("partial_download_messages", []),
                permanent_retry_count=rec.get("permanent_retry_count", 0),
                fresh_download_recovery_count=rec.get(
                    "fresh_download_recovery_count", 0
                ),
                source_fresh_download_deferred_count=rec.get(
                    "source_fresh_download_deferred_count", 0
                ),
                source_fresh_download_deferred_due_at=rec.get(
                    "source_fresh_download_deferred_due_at", 0
                ),
                source_fresh_download_deferred_reason=rec.get(
                    "source_fresh_download_deferred_reason", ""
                ),
                source_item_unavailable_retries=rec.get(
                    "source_item_unavailable_retries", {}
                ),
                manual_fresh_download_deferred_count=rec.get(
                    "manual_fresh_download_deferred_count", 0
                ),
                manual_fresh_download_deferred_due_at=rec.get(
                    "manual_fresh_download_deferred_due_at", 0
                ),
                manual_fresh_download_deferred_reason=rec.get(
                    "manual_fresh_download_deferred_reason", ""
                ),
            )
            if admitted:
                recovered += 1
                recovered_job_ids.append(job_id)
            else:
                if recovery_record_is_complete(rec):
                    update_persisted_queue_status("download_queue", job_id, "skipped_duplicate")
                    skipped_duplicates += 1
                else:
                    deferred += 1
            if QUEUE_RECOVERY_ITEM_DELAY_SECONDS:
                await asyncio.sleep(QUEUE_RECOVERY_ITEM_DELAY_SECONDS)

        pending = len(persisted_recovery_pending_job_ids())
        if recovered:
            metric_increment("queue_recovery_jobs", recovered)
            metric_increment("queue_restore_success", recovered)
        if recovered or skipped_duplicates or deferred or pending:
            log_event(
                f"Queue recovery staged: admitted={recovered}, duplicate={skipped_duplicates}, "
                f"deferred={deferred}, pending={pending}, batch_limit={QUEUE_RECOVERY_BATCH_LIMIT}, "
                f"queue_limits=download:{channel_download_queue.maxsize}/"
                f"upload:{upload_queue.maxsize}."
            )
            if recovered:
                with contextlib.suppress(Exception):
                    await notify_queue_recovery_summary(
                        recovered,
                        deferred,
                        skipped_duplicates,
                        pending,
                        recovered_job_ids,
                    )
        else:
            log_event("No unfinished queue jobs found.")
        return {
            "busy": False,
            "recovered": recovered,
            "deferred": deferred,
            "duplicates": skipped_duplicates,
            "pending": pending,
        }


async def channel_download_worker_loop(worker_id):
    while True:
        await wait_while_session_invalid(f"DL W{worker_id}")
        job = await channel_download_queue.get()
        observe_queue_wait(job, "download")
        worker_name = f"DL W{worker_id}"
        mark_worker_job(worker_name, job)
        job["_v21_worker_id"] = worker_name
        attempt = job.get("attempt", 1)
        max_attempts = SOURCE_JOB_MAX_RETRIES if pressure_managed_source(job.get("source", "")) else MAX_RETRIES
        job_type = job["type"]
        messages = job["messages"]
        ch_name = job["ch_name"]
        files_to_cleanup = []
        should_cleanup_on_fail = False

        try:
            record_download_job(job, "downloading")
            record_total_job(job, "downloading")
            log_event(f"[DL W{worker_id}] Downloading {job_type} from {ch_name} attempt {attempt}")
            if V21_ENGINE is not None:
                await V21_ENGINE.wait_for_download_capacity(
                    job=job,
                    worker_id=worker_name,
                )
            await update_manual_link_status(
                job,
                f"Telegram media downloading...\nAttempt: {attempt}\nSource: {ch_name}",
            )
            await run_blocking("media", cleanup_download_dir_if_needed)
            download_disk = sane_disk_snapshot(DOWNLOAD_DIR)
            if (
                download_disk.get("trusted")
                and int(download_disk.get("free") or 0)
                < max(1, MIN_FREE_STORAGE_MB) * 1024 * 1024
            ):
                raise Exception(f"low runtime storage: less than {MIN_FREE_STORAGE_MB} MB free")
            download_bytes = await run_blocking(
                "media", directory_size_bytes, DOWNLOAD_DIR
            )
            if download_bytes >= max(1, DOWNLOAD_STORAGE_LIMIT_MB) * 1024 * 1024:
                raise RuntimeError(
                    f"download storage budget reached: {download_bytes // (1024 * 1024)} MB "
                    f"used of {DOWNLOAD_STORAGE_LIMIT_MB} MB"
                )
            downloaded_files = []
            downloaded_messages = []
            deferred_terminal_messages = []
            unavailable_cooldown_messages = []
            terminal_failure_codes = []
            duplicate_skipped = 0

            for idx, original_msg in enumerate(messages):
                touch_worker_job(worker_name, job)
                await asyncio.sleep(0)
                m = original_msg
                job["_hybrid_item_index"] = idx
                # An unavailable item remains owned by this durable job until
                # its exact cooldown is due.  Do not refresh/download it early
                # and do not release its processing key for a new source scan.
                if source_item_unavailable_remaining_seconds(job, m) > 0:
                    unavailable_cooldown_messages.append(m)
                    continue
                if DOWNLOAD_REFRESH_BEFORE_EACH_ITEM:
                    try:
                        fresh_m = await tg_call(
                            "download refresh message",
                            userbot.get_messages,
                            m.chat.id,
                            m.id,
                            retries=1,
                        )
                        if fresh_m and not fresh_m.empty:
                            m = fresh_m
                            messages[idx] = fresh_m
                    except Exception:
                        pass

                if not job.get("force_upload") and await known_duplicate_uid_async(get_media_uid(m)):
                    remove_processing_keys(m.chat.id, m)
                    duplicate_skipped += 1
                    continue

                resumed_fp = partial_download_file_for_message(job, m)
                if resumed_fp:
                    track_download_file(resumed_fp, owner=worker_name)
                    if resumed_fp not in files_to_cleanup:
                        files_to_cleanup.append(resumed_fp)
                    valid_resume, resume_reason, _resume_code = await validate_downloaded_source_file(
                        job,
                        m,
                        resumed_fp,
                        worker_name,
                    )
                    if valid_resume:
                        clear_source_item_unavailable_retry(job, m)
                        downloaded_files.append(resumed_fp)
                        downloaded_messages.append(m)
                        log_event(
                            f"[DL W{worker_id}] Resumed partial download for "
                            f"{source_message_key(m)} from checkpoint."
                        )
                        continue
                    log_event(
                        f"[DL W{worker_id}] Discarding invalid partial download "
                        f"for {source_message_key(m)}: {resume_reason}"
                    )
                    defer_download_cleanup(
                        [resumed_fp],
                        "invalid partial download cleanup",
                    )

                ext = ".mp4" if m.video else ".jpg"
                fp = None
                safe_path_text = ""
                temp_path_text = ""
                last_failure_code = "missing"
                last_failure_reason = "download returned no file path"
                last_failure_size = 0
                for item_attempt in range(1, ZERO_BYTE_ITEM_MAX_RETRIES + 1):
                    safe_path = DOWNLOAD_DIR / (
                        f"{job['job_id']}_{idx}_try{item_attempt}_{uuid.uuid4().hex[:8]}{ext}"
                    )
                    safe_path_text = str(safe_path)
                    temp_path_text = f"{safe_path_text}.temp"
                    cleanup(safe_path_text, temp_path_text)
                    track_download_file(safe_path_text, owner=worker_name)
                    track_download_file(temp_path_text, owner=worker_name)
                    files_to_cleanup.extend([safe_path_text, temp_path_text])
                    if item_attempt > 1:
                        try:
                            fresh_m = await tg_call(
                                "media retry refresh message",
                                userbot.get_messages,
                                m.chat.id,
                                m.id,
                                retries=1,
                            )
                            if fresh_m and not fresh_m.empty:
                                m = fresh_m
                                messages[idx] = fresh_m
                        except Exception:
                            pass
                    item_timeout = download_timeout_for_message(m)
                    try:
                        async with worker_media_rpc_heartbeat(
                            worker_name,
                            job,
                            f"download media item {idx + 1}/{len(messages)}",
                        ):
                            fp = await hybrid_download_media(
                                job,
                                m,
                                safe_path_text,
                                item_timeout,
                                DOWNLOAD_ITEM_API_RETRIES,
                            )
                    except Exception as download_error:
                        fp = None
                        if (
                            item_attempt < ZERO_BYTE_ITEM_MAX_RETRIES
                            and (
                                isinstance(download_error, TimeoutError)
                                or is_temporary_network_error(download_error)
                            )
                        ):
                            defer_download_cleanup(
                                [safe_path_text, temp_path_text],
                                "download retry attempt cleanup",
                            )
                            log_event_rate_limited(
                                f"download_retry:{m.chat.id}",
                                f"Download item retry {item_attempt}/"
                                f"{ZERO_BYTE_ITEM_MAX_RETRIES} for {ch_name}: "
                                f"{str(download_error)[:140]}",
                                interval_seconds=30,
                            )
                            await asyncio.sleep(min(10, 2 * item_attempt))
                            continue
                        raise
                    observed_size = 0
                    if fp and os.path.exists(fp):
                        with contextlib.suppress(OSError):
                            observed_size = max(0, int(os.path.getsize(fp)))
                    if observed_size >= minimum_complete_media_size(m):
                        valid_file, validation_reason, validation_code = await validate_downloaded_source_file(
                            job,
                            m,
                            fp,
                            worker_name,
                        )
                        if valid_file:
                            break
                        last_failure_code = str(validation_code or "validation_failed")
                        last_failure_reason = str(validation_reason or "media validation failed")
                        last_failure_size = observed_size
                        defer_download_cleanup(
                            [fp, safe_path_text, temp_path_text],
                            "invalid download attempt cleanup",
                        )
                        fp = None
                        retry_note = (
                            "retrying source item"
                            if item_attempt < ZERO_BYTE_ITEM_MAX_RETRIES
                            else "bounded item attempts exhausted"
                        )
                        log_event(
                            f"Media validation failed ({item_attempt}/{ZERO_BYTE_ITEM_MAX_RETRIES}); "
                            f"{retry_note}: code={last_failure_code} reason={last_failure_reason}"
                        )
                        if item_attempt < ZERO_BYTE_ITEM_MAX_RETRIES:
                            await asyncio.sleep(min(30, ZERO_BYTE_RETRY_SECONDS * item_attempt))
                            continue
                        # A non-empty validation failure is not an empty download. Exit the
                        # item retry loop without falling through to the empty-file branch.
                        break

                    last_failure_size = observed_size
                    if not fp or not os.path.exists(fp):
                        last_failure_code = "missing"
                        last_failure_reason = "download returned no persistent file"
                    elif observed_size <= 0:
                        last_failure_code = "empty"
                        last_failure_reason = "downloaded file is empty"
                    else:
                        last_failure_code = "incomplete"
                        last_failure_reason = f"downloaded file is only {observed_size} bytes"
                    defer_download_cleanup(
                        [fp, safe_path_text, temp_path_text],
                        "empty or incomplete download attempt cleanup",
                    )
                    fp = None
                    chat_id_str = str(m.chat.id).replace("-100", "")
                    msg_link = (
                        f"https://t.me/{m.chat.username}/{m.id}"
                        if m.chat.username
                        else f"https://t.me/c/{chat_id_str}/{m.id}"
                    )
                    log_event(
                        f"Media download unavailable ({item_attempt}/{ZERO_BYTE_ITEM_MAX_RETRIES}); "
                        f"code={last_failure_code} bytes={last_failure_size} link={msg_link}"
                    )
                    if item_attempt < ZERO_BYTE_ITEM_MAX_RETRIES:
                        await asyncio.sleep(min(30, ZERO_BYTE_RETRY_SECONDS * item_attempt))

                if media_path_is_complete_enough(m, fp):
                    touch_worker_job(worker_name, job)
                    clear_source_item_unavailable_retry(job, m)
                    track_download_file(fp, owner=worker_name)
                    cleanup(temp_path_text)
                    untrack_download_files([temp_path_text])
                    if str(Path(fp).resolve()) != str(Path(safe_path_text).resolve()):
                        untrack_download_files([safe_path_text])
                    downloaded_files.append(fp)
                    downloaded_messages.append(m)
                    files_to_cleanup.append(fp)
                    if remember_partial_download(job, m, fp):
                        record_download_job(job, "downloading_partial", files=downloaded_files)
                    continue

                chat_id_str = str(m.chat.id).replace("-100", "")
                msg_link = f"https://t.me/{m.chat.username}/{m.id}" if m.chat.username else f"https://t.me/c/{chat_id_str}/{m.id}"
                terminal_error = RuntimeError(
                    f"media item deferred after {ZERO_BYTE_ITEM_MAX_RETRIES} item attempts: "
                    f"code={last_failure_code} reason={last_failure_reason}"
                )
                if last_failure_code == "empty":
                    metric_increment("zero_byte_media")
                else:
                    metric_increment("media_item_validation_deferred")
                # Every local validation/download result is retryable at the media-UID
                # level.  Do not create a watch/dead entry here: repeated scans of a
                # playable Telegram item must not turn a shallow parser verdict or a
                # transient partial download into a permanent skip.
                source_brain_record_messages([m], "failed", amount=1, title=ch_name, reason=terminal_error)
                deferred_terminal_messages.append(m)
                terminal_failure_codes.append(last_failure_code)
                log_event(
                    f"Media item retained for durable unavailable-source retry: "
                    f"code={last_failure_code} link={msg_link}"
                )

            if deferred_terminal_messages or unavailable_cooldown_messages:
                unique_codes = sorted(set(terminal_failure_codes)) or ["unknown"]
                retry_reason = RuntimeError(
                    f"{len(deferred_terminal_messages)} media item(s) need an independent "
                    f"unavailable-source retry; codes={','.join(unique_codes)}"
                )
                scheduled = False
                retry_job = job
                delay = 0
                if deferred_terminal_messages:
                    retry_job, delay = build_source_item_unavailable_retry_job(
                        job,
                        deferred_terminal_messages,
                        ",".join(unique_codes),
                    )
                else:
                    delay = max(1, source_item_unavailable_next_remaining_seconds(job))
                if retry_job is not None:
                    record_download_job(
                        retry_job,
                        "retry_later",
                        retry_reason,
                        files=downloaded_files,
                    )
                    record_total_job(retry_job, "queued_download", retry_reason)
                    record_sync_item(retry_job, "retry_later", retry_reason)
                    scheduled = schedule_queue_retry(
                        "download",
                        retry_job,
                        delay,
                        retry_reason,
                    )
                incident_messages = deferred_terminal_messages or unavailable_cooldown_messages
                incident_job = {**(retry_job or job), "messages": [incident_messages[0]]}
                record_production_incident(
                    "Source Item Unavailable",
                    "warning",
                    "download",
                    job=incident_job,
                    worker_name=worker_name,
                    queue_name="download",
                    exception=retry_reason,
                    recovery={
                        "attempted": True,
                        "retry_scheduled": bool(scheduled),
                        "failed": not bool(scheduled),
                    },
                    rate_limit_key=(
                        f"media_deferred:{job.get('job_id')}:"
                        f"{','.join(unique_codes)}:{attempt}"
                    ),
                )
                if scheduled:
                    # Successful members remain checkpointed and owned by the retry;
                    # never publish a partial album while another member is transient.
                    should_cleanup_on_fail = False
                    log_event(
                        f"Media job retained for durable unavailable-source retry: "
                        f"job={job.get('job_id')} codes={','.join(unique_codes)} "
                        f"partial={len(downloaded_files)} due_in={delay}s."
                    )
                    continue
                # The JSON record and processing reservation remain authoritative
                # even if the in-memory retry scheduler is unavailable.
                record_download_job(retry_job or job, "retry_later", retry_reason, files=downloaded_files)
                record_total_job(retry_job or job, "queued_download", retry_reason)
                record_sync_item(retry_job or job, "retry_later", retry_reason)
                should_cleanup_on_fail = False
                continue

            if not downloaded_files:
                if duplicate_skipped and not deferred_terminal_messages:
                    record_download_job(job, "skipped_duplicate")
                    record_total_job(job, "skipped_duplicate")
                    record_sync_item(job, "skipped_duplicate")
                else:
                    unique_codes = sorted(set(terminal_failure_codes)) or ["unknown"]
                    reason = (
                        f"all {len(deferred_terminal_messages)} media item(s) were deferred "
                        f"after bounded download/validation attempts; codes={','.join(unique_codes)}"
                    )
                    record_download_job(job, "failed_recoverable", reason)
                    record_total_job(job, "failed_recoverable", reason)
                    record_sync_item(job, "failed_recoverable", reason)
                should_cleanup_on_fail = True
                continue

            kept_messages = []
            kept_files = []
            skipped_filter = []
            for m, fp in zip(downloaded_messages, downloaded_files):
                if is_manual_telegram_link_job(job) and TELEGRAM_LINK_BYPASS_CONTENT_FILTER:
                    kept_messages.append(m)
                    kept_files.append(fp)
                    continue
                media_type = get_media_kind(m)
                skip_media, match_info = await content_filter_should_skip_file(fp, media_type)
                if skip_media:
                    sample = match_info.get("sample", {})
                    skipped_filter.append(
                        f"{get_media_uid(m) or m.id} -> sample #{sample.get('id')} distance {sample.get('distance')}"
                    )
                    remember_dead_media([m], RuntimeError("skipped_content_filter"), force_dead=True)
                    remove_processing_keys(m.chat.id, m)
                    untrack_download_files([fp])
                    cleanup(fp)
                    continue
                kept_messages.append(m)
                kept_files.append(fp)

            if skipped_filter:
                log_event(f"Content filter skipped {len(skipped_filter)} item(s) from {ch_name}: {', '.join(skipped_filter[:3])}")

            if not kept_files:
                record_download_job(job, "skipped_content_filter")
                record_total_job(job, "skipped_content_filter")
                record_sync_item(job, "skipped_content_filter")
                source_brain_record_messages(downloaded_messages, "filtered", amount=len(downloaded_messages), title=ch_name)
                should_cleanup_on_fail = True
                continue

            downloaded_messages = kept_messages
            downloaded_files = kept_files
            if job_type == "album" and len(downloaded_messages) < 2:
                job_type = "single"
                job["type"] = "single"

            job["messages"] = downloaded_messages
            upload_job = {**job, "files": downloaded_files, "attempt": 1}
            if V21_ENGINE is not None and isinstance(upload_job.get("_v21_context"), dict):
                upload_job["_v21_queue"] = "upload"
            record_download_job(job, "downloaded", files=downloaded_files)
            record_upload_job(upload_job, "queued_upload")
            record_total_job(job, "queued_upload")
            await update_manual_link_status(
                job,
                f"Telegram media downloaded.\nUploading to target...\nItems: {len(downloaded_files)}",
            )
            capacity_ready = await wait_for_local_media_capacity(job.get("source", "auto"))
            if capacity_ready and not upload_queue.full():
                stamp_queue_job(upload_job, "upload")
                try:
                    upload_queue.put_nowait(upload_job)
                except asyncio.QueueFull:
                    scheduled = schedule_queue_retry(
                        "upload",
                        upload_job,
                        2,
                        "download-to-upload active window full",
                    )
                    if not scheduled:
                        raise RuntimeError("upload retry admission full after download")
            else:
                scheduled = schedule_queue_retry("upload", upload_job, 2, "download-to-upload backpressure")
                if not scheduled:
                    raise RuntimeError("upload retry admission full after download")

        except asyncio.CancelledError as e:
            if SHUTDOWN_REQUESTED:
                raise
            job["attempt"] = attempt + 1
            reason = RuntimeError(
                f"download worker job stalled for more than {WORKER_STALL_SECONDS}s"
            )
            record_download_job(job, "retry", reason, files=files_to_cleanup)
            record_total_job(job, "queued_download", reason)
            scheduled = schedule_queue_retry("download", job, 5, reason)
            should_cleanup_on_fail = not scheduled
            if scheduled:
                metric_increment("recovered_workers")
                log_event(
                    f"[DL W{worker_id}] Stalled job {job.get('job_id')} cancelled and "
                    "requeued; healthy workers continue."
                )
            else:
                record_download_job(job, "retry_admission_failed", reason)
            with contextlib.suppress(Exception):
                await update_manual_link_status(
                    job,
                    "Stalled download cancelled safely. Job retained for automatic retry.",
                )

        except FloodWait as e:
            flood_role = getattr(e, "_royells_client_role", "userbot")
            note_global_flood_wait(e, flood_role)
            delay = max(1.0, telegram_flood_gate_remaining_seconds(flood_role))
            scheduled = False
            if attempt < max_attempts:
                job["attempt"] = attempt + 1
                record_download_job(job, "retry", e)
                await update_manual_link_status(job, f"Download flood wait handled. Retrying...\nAttempt: {attempt + 1}/{max_attempts}")
                scheduled = schedule_queue_retry("download", job, delay, e)
                should_cleanup_on_fail = True
                if not scheduled:
                    record_download_job(job, "retry_admission_failed", e)
                    for message in messages:
                        remove_processing_keys(message.chat.id, message)
            else:
                scheduled = schedule_source_job_retry_later(job, e)
                if scheduled:
                    should_cleanup_on_fail = True
                else:
                    err_msg = format_exception_for_log(e)
                    record_download_job(job, "failed", e)
                    record_total_job(job, "failed", e)
                    record_sync_item(job, "failed", e)
                    await update_manual_link_status(job, f"Download failed after retries:\n{err_msg[:500]}")
                    for m in messages:
                        remove_processing_keys(m.chat.id, m)
                    should_cleanup_on_fail = True
            record_production_incident(
                "FloodWait",
                "warning",
                "download",
                job=job,
                worker_name=worker_name,
                queue_name="download",
                exception=e,
                recovery={
                    "attempted": True,
                    "retry_scheduled": bool(scheduled),
                    "failed": not bool(scheduled),
                },
                rate_limit_key=f"download_floodwait:{job.get('job_id')}:{attempt}",
            )
        except Exception as e:
            err_text = str(e)
            err_msg = format_exception_for_log(e)
            incident_name = "Zero-byte Media" if "0-byte" in err_msg.lower() or "zero-byte" in err_msg.lower() else "Download Failure"
            record_production_incident(
                incident_name,
                "error",
                "download",
                job=job,
                worker_name=worker_name,
                queue_name="download",
                exception=e,
                recovery={
                    "attempted": False,
                    "retry_planned": attempt < max_attempts,
                },
                rate_limit_key=f"download_error:{job.get('job_id')}:{type(e).__name__}:{attempt}",
            )
            if should_reconnect_telegram_error(e):
                schedule_userbot_reconnect(f"download worker {worker_name}: {e}")
                delay = max(30, min(180, TELEGRAM_RECONNECT_COOLDOWN_SECONDS))
                record_download_job(job, "retry", f"telegram transport recovery: {err_msg[:180]}")
                record_total_job(job, "queued_download", e)
                await update_manual_link_status(
                    job,
                    "Telegram transport is recovering. Download job is retained for retry.",
                )
                scheduled = schedule_queue_retry("download", job, delay, e)
                should_cleanup_on_fail = True
                if not scheduled:
                    record_download_job(job, "retry_admission_failed", e)
                continue
            if should_skip_dead_media_now(e, attempt):
                record_download_job(job, "skipped_dead_media", e)
                record_total_job(job, "skipped_dead_media", e)
                record_sync_item(job, "skipped_dead_media", e)
                remember_dead_media(messages, e, force_dead=True)
                source_brain_record_messages(messages, "dead", amount=len(messages), title=ch_name, reason=e)
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                log_event(f"[DL W{worker_id}] Permanent dead-media skip after attempt {attempt}: {err_msg}")
                should_cleanup_on_fail = True
                continue
            channel_status = classify_channel_error(e)
            if channel_status and messages:
                source_msg = messages[0]
                access_result = await handle_source_access_error(
                    source_msg.chat.id,
                    e,
                    title=getattr(source_msg.chat, "title", "") or ch_name,
                    status=channel_status,
                    context="download",
                )
                if access_result == "expired_or_deleted":
                    record_download_job(job, "skipped_source_retired", e)
                    record_total_job(job, "skipped_source_retired", e)
                    record_sync_item(job, "skipped_source_retired", e)
                    for m in messages:
                        remove_processing_keys(m.chat.id, m)
                    should_cleanup_on_fail = True
                    continue
                if schedule_source_job_retry_later(job, e):
                    should_cleanup_on_fail = True
                    continue
                record_download_job(job, "failed", e)
                record_total_job(job, "failed", e)
                record_sync_item(job, "failed", e)
                await update_manual_link_status(job, f"Download failed:\n{err_msg[:500]}")
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                should_cleanup_on_fail = True
                continue
            if "sent to fallback" not in err_text:
                log_event(f"[DL ERROR W{worker_id}] {err_msg}")
                route_retryable = (
                    not isinstance(e, HybridDownloadError) or e.retryable
                )
                if (
                    route_retryable
                    and attempt < max_attempts
                    and not job.get("is_fallback")
                ):
                    await asyncio.sleep(5)
                    job["attempt"] = attempt + 1
                    record_download_job(job, "retry", e)
                    await update_manual_link_status(job, f"Download retry scheduled...\nAttempt: {attempt + 1}/{max_attempts}\nReason: {err_msg[:240]}")
                    scheduled = schedule_queue_retry("download", job, 5, e)
                    should_cleanup_on_fail = True
                    if not scheduled:
                        record_download_job(job, "retry_admission_failed", e)
                else:
                    offloaded = (
                        await offload_source_media_job_to_worker(job, e)
                        if route_retryable
                        else False
                    )
                    if (
                        route_retryable
                        and not offloaded
                        and schedule_source_job_retry_later(job, e)
                    ):
                        should_cleanup_on_fail = True
                        continue
                    fallback_status = "worker_fallback_queued" if offloaded else "failed"
                    record_download_job(job, fallback_status, e)
                    record_total_job(job, fallback_status, e)
                    record_sync_item(job, fallback_status, e)
                    if not offloaded:
                        await update_manual_link_status(job, f"Download failed:\n{err_msg[:500]}")
                    for m in messages:
                        remove_processing_keys(m.chat.id, m)
                    should_cleanup_on_fail = True
            else:
                record_download_job(job, "fallback_queued", e)
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                should_cleanup_on_fail = True
        finally:
            if SHUTDOWN_REQUESTED:
                should_cleanup_on_fail = False
            if should_cleanup_on_fail:
                defer_download_cleanup(files_to_cleanup, "download job failure cleanup")
            channel_download_queue.task_done()
            clear_worker_job(worker_name)


async def upload_worker_loop(worker_id):
    global auto_count
    while True:
        job = await upload_queue.get()
        observe_queue_wait(job, "upload")
        worker_name = f"UP W{worker_id}"
        mark_worker_job(worker_name, job)
        attempt = job.get("attempt", 1)
        max_attempts = SOURCE_JOB_MAX_RETRIES if pressure_managed_source(job.get("source", "")) else MAX_RETRIES
        job_type = job["type"]
        messages = job["messages"]
        files = job["files"]
        ch_name = job["ch_name"]
        original_files = set(files)
        generated_files = set()
        should_cleanup = True

        try:
            intent_recovery = await recover_delivery_intents_after_restart(job.get("job_id"))
            touch_worker_job(worker_name, job)
            if intent_recovery.get("unresolved") and intent_recovery.get("retry_after", 0) > 0:
                retry_after = int(intent_recovery["retry_after"])
                record_upload_job(
                    job,
                    "retry",
                    f"ambiguous Telegram delivery confirmation grace {retry_after}s",
                )
                scheduled = schedule_queue_retry(
                    "upload",
                    job,
                    retry_after,
                    "ambiguous Telegram delivery confirmation grace",
                )
                should_cleanup = not scheduled
                if not scheduled:
                    record_upload_job(job, "retry_admission_failed", "delivery intent grace")
                continue
            record_upload_job(job, "uploading")
            record_total_job(job, "uploading")
            log_event(f"[UP W{worker_id}] Uploading {job_type} for {ch_name} attempt {attempt}")
            if V21_ENGINE is not None:
                V21_ENGINE.upload_dispatcher.route(job=job, worker_id=worker_name)
            await update_manual_link_status(
                job,
                f"Telegram media uploading...\nAttempt: {attempt}\nItems: {len(files)}",
            )

            if job.get("force_upload"):
                kept = [(m, f) for m, f in zip(messages, files)]
            else:
                kept = []
                for m, f in zip(messages, files):
                    if not await known_duplicate_uid_async(get_media_uid(m)):
                        kept.append((m, f))
                    await asyncio.sleep(0)
            if not kept:
                record_upload_job(job, "skipped_duplicate")
                record_total_job(job, "skipped_duplicate")
                record_sync_item(job, "skipped_duplicate")
                source_brain_record_messages(messages, "duplicate", amount=len(messages), title=ch_name)
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                await update_manual_link_status(
                    job,
                    "Already uploaded or duplicate media. Skipped.\nTip: set ROYELLS_TELEGRAM_LINK_FORCE_UPLOAD=1 to force manual link repost.",
                )
                continue

            messages = [x[0] for x in kept]
            files = [x[1] for x in kept]
            if job_type == "album" and len(messages) < 2:
                job_type = "single"
                log_event(
                    f"[UP W{worker_id}] Album for {ch_name} has one non-duplicate item after "
                    "recheck; using terminal single-item fallback."
                )
            if job_type != "album" and len(messages) == 1:
                job_type = "single"

            for message, f in zip(messages, files):
                if not os.path.exists(f) or os.path.getsize(f) == 0:
                    metric_increment("zero_byte_media")
                    raise Exception("file missing or 0 bytes before upload")
                if not media_path_is_complete_enough(message, f):
                    raise Exception("incomplete download before upload")

            touch_worker_job(worker_name, job)
            prepared_items, new_generated_files = await asyncio.wait_for(
                prepare_source_upload_items(messages, files, worker_id, ch_name),
                timeout=max(60, UPLOAD_PREPARE_TIMEOUT_SECONDS),
            )
            touch_worker_job(worker_name, job)
            generated_files.update(new_generated_files)
            if not prepared_items:
                raise Exception("invalid media: no Telegram-ready media after source preparation")

            if job_type == "album" and len(prepared_items) < 2:
                job_type = "single"
                log_event(
                    f"[UP W{worker_id}] Album for {ch_name} left one Telegram-ready item; "
                    "using terminal single-item fallback."
                )

            if job_type != "album" and len(prepared_items) == 1:
                job_type = "single"

            sent_pairs = []
            persisted_source_ids = set(job.get("_persisted_source_ids", set()))
            if job_type == "single":
                m, fp = prepared_items[0]
                touch_worker_job(worker_name, job)
                async with worker_media_rpc_heartbeat(
                    worker_name,
                    job,
                    "send single media",
                ):
                    sent_message = await send_prepared_source_single(
                        m,
                        fp,
                        protect_content=True,
                        job=job,
                        ch_name=ch_name,
                        operation="single_upload",
                    )
                sent_pairs.append((m, sent_message))
                touch_worker_job(worker_name, job)
            elif job_type == "album":
                for chunk in split_source_album_chunks(prepared_items):
                    touch_worker_job(worker_name, job)
                    async with worker_media_rpc_heartbeat(
                        worker_name,
                        job,
                        f"send album chunk ({len(chunk)} item(s))",
                    ):
                        chunk_pairs = await send_source_album_chunk_resilient(
                            chunk,
                            worker_id,
                            ch_name,
                            job=job,
                        )
                    chunk_pairs = [(m, sent) for m, sent in chunk_pairs if sent]
                    persisted_source_ids.update(job.get("_persisted_source_ids", set()))
                    terminal_failures = set(job.get("_album_terminal_failures", set()))
                    missing_ids = {
                        f"{m.chat.id}:{m.id}"
                        for m, _fp in chunk
                        if f"{m.chat.id}:{m.id}" not in {
                            f"{sent_message.chat.id}:{sent_message.id}"
                            for sent_message, _sent in chunk_pairs
                        }
                    }
                    if len(chunk_pairs) != len(chunk) and not missing_ids.issubset(terminal_failures):
                        raise RuntimeError(
                            f"grouped album chunk returned {len(chunk_pairs)}/{len(chunk)} successful items"
                        )
                    unpersisted_chunk_pairs = [
                        (m, sent_msg)
                        for m, sent_msg in chunk_pairs
                        if f"{m.chat.id}:{m.id}" not in persisted_source_ids
                    ]
                    if unpersisted_chunk_pairs:
                        await mark_posted_many_queued(
                            [
                                (m.chat.id, m, ch_name, sent_msg, job["job_id"])
                                for m, sent_msg in unpersisted_chunk_pairs
                            ]
                        )
                        persisted_source_ids.update(
                            f"{m.chat.id}:{m.id}" for m, _ in unpersisted_chunk_pairs
                        )
                    if missing_ids:
                        log_event(
                            f"[UP W{worker_id}] Album fallback completed with "
                            f"{len(chunk_pairs)}/{len(chunk)} valid item(s) for {ch_name}; "
                            f"{len(missing_ids)} deterministic invalid item(s) quarantined."
                        )
                    sent_pairs.extend(chunk_pairs)
                    await asyncio.sleep(1)

            sent_source_ids = {f"{m.chat.id}:{m.id}" for m, sent in sent_pairs if sent}
            for m, _ in prepared_items:
                if f"{m.chat.id}:{m.id}" not in sent_source_ids:
                    remove_processing_keys(m.chat.id, m)
            sent_pairs = [(m, sent) for m, sent in sent_pairs if sent]
            if not sent_pairs:
                terminal_failures = set(job.get("_album_terminal_failures", set()))
                if terminal_failures:
                    reason = (
                        f"all {len(terminal_failures)} album item(s) were rejected as "
                        "deterministic invalid media"
                    )
                    record_upload_job(job, "skipped_dead_media", reason)
                    record_total_job(job, "skipped_dead_media", reason)
                    record_sync_item(job, "skipped_dead_media", reason)
                    await update_manual_link_status(job, f"Upload skipped:\n{reason}")
                    continue
                raise Exception("invalid media: all prepared media were rejected by Telegram")

            uploaded_messages = [m for m, _ in sent_pairs]
            files = [fp for _, fp in prepared_items]
            auto_count += len(uploaded_messages)
            diagnostic_stats["uploads"] = int(diagnostic_stats.get("uploads") or 0) + len(uploaded_messages)
            unpersisted_pairs = [
                (m, sent_msg)
                for m, sent_msg in sent_pairs
                if f"{m.chat.id}:{m.id}" not in persisted_source_ids
            ]
            if unpersisted_pairs:
                await mark_posted_many_queued(
                    [
                        (m.chat.id, m, ch_name, sent_msg, job["job_id"])
                        for m, sent_msg in unpersisted_pairs
                    ]
                )
            await complete_delivery_intents_for_job(job["job_id"])

            with state_mutex:
                STATE["total_auto_upload"]["total_uploaded"] = STATE["total_auto_upload"].get("total_uploaded", 0) + len(uploaded_messages)
                save_state("total_auto_upload")
            terminal_failure_count = len(set(job.get("_album_terminal_failures", set())))
            completion_status = "uploaded_partial" if terminal_failure_count else "uploaded"
            completion_error = (
                f"{terminal_failure_count} deterministic invalid album item(s) skipped"
                if terminal_failure_count
                else None
            )
            record_upload_job(
                {**job, "messages": uploaded_messages, "files": files, "type": job_type},
                completion_status,
                completion_error,
            )
            record_download_job(
                {**job, "messages": uploaded_messages, "type": job_type},
                completion_status,
                completion_error,
                files=files,
            )
            record_total_job(
                {**job, "messages": uploaded_messages, "type": job_type},
                completion_status,
                completion_error,
            )
            record_sync_item(
                {**job, "messages": uploaded_messages, "type": job_type},
                completion_status,
                completion_error,
            )
            source_brain_record_messages(uploaded_messages, "uploaded", amount=len(uploaded_messages), title=ch_name)
            log_event(
                f"[UP W{worker_id}] Uploaded successfully ({len(uploaded_messages)} item(s)"
                + (f", {terminal_failure_count} invalid skipped)" if terminal_failure_count else ")")
            )
            await update_manual_link_status(
                job,
                f"Telegram media uploaded successfully.\nItems: {len(uploaded_messages)}"
                + (
                    f"\nInvalid album items skipped: {terminal_failure_count}"
                    if terminal_failure_count
                    else ""
                ),
            )
            await asyncio.sleep(POST_DELAY)

        except asyncio.CancelledError as e:
            if SHUTDOWN_REQUESTED:
                raise
            reason = RuntimeError(
                f"upload worker job stalled for more than {WORKER_STALL_SECONDS}s"
            )
            record_upload_job(job, "retry", reason)
            record_total_job(job, "queued_upload", reason)
            scheduled = schedule_queue_retry("upload", job, 30, reason)
            should_cleanup = not scheduled
            if scheduled:
                metric_increment("recovered_workers")
                log_event(
                    f"[UP W{worker_id}] Stalled job {job.get('job_id')} cancelled and "
                    "requeued; delivery intent recovery will verify target before retry."
                )
            else:
                record_upload_job(job, "retry_admission_failed", reason)
            with contextlib.suppress(Exception):
                await update_manual_link_status(
                    job,
                    "Stalled upload cancelled safely. Job retained for automatic retry.",
                )

        except FloodWait as e:
            flood_role = getattr(e, "_royells_client_role", "userbot")
            note_global_flood_wait(e, flood_role)
            delay = max(1.0, telegram_flood_gate_remaining_seconds(flood_role))
            scheduled = False
            if attempt < max_attempts:
                job["attempt"] = attempt + 1
                record_upload_job(job, "retry", e)
                await update_manual_link_status(
                    job,
                    f"Upload client paused for FloodWait. Retrying automatically.\n"
                    f"Attempt: {attempt + 1}/{max_attempts}",
                )
                scheduled = schedule_queue_retry("upload", job, delay, e)
                should_cleanup = not scheduled
                if not scheduled:
                    record_upload_job(job, "retry_admission_failed", e)
                    for message in messages:
                        remove_processing_keys(message.chat.id, message)
            else:
                offloaded = await offload_source_media_job_to_worker(job, e)
                scheduled = bool(
                    offloaded
                    or (not offloaded and schedule_source_job_retry_later(job, e))
                )
                if scheduled:
                    should_cleanup = True
                    if offloaded:
                        record_upload_job(job, "worker_fallback_queued", e)
                        record_total_job(job, "worker_fallback_queued", e)
                        record_sync_item(job, "worker_fallback_queued", e)
                else:
                    record_upload_job(job, "failed", e)
                    record_total_job(job, "failed", e)
                    record_sync_item(job, "failed", e)
                    await update_manual_link_status(job, f"Upload failed:\n{str(e)[:500]}")
                    for m in messages:
                        remove_processing_keys(m.chat.id, m)
                    should_cleanup = True
            record_production_incident(
                "FloodWait",
                "warning",
                "upload",
                job=job,
                worker_name=worker_name,
                queue_name="upload",
                exception=e,
                recovery={
                    "attempted": True,
                    "retry_scheduled": bool(scheduled),
                    "failed": not bool(scheduled),
                },
                rate_limit_key=f"upload_floodwait:{job.get('job_id')}:{attempt}",
            )

        except UploadSessionRecoveryError as e:
            retry_job, delay, deferred_retry = plan_fresh_download_retry(
                job,
                "FILE_PART_X_MISSING",
                max(10, min(120, 20 * max(1, attempt))),
            )
            manual_deferred_retry = bool(
                deferred_retry
                and retry_job
                and str(retry_job.get("source") or "") == "telegram_link"
            )
            source_deferred_retry = bool(
                deferred_retry
                and retry_job
                and retry_job.get("_source_fresh_download_deferred_due_at")
            )
            scheduled = False
            if retry_job is not None:
                retry_job["_upload_session_corrupted"] = True
                retry_job["_upload_session_corrupted_at"] = now_iso()
                record_upload_job(job, "retry_download", e)
                record_download_job(
                    retry_job,
                    "retry_later" if deferred_retry else "retry",
                    e,
                    files=[],
                )
                record_total_job(retry_job, "queued_download", e)
                record_sync_item(retry_job, "retry_later" if deferred_retry else "retry", e)
                scheduled = schedule_queue_retry(
                    "download",
                    retry_job,
                    delay,
                    (
                        "FILE_PART_X_MISSING; manual delayed fresh-download retry"
                        if manual_deferred_retry
                        else "FILE_PART_X_MISSING; source-owned delayed fresh-download retry"
                        if source_deferred_retry
                        else "FILE_PART_X_MISSING; fresh download required"
                    ),
                )
            record_production_incident(
                "FILE_PART_X_MISSING",
                "error",
                "upload",
                job=job,
                worker_name=worker_name,
                queue_name="upload",
                exception=e,
                recovery={
                    "attempted": True,
                    "retry_scheduled": bool(scheduled),
                    "retained_durably": retry_job is not None,
                    "failed": retry_job is None,
                },
                rate_limit_key=f"upload_session:{job.get('job_id')}:{attempt}",
            )
            should_cleanup = True
            if scheduled:
                retry_label = (
                    f"Delayed fresh download retry retained ({max(1, delay // 60)} minutes)."
                    if manual_deferred_retry
                    else f"Durable source fresh-download retry retained ({max(1, delay // 60)} minutes)."
                    if source_deferred_retry
                    else "Fresh download retry scheduled."
                )
                await update_manual_link_status(
                    job,
                    f"Telegram upload session was corrupted. {retry_label}",
                )
            elif retry_job is not None:
                # Never release either a manual request or a channel post just
                # because the in-memory retry scheduler is unavailable.  The
                # durable descriptor, message metadata, and processing keys are
                # sufficient for queue healing/restart recovery to resume it.
                record_upload_job(job, "retry_download", e)
                retain_fresh_download_retry_for_recovery(retry_job, e)
                await update_manual_link_status(
                    job,
                    "Fresh-download recovery is retained durably and waiting for retry admission.",
                )
            else:
                record_upload_job(job, "failed_recoverable", e)
                record_total_job(job, "failed_recoverable", e)
                record_sync_item(job, "failed_recoverable", e)
                for message in messages:
                    remove_processing_keys(message.chat.id, message)
                await update_manual_link_status(
                    job,
                    "Upload-session recovery could not build a durable source descriptor.",
                )

        except Exception as e:
            err_str = str(e)
            err_log = format_exception_for_log(e)
            log_event(f"[UP ERROR W{worker_id}] {err_log}")
            lower_error = err_log.lower()
            if "media_empty" in lower_error or "media empty" in lower_error:
                incident_name = "MEDIA_EMPTY"
            elif "0 bytes" in lower_error or "0-byte" in lower_error:
                incident_name = "Zero-byte Media"
            else:
                incident_name = "Upload Failure"
            record_production_incident(
                incident_name,
                "error",
                "upload",
                job=job,
                worker_name=worker_name,
                queue_name="upload",
                exception=e,
                recovery={
                    "attempted": False,
                    "retry_planned": attempt < max_attempts,
                },
                rate_limit_key=f"upload_error:{job.get('job_id')}:{type(e).__name__}:{attempt}",
            )
            needs_fresh_download = (
                isinstance(e, MediaArtifactRefreshRequired)
                or is_upload_source_file_missing_error(e)
                or is_invalid_media_upload_error(e)
                or "source media preparation" in lower_error
                or "needs fresh download" in lower_error
                or "requires fresh download" in lower_error
            )
            if needs_fresh_download:
                retry_job, delay, deferred_retry = plan_fresh_download_retry(
                    job,
                    incident_name,
                    5,
                )
                manual_deferred_retry = bool(
                    deferred_retry
                    and retry_job
                    and str(retry_job.get("source") or "") == "telegram_link"
                )
                source_deferred_retry = bool(
                    deferred_retry
                    and retry_job
                    and retry_job.get("_source_fresh_download_deferred_due_at")
                )
                scheduled = False
                if retry_job is not None:
                    record_upload_job(job, "retry_download", e)
                    record_download_job(
                        retry_job,
                        "retry_later" if deferred_retry else "retry",
                        e,
                        files=[],
                    )
                    record_total_job(retry_job, "queued_download", e)
                    record_sync_item(retry_job, "retry_later" if deferred_retry else "retry", e)
                    scheduled = schedule_queue_retry(
                        "download",
                        retry_job,
                        delay,
                        (
                            f"{incident_name}; manual delayed fresh-download retry"
                            if manual_deferred_retry
                            else f"{incident_name}; source-owned delayed fresh-download retry"
                            if source_deferred_retry
                            else f"{incident_name}; fresh download required"
                        ),
                    )
                record_production_incident(
                    incident_name,
                    "error",
                    "upload",
                    job=job,
                    worker_name=worker_name,
                    queue_name="upload",
                    exception=e,
                    recovery={
                        "attempted": True,
                        "retry_scheduled": bool(scheduled),
                        "retained_durably": retry_job is not None,
                        "failed": retry_job is None,
                    },
                    rate_limit_key=(
                        f"upload_recovery_outcome:{job.get('job_id')}:"
                        f"{type(e).__name__}:{attempt}"
                    ),
                )
                should_cleanup = True
                if scheduled:
                    retry_label = (
                        f"It is retained for a fresh download retry in {max(1, delay // 60)} minutes."
                        if manual_deferred_retry
                        else f"A durable source fresh-download retry is retained for {max(1, delay // 60)} minutes."
                        if source_deferred_retry
                        else "Fresh download retry scheduled."
                    )
                    await update_manual_link_status(
                        job,
                        f"Media upload rejected the local artifact. {retry_label}",
                    )
                elif retry_job is not None:
                    # A source cursor can have advanced too, so both manual and
                    # source-owned jobs remain recoverable when admission fails.
                    record_upload_job(job, "retry_download", e)
                    retain_fresh_download_retry_for_recovery(retry_job, e)
                    await update_manual_link_status(
                        job,
                        "Fresh-download recovery is retained durably and waiting for retry admission.",
                    )
                else:
                    record_upload_job(job, "failed_recoverable", e)
                    record_total_job(job, "failed_recoverable", e)
                    record_sync_item(job, "failed_recoverable", e)
                    for message in messages:
                        remove_processing_keys(message.chat.id, message)
                    await update_manual_link_status(
                        job,
                        "Fresh-download recovery could not build a durable source descriptor.",
                    )
                continue
            if should_reconnect_telegram_error(e):
                schedule_userbot_reconnect(f"upload worker {worker_name}: {e}")
                delay = max(30, min(180, TELEGRAM_RECONNECT_COOLDOWN_SECONDS))
                record_upload_job(job, "retry", f"telegram transport recovery: {err_log[:180]}")
                record_total_job(job, "queued_upload", e)
                await update_manual_link_status(
                    job,
                    "Telegram transport is recovering. Upload job is retained for retry.",
                )
                scheduled = schedule_queue_retry("upload", job, delay, e)
                should_cleanup = not scheduled
                if not scheduled:
                    record_upload_job(job, "retry_admission_failed", e)
                continue
            if should_skip_dead_media_now(e, attempt):
                record_upload_job(job, "skipped_dead_media", e)
                record_total_job(job, "skipped_dead_media", e)
                record_sync_item(job, "skipped_dead_media", e)
                remember_dead_media(messages, e, force_dead=True)
                source_brain_record_messages(messages, "dead", amount=len(messages), title=ch_name, reason=e)
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                await update_manual_link_status(job, f"Upload skipped as invalid/dead media:\n{err_log[:500]}")
                should_cleanup = True
                continue
            if is_invalid_media_upload_error(e) or "invalid" in err_str.lower():
                offloaded = await offload_source_media_job_to_worker(job, e)
                if not offloaded and schedule_source_job_retry_later(job, e):
                    should_cleanup = True
                    continue
                fallback_status = "worker_fallback_queued" if offloaded else "failed_invalid_media"
                record_upload_job(job, fallback_status, e)
                record_total_job(job, fallback_status, e)
                record_sync_item(job, fallback_status, e)
                if not offloaded:
                    await update_manual_link_status(job, f"Upload failed invalid media:\n{err_log[:500]}")
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                should_cleanup = True
            elif attempt < max_attempts:
                await asyncio.sleep(5)
                job["attempt"] = attempt + 1
                record_upload_job(job, "retry", e)
                await update_manual_link_status(job, f"Upload retry scheduled...\nAttempt: {attempt + 1}/{max_attempts}\nReason: {err_log[:240]}")
                scheduled = schedule_queue_retry("upload", job, 5, e)
                should_cleanup = not scheduled
                if not scheduled:
                    record_upload_job(job, "retry_admission_failed", e)
            else:
                offloaded = await offload_source_media_job_to_worker(job, e)
                if not offloaded and schedule_source_job_retry_later(job, e):
                    should_cleanup = True
                    continue
                fallback_status = "worker_fallback_queued" if offloaded else "failed"
                record_upload_job(job, fallback_status, e)
                record_total_job(job, fallback_status, e)
                record_sync_item(job, fallback_status, e)
                if not offloaded:
                    await update_manual_link_status(job, f"Upload failed:\n{err_log[:500]}")
                for m in messages:
                    remove_processing_keys(m.chat.id, m)
                should_cleanup = True

        finally:
            if SHUTDOWN_REQUESTED:
                should_cleanup = False
            if should_cleanup:
                untrack_download_files(original_files | generated_files | set(files))
                cleanup(*(original_files | generated_files | set(files)))
            else:
                untrack_download_files(generated_files)
                cleanup(*generated_files)
            upload_queue.task_done()
            clear_worker_job(worker_name)


async def process_telegram_link(job):
    url = canonical_link_url(job.get("url", ""), "telegram")
    status_msg = job.get("status_msg")
    is_fallback = job.get("is_fallback", False)
    requester_id = int(job.get("requester_id") or OWNER_ID or 0)
    force_upload = (
        bool(job.get("force_upload"))
        or TELEGRAM_LINK_FORCE_UPLOAD_FOR_ALL
        or (TELEGRAM_LINK_FORCE_UPLOAD and requester_id == OWNER_ID)
    )

    if status_msg:
        await safe_edit(status_msg, f"Telegram link detected.\nFetching media: {url}")

    chat_id, msg_id = parse_telegram_message_link(url)
    if chat_id in (None, "") or not msg_id:
        if status_msg:
            await safe_edit(status_msg, "Invalid Telegram post link. Send a direct Telegram media post link.")
        return

    msg = None
    source_peer = chat_id

    for attempt in range(MAX_RETRIES):
        try:
            source_peer = await resolve_source_peer_for_access(chat_id, "telegram_link", force_refresh=attempt > 0)
            msg = await tg_call("telegram link get_messages", userbot.get_messages, source_peer, msg_id)
            if msg and not msg.empty:
                break
            raise Exception("message not found or empty")
        except Exception as e:
            err_str = str(e).lower()
            if any(x in err_str for x in ["110", "timeout", "network"]) and attempt < MAX_RETRIES - 1:
                log_event(f"Network timeout fetching link. Retry {attempt + 1}/{MAX_RETRIES}")
                await asyncio.sleep(5)
                continue
            raise Exception(f"Failed after {MAX_RETRIES} attempts: {e}")

    if not msg or msg.empty:
        if status_msg:
            await safe_edit(status_msg, "Message not found. Ensure the userbot account can open that Telegram post.")
        return

    if msg.media_group_id:
        messages = await tg_call("telegram link get_media_group", userbot.get_media_group, source_peer, msg.id)
        job_type = "album"
    else:
        messages = [msg]
        job_type = "single"

    filtered = []
    for m in messages:
        if not is_valid_media(m):
            continue
        if force_upload:
            uid = get_media_uid(m)
            old_hash = make_old_hash(m.chat.id, m.id)
            if uid in processing_cache or old_hash in processing_cache:
                continue
            add_processing_keys(m.chat.id, m)
            filtered.append(m)
        elif not await check_and_mark_processing_async(m.chat.id, m):
            filtered.append(m)

    if not filtered:
        if status_msg:
            duplicate_note = "This Telegram media is already processing." if force_upload else "Already uploaded or duplicate media. Skipped."
            await safe_edit(status_msg, duplicate_note)
        return

    queued = await enqueue_media_job(
        job_type,
        filtered,
        msg.chat.title or str(chat_id),
        attempt=1,
        is_fallback=is_fallback,
        source="telegram_link",
        status_msg=status_msg,
        force_upload=force_upload,
        manual_link_url=url,
    )
    if status_msg:
        if queued:
            await safe_edit(
                status_msg,
                f"Telegram media added to downloader queue.\nItems: {len(filtered)}\nMode: {'force upload' if force_upload else 'duplicate protected'}",
            )
        else:
            await safe_edit(status_msg, "Telegram media could not be queued. Check logs for details.")


# External platform downloaders were intentionally removed.
# This main bot now accepts Telegram links and source-channel media only.

def validate_photo_file_sync(path):
    if not path or not os.path.exists(path) or os.path.getsize(path) <= 512:
        return False
    if Image is None:
        return True
    try:
        with Image.open(path) as image:
            image.verify()
        with Image.open(path) as image:
            width, height = image.size
        return width > 0 and height > 0
    except Exception:
        return False


async def ensure_photo_for_telegram(path):
    log_event_rate_limited(
        "source_photo_conversion_disabled",
        "Source photo conversion is disabled; uploading original Telegram media file.",
        interval_seconds=3600,
    )
    return path


async def link_process_worker_loop(worker_id):
    while True:
        await wait_while_session_invalid(f"LINK W{worker_id}")
        job = await link_process_queue.get()
        observe_queue_wait(job, "link")
        worker_name = f"LINK W{worker_id}"
        job.setdefault(
            "job_id",
            stable_uid(
                "link",
                job.get("url"),
                job.get("requester_id"),
                job.get("status_message_id"),
            ),
        )
        job.setdefault("source", "link")
        job.setdefault("ch_name", job.get("platform", "link"))
        job["attempt"] = int(job.get("retries") or 0) + 1
        mark_worker_job(worker_name, job)
        try:
            url = job.get("url", "")
            platform = detect_link_platform(url)
            log_event(f"[LINK W{worker_id}] Processing link: {url}")
            if platform == "telegram":
                await process_telegram_link(job)
            else:
                log_event(f"[LINK W{worker_id}] Unsupported link format: {url}")
                if job.get("status_msg"):
                    await safe_edit(job["status_msg"], "Unsupported link. Telegram links only.")
        except Exception as e:
            err_log = format_exception_for_log(e)
            log_event(f"[LINK ERROR W{worker_id}] {err_log}")
            retries = int(job.get("retries") or 0)
            if retries < MAX_RETRIES:
                retry_job = {**job, "retries": retries + 1}
                delay = min(60, 5 * (retries + 1))
                scheduled = schedule_queue_retry(
                    "link",
                    retry_job,
                    delay,
                    e,
                )
                if scheduled:
                    await update_manual_link_status(
                        job,
                        f"Telegram link retry scheduled.\n"
                        f"Attempt: {retries + 2}/{MAX_RETRIES + 1}\n"
                        f"Reason: {err_log[:300]}",
                    )
                else:
                    await update_manual_link_status(
                        job,
                        f"Telegram link retry state retained for recovery:\n{err_log[:500]}",
                    )
            else:
                await update_manual_link_status(job, f"Telegram link processing failed:\n{err_log[:500]}")
        finally:
            link_process_queue.task_done()
            clear_worker_job(worker_name)


async def button_worker_loop(worker_id):
    while True:
        job = await button_queue.get()
        observe_queue_wait(job, "button")
        try:
            if job["type"] == "admin":
                await actual_admin_callback_logic(job["client"], job["query"])
            elif job["type"] == "public":
                await actual_public_callback_logic(job["client"], job["query"])
        except Exception as e:
            tb = traceback.format_exc()
            diagnostic_increment_error(e, context=f"BUTTON W{worker_id} {job.get('type', '')}", traceback_text=tb)
            log_event(f"[BUTTON ERROR W{worker_id}] {format_exception_for_log(e)}")
            logging.error("Button worker %s failed\n%s", worker_id, tb)
        finally:
            pending_key = str(job.get("_button_pending_key") or "")
            if pending_key:
                with BUTTON_PENDING_LOCK:
                    BUTTON_PENDING_KEYS.discard(pending_key)
            button_queue.task_done()


async def _auto_flush_album(group_key, ch_name, delay=None):
    try:
        await asyncio.sleep(ALBUM_WAIT if delay is None else max(0.0, float(delay)))
        async with auto_album_lock:
            msgs = auto_album_buffer.pop(group_key, [])
            auto_album_deadlines.pop(group_key, None)
        valid_msgs = []
        if msgs:
            first = msgs[0]
            try:
                album_msgs = await tg_call("auto monitor get_media_group", userbot.get_media_group, first.chat.id, first.id)
                valid_msgs = [m for m in album_msgs if is_valid_media(m)]
                buffered_ids = {getattr(m, "id", None) for m in msgs}
                for m in valid_msgs:
                    if getattr(m, "id", None) not in buffered_ids:
                        add_processing_keys(m.chat.id, m)
            except Exception as e:
                log_event(f"Auto monitor full album fetch failed for {group_key}: {str(e)[:140]}")
                valid_msgs = [m for m in msgs if is_valid_media(m)]
        if valid_msgs:
            await enqueue_media_job("album", valid_msgs, ch_name, source="auto_monitor")
        async with auto_album_lock:
            auto_album_tasks.pop(group_key, None)
    finally:
        async with auto_album_lock:
            auto_album_tasks.pop(group_key, None)
            auto_album_buffer.pop(group_key, None)
            auto_album_deadlines.pop(group_key, None)
        mark_runtime_checkpoint_dirty("album flush complete")

@userbot.on_message(filters.channel)
async def auto_monitor(client, message):
    try:
        cid = message.chat.id
        cusr = f"@{message.chat.username}" if message.chat.username else ""
        if is_reserved_source_channel(cid):
            return
        active_channels = set(active_source_channels())
        if cid not in active_channels and cusr not in active_channels:
            return
        schedule_source_link_discovery(message, "auto_monitor")
        if not is_valid_media(message):
            return
        if await check_and_mark_processing_async(cid, message):
            return

        ch_name = message.chat.title or str(cid)
        record_channel(cid, title=ch_name, status="active", action="seen")

        if message.media_group_id:
            group_key = f"{cid}:{message.media_group_id}"
            async with auto_album_lock:
                auto_album_buffer[group_key].append(message)
                auto_album_deadlines.setdefault(group_key, time.time() + ALBUM_WAIT)
                if group_key not in auto_album_tasks:
                    auto_album_tasks[group_key] = asyncio.create_task(_auto_flush_album(group_key, ch_name))
                mark_runtime_checkpoint_dirty("album buffered")
            return

        await enqueue_media_job("single", [message], ch_name, source="auto_monitor")
    except Exception as e:
        await handle_ai_error(e, "auto_monitor")


async def target_deleted_handler(client, messages):
    try:
        if not isinstance(messages, list):
            messages = [messages]
        target_ids = []
        for msg in messages:
            chat_id = getattr(getattr(msg, "chat", None), "id", None)
            if chat_id in (None, TARGET_CHAT_ID):
                target_ids.append(msg.id)
        removed = remove_clean_duplicate_by_target_ids(target_ids)
        if removed:
            log_event(f"Removed {len(removed)} duplicate ledger item(s) after target delete event.")
    except Exception as e:
        log_event(f"Delete event handler error: {e}")


if hasattr(userbot, "on_deleted_messages"):
    userbot.on_deleted_messages()(target_deleted_handler)


async def run_sync_for_channel(
    channel_id,
    limit=1000,
    sync_run_id=None,
    history_limit=None,
    source="sync",
    return_status=False,
):
    synced = 0
    processed_albums = set()
    ch = normalize_channel_id(channel_id)
    last_title = ""
    had_sync_error = False

    def result(success):
        value = (synced, bool(success)) if return_status else synced
        return value

    try:
        await wait_for_telegram_client("sync history")
        if not channel_is_active_record(ch):
            return result(True)
        source_peer = await resolve_source_peer_for_access(ch, "sync")
        ch = normalize_channel_id(source_peer)
        media_limit = int(limit or 0)
        unlimited_media = media_limit <= 0
        if history_limit is None:
            history_limit = 0 if unlimited_media else (media_limit * 5 if media_limit <= STARTUP_SCAN_LIMIT else media_limit)
        media_units_seen = 0
        history_iter = userbot.get_chat_history(source_peer, limit=history_limit)
        async for msg in history_iter:
            await asyncio.sleep(0)
            last_title = getattr(getattr(msg, "chat", None), "title", "") or last_title
            schedule_source_link_discovery(msg, "sync")
            if not is_valid_media(msg):
                continue

            if msg.media_group_id:
                if msg.media_group_id in processed_albums:
                    continue
                processed_albums.add(msg.media_group_id)
                media_units_seen += 1
                if not unlimited_media and media_units_seen > media_limit:
                    break
                try:
                    album_msgs = await fetch_scan_media_group("sync get_media_group", msg)
                    valid_album = []
                    for m in album_msgs:
                        if is_valid_media(m) and not await check_and_mark_processing_async(m.chat.id, m):
                            valid_album.append(m)
                    if valid_album:
                        ok = await enqueue_media_job(
                            "album",
                            valid_album,
                            msg.chat.title or str(ch),
                            source=source,
                            sync_run_id=sync_run_id,
                        )
                        synced += 1 if ok else 0
                except Exception as e:
                    had_sync_error = True
                    status = classify_channel_error(e)
                    if status:
                        if await try_refresh_channel_peer(ch, e):
                            return result(False)
                        quarantine_channel(ch, reason=str(e), status=status)
                        return result(False)
                    if is_temporary_network_error(e):
                        register_guard_temp_error(ch, e)
                    else:
                        await handle_ai_error(e, "run_sync_for_channel album")
                continue

            media_units_seen += 1
            if not unlimited_media and media_units_seen > media_limit:
                break
            if not await check_and_mark_processing_async(msg.chat.id, msg):
                ok = await enqueue_media_job(
                    "single",
                    [msg],
                    msg.chat.title or str(ch),
                    source=source,
                    sync_run_id=sync_run_id,
                )
                synced += 1 if ok else 0

    except Exception as e:
        had_sync_error = True
        if is_session_auth_error(e):
            mark_session_auth_invalid(e)
            with contextlib.suppress(Exception):
                asyncio.create_task(notify_session_problem(e))
            return result(False)
        status = classify_channel_error(e)
        if status:
            if await try_refresh_channel_peer(channel_id, e):
                return result(False)
            quarantine_channel(channel_id, reason=str(e), status=status)
        elif is_temporary_network_error(e):
            register_guard_temp_error(channel_id, e)
        else:
            await handle_ai_error(e, "run_sync_for_channel")
    if not had_sync_error:
        source_brain_scan_result(ch, synced, title=last_title)
    return result(not had_sync_error)


async def check_single_channel_health(channel_id):
    ch = normalize_channel_id(channel_id)
    try:
        source_peer = await resolve_source_peer_for_access(ch, "health")
        chat = await tg_call("health get_chat", userbot.get_chat, source_peer)
        title = getattr(chat, "title", "") or getattr(chat, "first_name", "") or str(ch)
        record_channel(getattr(chat, "id", ch), title=title, status="active", action="health_ok", reason="")
        return True, title, ""
    except Exception as e:
        status = classify_channel_error(e)
        if status:
            if await try_refresh_channel_peer(ch, e):
                return None, str(ch), str(e)
            result_status = quarantine_channel(ch, reason=str(e), status=status)
            if result_status == "expired_or_deleted":
                return False, str(ch), str(e)
            return None, str(ch), str(e)
        if is_temporary_network_error(e):
            register_guard_temp_error(ch, e)
        return None, str(ch), str(e)


async def check_all_channels_health(status_msg=None):
    channels = active_source_channels()
    ok_count, issue_count, temp_count = 0, 0, 0
    for ch in channels:
        try:
            result, title, reason = await asyncio.wait_for(
                check_single_channel_health(ch),
                timeout=max(5, CHANNEL_HEALTH_TIMEOUT_SECONDS),
            )
        except asyncio.TimeoutError:
            result, title, reason = None, str(ch), f"health check timed out after {CHANNEL_HEALTH_TIMEOUT_SECONDS}s"
            register_guard_temp_error(ch, reason)
        if result is True:
            ok_count += 1
        elif result is False:
            issue_count += 1
        else:
            temp_count += 1
        await asyncio.sleep(0.2)
    text = (
        "Channel health check complete.\n"
        f"Active: {ok_count}\n"
        f"Removed/deleted: {issue_count}\n"
        f"Temporary/unchecked: {temp_count}"
    )
    if status_msg:
        await safe_edit(status_msg, text, reply_markup=source_status_keyboard())
    else:
        log_event(text.replace("\n", " | "))
    return ok_count, issue_count, temp_count


def guard_key(channel_id):
    return str(normalize_channel_id(channel_id))


def get_guard_cursor(channel_id):
    key = guard_key(channel_id)
    with state_mutex:
        cursor = STATE["sync_source_manager"].setdefault("cursors", {}).get(key, {})
    return int(cursor.get("last_seen_message_id") or 0)


def legacy_peer_backoff_needs_normalization(cursor, now_ts=None):
    """Identify only peer cooldowns that no current build could have created.

    Current builds cap peer backoff at 30 minutes and persist an update timestamp.
    Old builds wrote six-hour cooldowns and allowed the failure counter to grow into
    the hundreds.  A fresh, timestamped cursor is deliberately left untouched even
    if a human or a future build supplied a longer deadline; that prevents a live
    current retry policy from being reset merely because this process restarted.
    """

    cursor = cursor if isinstance(cursor, dict) else {}
    now_ts = float(now_ts if now_ts is not None else time.time())
    peer_count = max(0, int(cursor.get("peer_invalid_count") or 0))
    peer_until = float(cursor.get("next_check_after") or 0)
    if peer_count > CHANNEL_PEER_INVALID_BACKOFF_MAX_ATTEMPTS:
        # The current writer clamps this field before persistence, so a larger
        # number is conclusive legacy evidence regardless of timestamp.
        return True
    if peer_until <= now_ts + 1800:
        return False
    updated_at = parse_iso_timestamp(cursor.get("peer_invalid_updated_at"))
    if updated_at is None:
        # Older peer cursors had no timestamp; a long deadline is their legacy
        # signature.  Do not inspect generic source/circuit cooldowns here: this
        # helper is invoked only when a peer-invalid field is present.
        return bool(peer_count or cursor.get("peer_invalid_context") or cursor.get("peer_invalid_last_error"))
    try:
        updated_ts = float(updated_at.timestamp())
    except Exception:
        return False
    # A persisted peer backoff only lasts 30 minutes in this build. Give the
    # timestamp a one-hour grace window for clock skew and a just-restarted app,
    # then repair stale long-lived state from pre-cap releases.
    return updated_ts <= now_ts - 3600


def guard_next_check_allowed(channel_id):
    key = guard_key(channel_id)
    migrated_legacy_peer_backoff = False
    with state_mutex:
        cursor = STATE["sync_source_manager"].setdefault("cursors", {}).get(key, {})
        now_ts = time.time()
        peer_count = max(0, int(cursor.get("peer_invalid_count") or 0))
        peer_until = float(cursor.get("next_check_after") or 0)
        # Old builds stored a six-hour (or longer) peer-invalid ban and could
        # multiply it by a historical count in the hundreds.  The peer-specific
        # counter is sufficient evidence even when an old JSON record predates
        # ``peer_invalid_context``; timestamp checks keep a fresh modern cursor
        # from being altered during restart.
        if legacy_peer_backoff_needs_normalization(cursor, now_ts):
            cursor["peer_invalid_count"] = min(
                CHANNEL_PEER_INVALID_BACKOFF_MAX_ATTEMPTS,
                max(1, peer_count),
            )
            cursor["next_check_after"] = min(peer_until, now_ts + 1800)
            cursor["peer_invalid_legacy_migrated_at"] = now_iso()
            save_state("sync_source_manager")
            migrated_legacy_peer_backoff = True
    next_check_after = max(
        float(cursor.get("next_check_after") or 0),
        float(cursor.get("circuit_open_until") or 0),
    )
    if migrated_legacy_peer_backoff:
        log_event_rate_limited(
            f"peer_backoff_migrated:{key}",
            f"Normalized legacy peer retry cooldown for {key}; source remains active.",
            interval_seconds=3600,
        )
    return next_check_after <= time.time()


def source_brain_default(channel_id, title=""):
    return {
        "channel_id": guard_key(channel_id),
        "title": title or "",
        "score": 50,
        "queued": 0,
        "uploaded": 0,
        "duplicates": 0,
        "failed": 0,
        "dead": 0,
        "copy_uploaded": 0,
        "scan_hits": 0,
        "scan_misses": 0,
        "consecutive_failures": 0,
        "silent_streak": 0,
        "next_scan_after": 0,
        "last_event": "",
        "last_error": "",
        "last_checked_at": "",
        "last_activity_at": "",
        "media_profile": brain_media_empty_counts(),
        "semantic_profile": brain_semantic_empty_profile(),
        "updated_at": now_iso(),
    }


def source_brain_clamp_score(value):
    return max(1, min(100, int(value)))


def source_brain_recalculate_score(item):
    queued = int(item.get("queued") or 0)
    uploaded = int(item.get("uploaded") or 0)
    duplicates = int(item.get("duplicates") or 0)
    failed = int(item.get("failed") or 0)
    dead = int(item.get("dead") or 0)
    hits = int(item.get("scan_hits") or 0)
    misses = int(item.get("scan_misses") or 0)
    fail_streak = int(item.get("consecutive_failures") or 0)
    score = 50 + min(25, uploaded * 2 + hits * 3) + min(10, queued)
    score -= min(20, duplicates // 3)
    score -= min(35, failed * 4 + dead * 8 + fail_streak * 6)
    score -= min(20, misses // 2)
    item["score"] = source_brain_clamp_score(score)
    return item["score"]


def source_brain_next_delay(item, queued=0, event="scan"):
    if queued > 0 or event in {"queued", "uploaded", "copy_uploaded"}:
        return SOURCE_BRAIN_MIN_SCAN_DELAY_SECONDS
    if event in {"failed", "dead", "timeout", "access_error"}:
        fail_streak = int(item.get("consecutive_failures") or 0)
        return min(SOURCE_BRAIN_BAD_COOLDOWN_SECONDS, 300 * max(1, fail_streak))
    silent = int(item.get("silent_streak") or 0)
    score = int(item.get("score") or 50)
    multiplier = min(6, max(1, silent))
    if score >= 75:
        multiplier = max(1, multiplier - 1)
    elif score <= 35:
        multiplier += 2
    return min(SOURCE_BRAIN_MAX_SCAN_DELAY_SECONDS, SOURCE_BRAIN_QUIET_BASE_DELAY_SECONDS * multiplier)


def source_brain_record(channel_id, event, amount=1, title="", reason="", save=True):
    if not SOURCE_BRAIN_ENABLED or not channel_id:
        return
    key = guard_key(channel_id)
    with state_mutex:
        brain = STATE["sync_source_manager"].setdefault("source_brain", {})
        item = brain.setdefault(key, source_brain_default(key, title=title))
        if title:
            item["title"] = title
        item["last_event"] = event
        item["updated_at"] = now_iso()
        if event == "queued":
            item["queued"] = int(item.get("queued") or 0) + amount
            item["consecutive_failures"] = 0
            item["silent_streak"] = 0
            item["last_activity_at"] = now_iso()
        elif event == "uploaded":
            item["uploaded"] = int(item.get("uploaded") or 0) + amount
            item["consecutive_failures"] = 0
            item["silent_streak"] = 0
            item["last_activity_at"] = now_iso()
        elif event == "copy_uploaded":
            item["copy_uploaded"] = int(item.get("copy_uploaded") or 0) + amount
            item["uploaded"] = int(item.get("uploaded") or 0) + amount
            item["consecutive_failures"] = 0
            item["silent_streak"] = 0
            item["last_activity_at"] = now_iso()
        elif event == "duplicate":
            item["duplicates"] = int(item.get("duplicates") or 0) + amount
        elif event in {"failed", "timeout", "access_error"}:
            item["failed"] = int(item.get("failed") or 0) + amount
            item["consecutive_failures"] = int(item.get("consecutive_failures") or 0) + amount
            item["last_error"] = str(reason)[:180]
        elif event == "dead":
            item["dead"] = int(item.get("dead") or 0) + amount
            item["failed"] = int(item.get("failed") or 0) + amount
            item["consecutive_failures"] = int(item.get("consecutive_failures") or 0) + amount
            item["last_error"] = str(reason)[:180]
        elif event == "scan_hit":
            item["scan_hits"] = int(item.get("scan_hits") or 0) + amount
            item["silent_streak"] = 0
            item["consecutive_failures"] = 0
            item["last_checked_at"] = now_iso()
        elif event == "scan_miss":
            item["scan_misses"] = int(item.get("scan_misses") or 0) + amount
            item["silent_streak"] = int(item.get("silent_streak") or 0) + 1
            item["last_checked_at"] = now_iso()
        source_brain_recalculate_score(item)
        if event in {"scan_hit", "scan_miss", "failed", "timeout", "access_error", "dead"}:
            queued = amount if event == "scan_hit" else 0
            item["next_scan_after"] = time.time() + source_brain_next_delay(item, queued=queued, event=event)
        if item.get("consecutive_failures", 0) >= SOURCE_BRAIN_FAIL_STREAK_BAD:
            item["next_scan_after"] = max(float(item.get("next_scan_after") or 0), time.time() + SOURCE_BRAIN_BAD_COOLDOWN_SECONDS)
        if save:
            save_state("sync_source_manager")


